INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb415a1b-6b9c-44a8-9b66-1ec309a4f7e2', '善哉行', '善哉行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大鵬刷翮謝溟渤，青雲萬層高突出。","下視秋濤空渺瀰，舊處魚龍皆細物。","人生在世何容易，眼濁心昏信生死。","願除嗜慾待身輕，攜手同尋列仙事。"]', '["大鵬刷翮謝溟渤，青云万層高突出。","下視秋濤空渺瀰，旧处鱼龙皆細物。","人生在世何容易，眼濁心昏信生死。","願除嗜慾待身轻，携手同尋列仙事。"]', '诗', 'shi', '', NULL, '善哉行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a731f134-b922-401c-bcab-4a07aa582166', '日日曲', '日日曲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日日東上，日日日西沒。","任是神仙容，也須成朽骨。","浮雲滅復生，芳草死還出。","不知千古萬古人，葬向青山爲底物。"]', '["日日日东上，日日日西沒。","任是神仙容，也須成朽骨。","浮云滅复生，芳草死還出。","不知千古万古人，葬向青山爲底物。"]', '诗', 'shi', '', NULL, '日日曲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d604122-86c3-4d12-aaac-ef556be82580', '耕叟', '耕叟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春風吹蓑衣，暮雨滴箬笠。","夫婦耕共勞，兒孫飢對泣。","田園高且瘦，賦稅重復急。","官倉鼠雀羣，共待新租入。"]', '["春风吹蓑衣，暮雨滴箬笠。","夫婦耕共勞，兒孫飢对泣。","田园高且瘦，賦稅重复急。","官倉鼠雀羣，共待新租入。"]', '诗', 'shi', '', NULL, '耕叟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639368bd-320d-4853-8d7b-2e08c42909b2', '苦熱行', '苦熱行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["離宮劃開赤帝怒，喝出六龍奔日馭。","下土熬熬若煎煮，蒼生惶惶無處處。","火雲崢嶸焚泬寥，東臯老農腸欲焦。","何當一雨蘇我苗，爲君擊壤歌帝堯。"]', '["離宮劃开赤帝怒，喝出六龙奔日馭。","下土熬熬若煎煮，蒼生惶惶無处处。","火云崢嶸焚泬寥，东臯老農腸欲焦。","何當一雨蘇我苗，爲君擊壤歌帝堯。"]', '诗', 'shi', '', NULL, '苦熱行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f2cb4f-fab0-49ce-8991-9dbbd48c7a32', '苦寒行', '苦寒行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["冰峰撐空寒矗矗，雲凝水凍埋海陸。","殺物之性，傷人之慾。","既不能斷絕蒺藜荆棘之根株，又不能展鳳皇麒麟之拳跼。","如此，則何如爲和煦，爲膏雨？","自然天下之榮枯，融融於萬戶。"]', '["冰峰撐空寒矗矗，云凝水凍埋海陸。","殺物之性，傷人之慾。","既不能斷絕蒺藜荆棘之根株，又不能展鳳皇麒麟之拳跼。","如此，則何如爲和煦，爲膏雨？","自然天下之榮枯，融融於万戶。"]', '诗', 'shi', '', NULL, '苦寒行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6b5b8c-4c8d-4fa9-83d7-31ad6dc6c3e8', '春風曲', '春风曲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春風有何情，旦暮來林園。","不問桃李主，吹落紅無言。"]', '["春风有何情，旦暮来林园。","不问桃李主，吹落紅無言。"]', '诗', 'shi', '', NULL, '春風曲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fee248d-4b49-4d04-a26a-f2c67f0d5bb2', '城中懷山友', '城中懷山友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春城來往桃李碧，煖豔紅香斷消息。","吾徒自有山中鄰，白晝冥心坐嵐壁。"]', '["春城来往桃李碧，煖豔紅香斷消息。","吾徒自有山中鄰，白晝冥心坐嵐壁。"]', '诗', 'shi', '', NULL, '城中懷山友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948d8473-84e1-4320-9535-3aa9c3e67210', '讀李賀歌集', '读李賀歌集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["赤水無精華，荆山亦枯槁。","玄珠與虹玉，璨璨李賀抱。","清晨醉起臨春臺，吳綾蜀錦胸襟開。","狂多兩手掀蓬萊，珊瑚掇盡空土堆。"]', '["赤水無精华，荆山亦枯槁。","玄珠與虹玉，璨璨李賀抱。","清晨醉起臨春台，吳綾蜀錦胸襟开。","狂多兩手掀蓬萊，珊瑚掇尽空土堆。"]', '诗', 'shi', '', NULL, '讀李賀歌集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d64a419e-2aff-447a-910e-6d19ad1eb089', '風琴引', '风琴引', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["挼吳絲，雕楚竹，高託天風拂爲曲。","一一宮商在素空，鸞鳴鳳語翹梧桐。","夜深天碧松風多，孤窗寒夢驚流波。","愁魂傍枕不肯去，翻疑住處鄰湘娥。","金風聲盡熏風發，冷泛虛堂韻難歇。","常恐聽多耳漸煩，清音不絕知音絕。"]', '["挼吳絲，雕楚竹，高託天风拂爲曲。","一一宮商在素空，鸾鳴鳳語翹梧桐。","夜深天碧松风多，孤窗寒梦驚流波。","愁魂傍枕不肯去，翻疑住处鄰湘娥。","金风声尽熏风發，冷泛虛堂韻难歇。","常恐听多耳漸煩，清音不絕知音絕。"]', '诗', 'shi', '', NULL, '風琴引 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bb9ae8-5811-4b43-b81f-f72cb511ab1d', '夏雲曲', '夏云曲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["紅嵯峨，爍晚波，乖龍慵臥旱鬼多。","爞爞萬里壓天塹，颺雷電光空閃閃。","好雨不雨風不風，徒倚穹蒼作巖險。","男巫女覡更走魂，焚香祝天天不聞。","天若聞，必能使爾爲潤澤，洗埃氛，而又變之成五色。","捧日輪，將以表唐堯虞舜之明君。"]', '["紅嵯峨，爍晚波，乖龙慵臥旱鬼多。","爞爞万里壓天塹，颺雷電光空閃閃。","好雨不雨风不风，徒倚穹蒼作巖險。","男巫女覡更走魂，焚香祝天天不闻。","天若闻，必能使爾爲潤澤，洗埃氛，而又变之成五色。","捧日輪，將以表唐堯虞舜之明君。"]', '诗', 'shi', '', NULL, '夏雲曲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f774df5-7c80-40d3-a546-3832227e07c0', '讀李白集', '读李白集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竭雲濤，刳巨鼇，搜括造化空牢牢。","冥心入海海神怖，驪龍不敢爲珠主。","人間物象不供取，飽飲遊神向懸圃。","鏘金鏗玉千餘篇，膾吞炙嚼人口傳。","須知一一丈夫氣，不是綺羅兒女言。"]', '["竭云濤，刳巨鼇，搜括造化空牢牢。","冥心入海海神怖，驪龙不敢爲珠主。","人间物象不供取，飽饮游神向懸圃。","鏘金鏗玉千餘篇，膾吞炙嚼人口傳。","須知一一丈夫氣，不是綺羅兒女言。"]', '诗', 'shi', '', NULL, '讀李白集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9eb025-d2dc-4aed-8cf3-3d13d745a224', '祈真壇', '祈真壇', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["玉甕瑤壇二三級，學仙弟子參差入。","霓旌隊仗下不下，松檜森森天露濕。","殿前寒氣束香雲，朝祈暮禱玄元君。","茫茫俗骨醉更昏，樓臺十二遙崑崙。","崑崙縱廣一萬二千里，中有五色雲霞五色水。","何當斷慾便飛去，不要九轉神丹換精髓。"]', '["玉甕瑤壇二三級，学仙弟子參差入。","霓旌隊仗下不下，松檜森森天露濕。","殿前寒氣束香云，朝祈暮禱玄元君。","茫茫俗骨醉更昏，楼台十二遙崑崙。","崑崙縱廣一万二千里，中有五色云霞五色水。","何當斷慾便飞去，不要九轉神丹換精髓。"]', '诗', 'shi', '', NULL, '祈真壇 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1327917-f259-4bbc-bf00-9d2abb2fe053', '黃雀行', '黄雀行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雙雙野田雀，上下同飲啄。","暖去栖蓬蒿，寒歸傍籬落。","殷勤避羅網，乍可遇鵰鶚。","鵰鶚雖不仁，分明在寥廓。"]', '["雙雙野田雀，上下同饮啄。","暖去栖蓬蒿，寒归傍籬落。","殷勤避羅網，乍可遇鵰鶚。","鵰鶚雖不仁，分明在寥廓。"]', '诗', 'shi', '', NULL, '黃雀行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c85d83-a6bb-445f-b67c-f814f29bc805', '石竹花', '石竹花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["石竹花開照庭石，紅蘚自稟離宮色。","一枝兩枝初笑風，猩猩血潑低低叢。","常嗟世眼無真鑒，却被丹青苦相陷。","誰爲根尋造化功，爲君吐出淳元膽。","白日當午方盛開，彤霞灼灼臨池臺。","繁香濃豔如未已，粉蝶遊蜂狂欲死。"]', '["石竹花开照庭石，紅蘚自稟離宮色。","一枝兩枝初笑风，猩猩血潑低低叢。","常嗟世眼無真鑒，却被丹青苦相陷。","誰爲根尋造化功，爲君吐出淳元膽。","白日當午方盛开，彤霞灼灼臨池台。","繁香濃豔如未已，粉蝶游蜂狂欲死。"]', '诗', 'shi', '', NULL, '石竹花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efd6084-78bd-4f0e-9188-942e4d7eda7c', '寄南岳白蓮道士能于長嘯', '寄南岳白蓮道士能于长嘯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["猨猱休啼月皎皎，蟋蟀不吟山悄悄。","大耳仙人滿頷鬚，醉倚長松一聲嘯。"]', '["猨猱休啼月皎皎，蟋蟀不吟山悄悄。","大耳仙人满頷鬚，醉倚长松一声嘯。"]', '诗', 'shi', '', NULL, '寄南岳白蓮道士能于長嘯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb800859-cf83-464e-8518-6ec688a1ade9', '古劒歌', '古劒歌', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["古人手中鑄神物，百鍊百淬始提出。","今人不要強硎磨，蓮鍔星文未曾沒。","一彈一撫聞錚錚，老龍影奪秋燈明。","何時得遇英雄主，用爾平治天下去。"]', '["古人手中鑄神物，百鍊百淬始提出。","今人不要強硎磨，蓮鍔星文未曾沒。","一彈一撫闻錚錚，老龙影奪秋灯明。","何时得遇英雄主，用爾平治天下去。"]', '诗', 'shi', '', NULL, '古劒歌 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a34957-ca4b-41cf-acb8-b883edcc20c4', '湘妃廟', '湘妃廟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["湘煙濛濛湘水急，汀露凝紅裛蓮濕。","蒼梧雲疊九嶷深，二女魂飛江上立。","相攜泣，鳳蓋龍輿追不及。","廟荒松朽啼飛猩，筍鞭迸出階基傾。","黃昏一岸陰風起，新月如眉生闊水。"]', '["湘煙濛濛湘水急，汀露凝紅裛蓮濕。","蒼梧云叠九嶷深，二女魂飞江上立。","相携泣，鳳蓋龙輿追不及。","廟荒松朽啼飞猩，筍鞭迸出階基傾。","黄昏一岸陰风起，新月如眉生闊水。"]', '诗', 'shi', '', NULL, '湘妃廟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('665cfbe3-194c-48bc-8c57-4ce73bb306df', '巫山高', '巫山高', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["巫山高，巫女妖。","雨爲暮兮雲爲朝，楚王顦顇魂欲銷。","秋猨嗥嗥日將夕，紅霞紫煙凝老壁。","千巖萬壑花皆坼，但恐芳菲無正色。","不知今古行人行，幾人經此無秋情。","雲深廟遠不可覓，十二峰頭插天碧。"]', '["巫山高，巫女妖。","雨爲暮兮云爲朝，楚王顦顇魂欲銷。","秋猨嗥嗥日將夕，紅霞紫煙凝老壁。","千巖万壑花皆坼，但恐芳菲無正色。","不知今古行人行，幾人經此無秋情。","云深廟远不可覓，十二峰头插天碧。"]', '诗', 'shi', '', NULL, '巫山高 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04c1a95-755d-4dab-b75e-afed4071f72f', '贈持法華經僧', '贈持法华經僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["衆人有口，不說是，即說非。","吾師有口何所爲，蓮經七軸六萬九千字。","日日夜夜終復始。","乍吟乍諷何悠揚，風篁古松含秋霜。","但恐天龍夜叉乾闥衆，㽬塞虛空耳皆聳。","我聞念經功德緣，舌根可算金剛堅。","他時劫火洞燃後，神光璨璨如紅蓮。","受持身心苟精潔，尚能使煩惱大海水枯竭。","魔王輪幢自摧折，何況更如理行如理說。"]', '["衆人有口，不说是，即说非。","吾師有口何所爲，蓮經七軸六万九千字。","日日夜夜終复始。","乍吟乍諷何悠揚，风篁古松含秋霜。","但恐天龙夜叉乾闥衆，㽬塞虛空耳皆聳。","我闻念經功德緣，舌根可算金剛堅。","他时劫火洞燃後，神光璨璨如紅蓮。","受持身心苟精潔，尚能使煩惱大海水枯竭。","魔王輪幢自摧折，何況更如理行如理说。"]', '诗', 'shi', '', NULL, '贈持法華經僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e762d167-3cc2-4aeb-8fb7-d155c8fe01c9', '刳腸龜', '刳腸龟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["爾既能於靈，應久存其生。","爾既能於瑞，胡得迷其死。","刳腸徒自屠，曳尾復何累。","可憐濮水流，一葉泛莊子。"]', '["爾既能於靈，應久存其生。","爾既能於瑞，胡得迷其死。","刳腸徒自屠，曳尾复何累。","可怜濮水流，一葉泛莊子。"]', '诗', 'shi', '', NULL, '刳腸龜 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa0991a-57b3-4ddc-a3a1-ce133f6bf93e', '贈巖居僧', '贈巖居僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["石如騏驎巖作室，秋苔漫壇淨於漆。","袈裟蓋頭心在無，黃猨白猨啼日日。"]', '["石如騏驎巖作室，秋苔漫壇淨於漆。","袈裟蓋头心在無，黄猨白猨啼日日。"]', '诗', 'shi', '', NULL, '贈巖居僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('428e82d6-21a0-4945-84af-2f1355de0b5a', '觀李瓊處士畫海濤', '观李瓊处士畫海濤', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["巨鼇轉側長鰌翻，狂濤顛浪高漫漫。","李瓊奪得造化本，都盧縮在秋毫端。","一揮一畫皆筋骨，滉漾崩騰大鯨臬。","葉撲仙槎擺欲沉，下頭應是驪龍窟。","昔年曾要涉蓬瀛，唯聞撼動珊瑚聲。","今來正歎陸沉久，見君此畫思前程。","千尋萬派功難測，海門山小濤頭白。","令人錯認錢塘城，羅剎石底奔雷霆。"]', '["巨鼇轉側长鰌翻，狂濤顛浪高漫漫。","李瓊奪得造化本，都盧縮在秋毫端。","一揮一畫皆筋骨，滉漾崩腾大鯨臬。","葉撲仙槎擺欲沉，下头應是驪龙窟。","昔年曾要涉蓬瀛，唯闻撼动珊瑚声。","今来正歎陸沉久，见君此畫思前程。","千尋万派功难測，海门山小濤头白。","令人錯認錢塘城，羅剎石底奔雷霆。"]', '诗', 'shi', '', NULL, '觀李瓊處士畫海濤 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e2da73-fcd8-4ff4-b1d3-a2bd4b468345', '昇天行', '昇天行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["身不沉，骨不重，驅青鸞，駕白鳳。","幢蓋飄搖入冷空，天風瑟瑟星河動。","瑤闕參差阿母家，樓臺戲閉凝彤霞。","三五仙子乘龍車，堂前碾爛蟠桃花。","迴頭却顧蓬萊頂，一點濃嵐在深井。"]', '["身不沉，骨不重，驱青鸾，駕白鳳。","幢蓋飄搖入冷空，天风瑟瑟星河动。","瑤闕參差阿母家，楼台戲閉凝彤霞。","三五仙子乘龙车，堂前碾爛蟠桃花。","迴头却顧蓬萊頂，一点濃嵐在深井。"]', '诗', 'shi', '', NULL, '昇天行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e869707-71c0-4268-b2c3-9e6e4f396dbc', '還人卷', '還人卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["李白李賀遺機杼，散在人間不知處。","聞君收在芙蓉江，日鬬鮫人織秋浦。","金梭劄劄文離離，吳姬越女羞上機。","鴛鴦浴煙鸞鳳飛，澄江曉映餘霞輝。","仙人手持玉刀尺，寸寸酬君珠與璧。","裁作霞裳何處披，紫皇殿裏深難覓。"]', '["李白李賀遺機杼，散在人间不知处。","闻君收在芙蓉江，日鬬鮫人织秋浦。","金梭劄劄文離離，吳姬越女羞上機。","鴛鴦浴煙鸾鳳飞，澄江晓映餘霞輝。","仙人手持玉刀尺，寸寸酬君珠與璧。","裁作霞裳何处披，紫皇殿裏深难覓。"]', '诗', 'shi', '', NULL, '還人卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9aa05ba-6c7d-4ebd-9401-5edd412f9b93', '輕薄行', '轻薄行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["玉鞭金鐙驊騮蹄，橫眉吐氣如虹霓。","五陵春暖芳草齊，笙歌到處花成泥。","日沉月上且鬬雞，醉來莫問天高低。","伯陽道德何唾咦，仲尼禮樂徒卑栖。"]', '["玉鞭金鐙驊騮蹄，橫眉吐氣如虹霓。","五陵春暖芳草齊，笙歌到处花成泥。","日沉月上且鬬雞，醉来莫问天高低。","伯陽道德何唾咦，仲尼禮乐徒卑栖。"]', '诗', 'shi', '', NULL, '輕薄行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00683cf6-9066-423f-8480-e14b39cfa8fc', '浮雲行', '浮云行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大野有賢人，大朝有聖君。","如何彼浮雲，掩蔽白日輪。","安得東南風，吹散八表外。","使之天下人，共見堯眉彩。"]', '["大野有賢人，大朝有聖君。","如何彼浮云，掩蔽白日輪。","安得东南风，吹散八表外。","使之天下人，共见堯眉彩。"]', '诗', 'shi', '', NULL, '浮雲行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af167d52-44ff-497f-aa19-c4b07c07f974', '煌煌京洛行', '煌煌京洛行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聖君垂衣裳，蕩蕩若朝旭。","大觀無遺物，四夷來率服。","清晨迴北極，紫氣蓋黃屋。","雙闕聳雙鼇，九門如川瀆。","梯山航海至，晝夜車相續。","我恐紅塵深，變爲黃河曲。"]', '["聖君垂衣裳，蕩蕩若朝旭。","大观無遺物，四夷来率服。","清晨迴北極，紫氣蓋黄屋。","雙闕聳雙鼇，九门如川瀆。","梯山航海至，晝夜车相續。","我恐紅塵深，变爲黄河曲。"]', '诗', 'shi', '', NULL, '煌煌京洛行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cf19a5-59c6-49bb-9ad8-36de23dec3eb', '弔汨羅', '弔汨羅', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["落日倚闌干，徘徊汨羅曲。","冤魂如可弔，煙浪聲似哭。","我欲考黿鼉之心，烹魚龍之腹。","爾既啖大夫之血，食大夫之肉。","千載之後，猶斯暗伏。","將謂唐堯之尊，還如荒悴之君。","更有逐臣，於焉葬魂。","得以縱其噬，[恣]其吞。"]', '["落日倚闌干，徘徊汨羅曲。","冤魂如可弔，煙浪声似哭。","我欲考黿鼉之心，烹鱼龙之腹。","爾既啖大夫之血，食大夫之肉。","千載之後，猶斯暗伏。","將謂唐堯之尊，還如荒悴之君。","更有逐臣，於焉葬魂。","得以縱其噬，[恣]其吞。"]', '诗', 'shi', '', NULL, '弔汨羅 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e5468d-90a4-4ef8-8479-f5b9ff5045d8', '贈念法華經僧', '贈念法华經僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["念念念兮入惡易，念念念兮入善難。","念經念佛能一般，愛河竭處生波瀾。","言公少年真法器，白晝不出夜不睡。","心心緣經口緣字，一室寥寥燈照地。","沈檀卷軸寶函盛，薝蔔香熏水精記。","空山木落古寺閑，松枝鶴眠霜霰乾。","牙根舌根水滴寒，珊瑚搥打紅琅玕。","但恐蓮花七朵一時折，朵朵似君心地白。","又恐天風吹天花，繽紛如雨飄袈裟。","況聞此經甚微妙，百千諸佛真祕要。","靈山說後始傳來，聞者雖多持者少。","更堪誦入陀羅尼，唐音梵音相雜時。","舜絃和雅熏風吹，文王武王絃更悲。","如此爭不遣碧空中有龍來聽，有鬼來聽，亦使人間聞者敬。","見者敬，自然心虛空，性清淨。","此經真體即毘盧，雪嶺白牛君識無。"]', '["念念念兮入惡易，念念念兮入善难。","念經念佛能一般，愛河竭处生波瀾。","言公少年真法器，白晝不出夜不睡。","心心緣經口緣字，一室寥寥灯照地。","沈檀卷軸寶函盛，薝蔔香熏水精記。","空山木落古寺闲，松枝鹤眠霜霰乾。","牙根舌根水滴寒，珊瑚搥打紅琅玕。","但恐蓮花七朵一时折，朵朵似君心地白。","又恐天风吹天花，繽紛如雨飄袈裟。","況闻此經甚微妙，百千諸佛真祕要。","靈山说後始傳来，闻者雖多持者少。","更堪誦入陀羅尼，唐音梵音相杂时。","舜絃和雅熏风吹，文王武王絃更悲。","如此爭不遣碧空中有龙来听，有鬼来听，亦使人间闻者敬。","见者敬，自然心虛空，性清淨。","此經真體即毘盧，雪嶺白牛君識無。"]', '诗', 'shi', '', NULL, '贈念法華經僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7c6379-97cb-446c-a7e5-f46ef866afe6', '短歌寄鼓山長老', '短歌寄鼓山长老', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雪峰雪峰高且雄，峨峨堆積青冥中。","六月赤日燒不鎔，飛禽瞥見人難通。","常聞中有白象王，五百象子皆威光。","行圍坐遶同一色，森森影動旃檀香。","於中一子最雄猛，稱尊獨踞鼓山頂。","百千眷屬陰□影，身照曜，吞秋景。","[我]聞岷國民歸依，前王後王皆師資。","寧同梁武遇達磨，過後彈指空傷悲。"]', '["雪峰雪峰高且雄，峨峨堆積青冥中。","六月赤日燒不鎔，飞禽瞥见人难通。","常闻中有白象王，五百象子皆威光。","行圍坐遶同一色，森森影动旃檀香。","於中一子最雄猛，稱尊独踞鼓山頂。","百千眷屬陰□影，身照曜，吞秋景。","[我]闻岷国民归依，前王後王皆師資。","寧同梁武遇達磨，過後彈指空傷悲。"]', '诗', 'shi', '', NULL, '短歌寄鼓山長老 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19ee43f1-1c4a-401c-8475-9e037360665c', '漁父', '漁父', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夜釣洞庭月，朝醉巴陵市。","却歸君山下，魚龍窟邊睡。","生涯在何處，白浪千萬里。","曾笑楚臣迷，蒼黃汨羅水。"]', '["夜釣洞庭月，朝醉巴陵市。","却归君山下，鱼龙窟邊睡。","生涯在何处，白浪千万里。","曾笑楚臣迷，蒼黄汨羅水。"]', '诗', 'shi', '', NULL, '漁父 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d931fb-2191-43a6-a02f-ab78920eeead', '採蓮曲', '採蓮曲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["越溪女，越江蓮。","齊菡萏，雙嬋娟。","嬉遊向何處，採摘且同船。","浩唱發容與，清波生漪連。","時逢島嶼泊，幾共鴛鴦眠。","襟袖既盈溢，馨香亦相傳。","薄暮歸去來，苧蘿生碧煙。"]', '["越溪女，越江蓮。","齊菡萏，雙嬋娟。","嬉游向何处，採摘且同船。","浩唱發容與，清波生漪連。","时逢島嶼泊，幾共鴛鴦眠。","襟袖既盈溢，馨香亦相傳。","薄暮归去来，苧蘿生碧煙。"]', '诗', 'shi', '', NULL, '採蓮曲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e81d4e-15be-4925-be9d-7246601c79b0', '啄木', '啄木', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["啄木啄啄，鳴林響壑。","貪心既緣，利嘴斯鑿。","有朽百尺，微蟲斯宅。","以啄去害，啄更彌劇。","層崖豫章，聳幹蒼蒼。","無縱爾啄，摧我棟梁。"]', '["啄木啄啄，鳴林响壑。","貪心既緣，利嘴斯鑿。","有朽百尺，微蟲斯宅。","以啄去害，啄更彌劇。","層崖豫章，聳幹蒼蒼。","無縱爾啄，摧我棟梁。"]', '诗', 'shi', '', NULL, '啄木 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeeac27e-9535-463e-9cd8-93c04d119f6e', '靈松歌', '靈松歌', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["靈松靈松，是何根株。","盤擗枝幹，與羣木殊。","世眼爭知蒼翠容，薜蘿遮體深朦朧。","先秋瑟瑟生谷風，青陰倒卓寒潭中。","八月天威行肅殺，萬木凋零向霜雪。","唯有此松高下枝，一枝枝在無摧折。","癡凍頑冰如鐵堅，重重鎖到槎牙顛。","老鱗枯節相把捉，踉蹌立在青崖前。","有時深洞興雷雹，飛電繞身光閃爍。","乍似蒼龍驚起時，攫霧穿雲欲騰躍。","夜深山月照高枝，疎影細落莓苔磯。","千年朽枿魍魎出，一株寒韻鏘琉璃。","安得良工妙圖雘，寫將偃蹇懸煙閣。","飛瀑聲中戰歲寒，紅霞影裏擎蕭索。"]', '["靈松靈松，是何根株。","盤擗枝幹，與羣木殊。","世眼爭知蒼翠容，薜蘿遮體深朦朧。","先秋瑟瑟生谷风，青陰倒卓寒潭中。","八月天威行肅殺，万木凋零向霜雪。","唯有此松高下枝，一枝枝在無摧折。","癡凍頑冰如鐵堅，重重鎖到槎牙顛。","老鱗枯節相把捉，踉蹌立在青崖前。","有时深洞兴雷雹，飞電繞身光閃爍。","乍似蒼龙驚起时，攫霧穿云欲腾躍。","夜深山月照高枝，疎影細落莓苔磯。","千年朽枿魍魎出，一株寒韻鏘琉璃。","安得良工妙圖雘，寫將偃蹇懸煙閣。","飞瀑声中戰歲寒，紅霞影裏擎蕭索。"]', '诗', 'shi', '', NULL, '靈松歌 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36a25a3-4a59-468a-9d23-bb252a73a578', '蠹', '蠹', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蠹不自蠹，而蠹于木。","蠹極木心，以豐爾腹。","偶或成之，胡爲勗人。","人而不真，繇爾亂神。","蠹兮蠹兮，何全其生。","無託爾形，霜松雪檉。"]', '["蠹不自蠹，而蠹于木。","蠹極木心，以豐爾腹。","偶或成之，胡爲勗人。","人而不真，繇爾亂神。","蠹兮蠹兮，何全其生。","無託爾形，霜松雪檉。"]', '诗', 'shi', '', NULL, '蠹 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25f4715-0ecf-44c1-ba86-c59b7ce4d6ba', '行路難', '行路难', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["行路難，君好看。","驚波不在黤黮間，小人心裏藏崩湍。","七盤九折寒𡺚崒，翻車倒蓋猶堪出。","未似是非脣舌危，闇中潛毀平人骨。","君不見楚靈均，千古沉冤湘水濱。","又不見李太白，一朝却作江南客。"]', '["行路难，君好看。","驚波不在黤黮间，小人心裏藏崩湍。","七盤九折寒𡺚崒，翻车倒蓋猶堪出。","未似是非脣舌危，闇中潛毀平人骨。","君不见楚靈均，千古沉冤湘水濱。","又不见李太白，一朝却作江南客。"]', '诗', 'shi', '', NULL, '行路難 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48dbd42a-33dc-4d84-a877-d4ab5bcc35f5', '謝徽上人見惠二龍障子以短歌酬之', '謝徽上人见惠二龙障子以短歌酬之', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["我見蘇州崑山金城中，金城柱上有二龍。","老僧相傳道是僧繇手，尋常入海共龍鬬。","又聞蜀國玉局觀有孫遇跡，盤屈身長八十尺。","遊人爭看不敢近，頭覻寒泉萬丈碧。","近有五羊徽上人，閑工小筆得意新。","畫龍不誇頭角及鬚鱗，只求筋骨與精神。","徽上人，真藝者。","惠我雙龍不言價，等閑不敢將懸挂。","恐是葉公好假龍，及見真龍却驚怕。"]', '["我见蘇州崑山金城中，金城柱上有二龙。","老僧相傳道是僧繇手，尋常入海共龙鬬。","又闻蜀国玉局观有孫遇跡，盤屈身长八十尺。","游人爭看不敢近，头覻寒泉万丈碧。","近有五羊徽上人，闲工小笔得意新。","畫龙不誇头角及鬚鱗，只求筋骨與精神。","徽上人，真藝者。","惠我雙龙不言價，等闲不敢將懸挂。","恐是葉公好假龙，及见真龙却驚怕。"]', '诗', 'shi', '', NULL, '謝徽上人見惠二龍障子以短歌酬之 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c70bb4-157b-403a-adec-c6a0f16d90b9', '送人往長沙', '送人往长沙', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆門歸路指湖南，千里風帆興可諳。","好聽鷓鴣啼雨處，木蘭舟晚泊春潭。"]', '["荆门归路指湖南，千里风帆兴可諳。","好听鷓鴣啼雨处，木蘭舟晚泊春潭。"]', '诗', 'shi', '', NULL, '送人往長沙 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b579d7-c425-4cb4-a241-b6fbcd6eec7f', '偶題', '偶題', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["時事嬾言多忌諱，野吟無主若縱橫。","君看三百篇章首，何處分明著姓名。"]', '["时事嬾言多忌諱，野吟無主若縱橫。","君看三百篇章首，何处分明著姓名。"]', '诗', 'shi', '', NULL, '偶題 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e7dfcb2-db62-49e8-976c-5e194f64cad1', '寄山中叟', '寄山中叟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["青泉碧樹夏風涼，紫蕨紅粳午爨香。","應笑晨持一盂苦，腥羶市裏呌家常。"]', '["青泉碧樹夏风涼，紫蕨紅粳午爨香。","應笑晨持一盂苦，腥羶市裏呌家常。"]', '诗', 'shi', '', NULL, '寄山中叟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dffab256-67f9-440c-b567-7adab89bd14f', '贈琴客', '贈琴客', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾攜五老峰前過，幾向雙松石上彈。","此境此身誰更愛，掀天羯鼓滿長安。"]', '["曾携五老峰前過，幾向雙松石上彈。","此境此身誰更愛，掀天羯鼓满长安。"]', '诗', 'shi', '', NULL, '贈琴客 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7f35ed-19af-4e03-a573-dd7fdb74de45', '勉吟僧', '勉吟僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["千途萬轍亂真源，白晝勞形夜斷魂。","忍著袈裟把名紙，學他低折五侯門。"]', '["千途万轍亂真源，白晝勞形夜斷魂。","忍著袈裟把名紙，学他低折五侯门。"]', '诗', 'shi', '', NULL, '勉吟僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0350d46-4847-4b17-b1a2-065595fb5af3', '送人歸華下', '送人归华下', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蓮花峰翠濕凝秋，舊業園林在下頭。","好束詩書且歸去，而今不愛事風流。"]', '["蓮花峰翠濕凝秋，旧業园林在下头。","好束诗书且归去，而今不愛事风流。"]', '诗', 'shi', '', NULL, '送人歸華下 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e15d6a-1494-4766-ac8d-55b186e6128e', '夏日城中作二首 一', '夏日城中作二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三面僧鄰一面牆，更無風路可吹涼。","他年捨此歸何處，青壁紅霞裹石房。"]', '["三面僧鄰一面牆，更無风路可吹涼。","他年捨此归何处，青壁紅霞裹石房。"]', '诗', 'shi', '', NULL, '夏日城中作二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef037e3-dc9b-4936-816d-6c9b766933f3', '夏日城中作二首 二', '夏日城中作二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竹低莎淺雨濛濛，水檻幽窗暑月中。","有境牽懷人不會，東林門外翠橫空。"]', '["竹低莎淺雨濛濛，水檻幽窗暑月中。","有境牽懷人不會，东林门外翠橫空。"]', '诗', 'shi', '', NULL, '夏日城中作二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a028c4a-17b0-48dc-a133-2fd04501b5e1', '默坐', '默坐', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["燈引飛蛾拂焰迷，露淋栖鶴壓枝低。","冥心坐滿蒲團穩，夢到天台過剡溪。"]', '["灯引飞蛾拂焰迷，露淋栖鹤壓枝低。","冥心坐满蒲團穩，梦到天台過剡溪。"]', '诗', 'shi', '', NULL, '默坐 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daffc4a6-8fa5-4ef9-910a-c38c6cbe4648', '水邊行', '水邊行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["身著袈裟手杖藤，水邊行止不妨僧。","禽栖日落猶孤立，隔浪秋山千萬層。"]', '["身著袈裟手杖藤，水邊行止不妨僧。","禽栖日落猶孤立，隔浪秋山千万層。"]', '诗', 'shi', '', NULL, '水邊行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c752fc70-90b0-4b80-8ebf-19d32e5d86cf', '寄鄭谷郎中', '寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["人間近遇風騷匠，鳥外曾逢心印師。","除此二門無別妙，水邊松下獨尋思。"]', '["人间近遇风騷匠，鸟外曾逢心印師。","除此二门無別妙，水邊松下独尋思。"]', '诗', 'shi', '', NULL, '寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a5bccb-12cd-4d73-a2f9-393375647012', '翡翠', '翡翠', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["水邊飛去青難辨，竹裏歸來色一般。","磨吻鷹鸇莫相害，白鷗鴻鶴滿沙灘。"]', '["水邊飞去青难辨，竹裏归来色一般。","磨吻鷹鸇莫相害，白鷗鴻鹤满沙灘。"]', '诗', 'shi', '', NULL, '翡翠 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49529bde-7ec1-45cf-80e2-ccce647137a0', '與節供奉大德遊京口寺留題', '與節供奉大德游京口寺留題', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["柳岸晴緣十里來，水邊精舍絕塵埃。","煮茶嘗摘興何極，直至殘陽未欲迴。"]', '["柳岸晴緣十里来，水邊精舍絕塵埃。","煮茶嘗摘兴何極，直至殘陽未欲迴。"]', '诗', 'shi', '', NULL, '與節供奉大德遊京口寺留題 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fffc93-d45d-4e68-880a-f7f8c2d26f62', '謝荆幕孫郎中見示樂府歌集二十八字', '謝荆幕孫郎中见示乐府歌集二十八字', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["長吉才狂太白顛，二公文陣勢橫前。","誰言後代無高手，奪得秦皇鞭鬼鞭。"]', '["长吉才狂太白顛，二公文陣勢橫前。","誰言後代無高手，奪得秦皇鞭鬼鞭。"]', '诗', 'shi', '', NULL, '謝荆幕孫郎中見示樂府歌集二十八字 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd45f048-9336-46b0-b4de-9a74b2e0e619', '謝陰符經勉送藏休上人二首 一', '謝陰符經勉送藏休上人二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["事遂鼎湖遺劒履，時來渭水擲魚竿。","欲知賢聖存亡道，自向心機反覆看。"]', '["事遂鼎湖遺劒履，时来渭水擲鱼竿。","欲知賢聖存亡道，自向心機反覆看。"]', '诗', 'shi', '', NULL, '謝陰符經勉送藏休上人二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eec4cbe-f723-402c-b0af-b064089c57d8', '謝陰符經勉送藏休上人二首 二', '謝陰符經勉送藏休上人二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一林霜雪未霑頭，爭遣藏休肯便休。","學盡世間難學事，始堪隨處任虛舟。"]', '["一林霜雪未霑头，爭遣藏休肯便休。","学尽世间难学事，始堪隨处任虛舟。"]', '诗', 'shi', '', NULL, '謝陰符經勉送藏休上人二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8834e3f2-f5e7-4000-ad41-8f9e8368b444', '幽齋偶作', '幽斋偶作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["幽院纔容箇小庭，疎篁低短不堪情。","春來猶賴鄰僧樹，時引流鶯送好聲。"]', '["幽院纔容箇小庭，疎篁低短不堪情。","春来猶賴鄰僧樹，时引流鶯送好声。"]', '诗', 'shi', '', NULL, '幽齋偶作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36121eb2-af72-4077-97d0-82d0aca03862', '贈念法華經僧', '贈念法华經僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬境心隨一念平，紅芙蓉折愛河清。","持經功力能如是，任駕白牛安穩行。"]', '["万境心隨一念平，紅芙蓉折愛河清。","持經功力能如是，任駕白牛安穩行。"]', '诗', 'shi', '', NULL, '贈念法華經僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb88719-cc4a-46d8-a61b-e1705450ae26', '對菊', '对菊', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["無豔無妖別有香，栽多不爲待重陽。","莫嫌醒眼相看過，却是真心愛澹黃。"]', '["無豔無妖別有香，栽多不爲待重陽。","莫嫌醒眼相看過，却是真心愛澹黄。"]', '诗', 'shi', '', NULL, '對菊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19007cd2-c25b-42b2-913e-51bd92d4d1b3', '閉門', '閉门', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["正是閉門爭合閉，大家開處不須開。","還防朗月清風夜，有箇詩人相訪來。"]', '["正是閉门爭合閉，大家开处不須开。","還防朗月清风夜，有箇诗人相訪来。"]', '诗', 'shi', '', NULL, '閉門 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0df7cfb-3547-4c58-a270-38d5785abff6', '勉送吳國三五新戒歸', '勉送吳国三五新戒归', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["法王遺制付仁王，難得難持劫數長。","努力只須堅守護，三千八萬是垣牆。"]', '["法王遺制付仁王，难得难持劫數长。","努力只須堅守護，三千八万是垣牆。"]', '诗', 'shi', '', NULL, '勉送吳國三五新戒歸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62126502-cb40-46c7-be87-1dd30de80e90', '夏日寄清溪道者', '夏日寄清溪道者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["老病不能求藥餌，朝昏祗是但焚燒。","不知誰爲收灰骨，[壘]石栽松傍寺橋。"]', '["老病不能求藥餌，朝昏祗是但焚燒。","不知誰爲收灰骨，[壘]石栽松傍寺橋。"]', '诗', 'shi', '', NULL, '夏日寄清溪道者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b41b2af-040f-4d19-a11e-55ae0ce4cd47', '送惠空北遊', '送惠空北游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["君向峴山遊聖境，我將何以記多才。","叮嚀墮淚碑前過，寫取斯文寄我來。"]', '["君向峴山游聖境，我將何以記多才。","叮嚀墮泪碑前過，寫取斯文寄我来。"]', '诗', 'shi', '', NULL, '送惠空北遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('790e6ce6-5aba-4ac4-a400-4dc1ea1e78c6', '寄懷歸州馬判官', '寄懷归州马判官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三年爲倅興何長，歸計應多事少忙。","又見秋風霜裛樹，滿山椒熟水雲香。"]', '["三年爲倅兴何长，归計應多事少忙。","又见秋风霜裛樹，满山椒熟水云香。"]', '诗', 'shi', '', NULL, '寄懷歸州馬判官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28693c72-4d60-4c07-86a8-6ea0bac5e3e4', '觀荷葉露珠', '观荷葉露珠', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["霏微曉露成珠顆，宛轉田田未有風。","任器方圓性終在，不妨翻覆落池中。"]', '["霏微晓露成珠顆，宛轉田田未有风。","任器方圓性終在，不妨翻覆落池中。"]', '诗', 'shi', '', NULL, '觀荷葉露珠 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09d497b-e62c-4867-a10b-763b87d96d3b', '苦熱懷玉泉寺寄仁上人', '苦熱懷玉泉寺寄仁上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["火雲如燒接蒼梧，原野煙連大澤枯。","謾費葛衫葵扇力，爭禁泉石潤肌膚。"]', '["火云如燒接蒼梧，原野煙連大澤枯。","謾費葛衫葵扇力，爭禁泉石潤肌膚。"]', '诗', 'shi', '', NULL, '苦熱懷玉泉寺寄仁上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3542b26-2054-4dd1-a0df-fc1e2cc86096', '觀盆池白蓮', '观盆池白蓮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["素萼金英歕露開，倚風凝立獨徘徊。","應思瀲灧秋池底，更有歸天伴侶來。"]', '["素萼金英歕露开，倚风凝立独徘徊。","應思瀲灧秋池底，更有归天伴侶来。"]', '诗', 'shi', '', NULL, '觀盆池白蓮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e23c10-ac2c-45c7-89c8-2bf778d5e5dd', '折楊柳詞四首 一', '折楊柳词四首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鳳樓高映綠陰陰，凝重多含雨露深。","莫謂一枝柔軟力，幾曾牽破別離心。"]', '["鳳楼高映綠陰陰，凝重多含雨露深。","莫謂一枝柔軟力，幾曾牽破別離心。"]', '诗', 'shi', '', NULL, '折楊柳詞四首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386197f4-7356-4ac7-82e6-1c38a71720a4', '折楊柳詞四首 二', '折楊柳词四首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["館娃宮畔響廊前，依託吳王養翠煙。","劒去國亡臺殿毀，却隨紅樹噪秋蟬。"]', '["館娃宮畔响廊前，依託吳王養翠煙。","劒去国亡台殿毀，却隨紅樹噪秋蟬。"]', '诗', 'shi', '', NULL, '折楊柳詞四首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ea7503-7b55-4005-a02a-95cdc9466b0d', '折楊柳詞四首 三', '折楊柳词四首 三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["穠低似中陶潛酒，軟極如傷宋玉風。","多謝將軍遶營種，翠中閑卓戰旗紅。"]', '["穠低似中陶潛酒，軟極如傷宋玉风。","多謝將軍遶營種，翠中闲卓戰旗紅。"]', '诗', 'shi', '', NULL, '折楊柳詞四首 三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975a664b-3687-47c8-917f-db76f5927c0d', '折楊柳詞四首 四', '折楊柳词四首 四', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高僧愛惜遮江寺，遊子傷殘露野橋。","爭似著行垂上苑，碧桃紅杏對搖搖。"]', '["高僧愛惜遮江寺，游子傷殘露野橋。","爭似著行垂上苑，碧桃紅杏对搖搖。"]', '诗', 'shi', '', NULL, '折楊柳詞四首 四 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b688aec9-9033-4809-9b09-6fba00df3207', '荅長沙丁秀才書', '荅长沙丁秀才书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["月月便車奔帝闕，年年貢士過荆臺。","如何三度槐花落，未見故人攜卷來。"]', '["月月便车奔帝闕，年年貢士過荆台。","如何三度槐花落，未见故人携卷来。"]', '诗', 'shi', '', NULL, '荅長沙丁秀才書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481ac4f0-7279-443d-b8a7-8161bbefa949', '戒小師', '戒小師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不肯吟詩不聽經，禪宗異岳嬾遊行。","他年白首當人問，將底言談對後生。"]', '["不肯吟诗不听經，禪宗異岳嬾游行。","他年白首當人问，將底言談对後生。"]', '诗', 'shi', '', NULL, '戒小師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610fdb00-2ee2-4368-8ad1-ec4a79f83536', '題舊拄杖', '題旧拄杖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["親採匡廬瀑布西，層崖懸壁更安梯。","攜行三十年吟伴，未有詩人□□□。"]', '["親採匡廬瀑布西，層崖懸壁更安梯。","携行三十年吟伴，未有诗人□□□。"]', '诗', 'shi', '', NULL, '題舊拄杖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de26998d-9144-4004-ab5b-d2ede7f0f9d7', '酬歐陽秀才卷', '酬歐陽秀才卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三十篇多十九章，□聲風力撼疎篁。","不堪更有精搜處，誰見蕭蕭雨夜堂。"]', '["三十篇多十九章，□声风力撼疎篁。","不堪更有精搜处，誰见蕭蕭雨夜堂。"]', '诗', 'shi', '', NULL, '酬歐陽秀才卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d09b58-c834-40f3-91f2-654f3242fe9b', '聞鴈', '闻鴈', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["瀟湘浦暖全迷鶴，邏逤川寒只有鵰。","誰向孤舟憶兄弟，坐看連鴈度橫橋。"]', '["瀟湘浦暖全迷鹤，邏逤川寒只有鵰。","誰向孤舟憶兄弟，坐看連鴈度橫橋。"]', '诗', 'shi', '', NULL, '聞鴈 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2da3ac3-7e9c-4cf6-9e28-bfab309be50b', '送高麗二僧南遊', '送高丽二僧南游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日邊鄉井別年深，中國靈蹤欲徧尋。","何處碧山逢長老，分明認取祖師心。"]', '["日邊乡井別年深，中国靈蹤欲徧尋。","何处碧山逢长老，分明認取祖師心。"]', '诗', 'shi', '', NULL, '送高麗二僧南遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f56fc20-e960-4a53-b367-e51a78699014', '謝猨皮', '謝猨皮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["貴向獵師家買得，攜來乞與坐禪牀。","不知摘月秋潭畔，曾對何人啼斷腸。"]', '["貴向獵師家買得，携来乞與坐禪牀。","不知摘月秋潭畔，曾对何人啼斷腸。"]', '诗', 'shi', '', NULL, '謝猨皮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('778e34ea-2f59-4705-b465-87953bf35736', '酬光上人', '酬光上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["禪言難後到詩言，坐石心同立月魂。","應記前秋會吟處，五更猶在老松根。"]', '["禪言难後到诗言，坐石心同立月魂。","應記前秋會吟处，五更猶在老松根。"]', '诗', 'shi', '', NULL, '酬光上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c43cce-1210-4f49-a314-5fec02c947e1', '送僧歸日本', '送僧归日本', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日東來向日西遊，一鉢閑尋徧九州。","却憶雞林本師寺，欲歸還待海風秋。"]', '["日东来向日西游，一鉢闲尋徧九州。","却憶雞林本師寺，欲归還待海风秋。"]', '诗', 'shi', '', NULL, '送僧歸日本 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a28514-343e-4fea-b5e0-4b88bcd4eabe', '庚午歲十五夜對月', '庚午歲十五夜对月', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["海澄空碧正團圓，吟想玄宗此夜寒。","玉兔有情應記得，西邊不見舊長安。"]', '["海澄空碧正團圓，吟想玄宗此夜寒。","玉兔有情應記得，西邊不见旧长安。"]', '诗', 'shi', '', NULL, '庚午歲十五夜對月 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df7eca1-7ae0-4d34-bfd7-f702f8d2ca11', '紅薔薇花', '紅薔薇花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["晴日當樓曉香歇，錦帶盤空欲成結。","鶯聲漸老柳飛時，狂風吹落猩猩血。"]', '["晴日當楼晓香歇，錦带盤空欲成結。","鶯声漸老柳飞时，狂风吹落猩猩血。"]', '诗', 'shi', '', NULL, '紅薔薇花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e848a7-3b9d-4c18-a7bb-58066e33c74a', '貽九華上人', '貽九华上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一法傳聞繼老能，九華閑臥最高層。","秋鐘盡後殘陽暝，門掩松邊雨夜燈。"]', '["一法傳闻繼老能，九华闲臥最高層。","秋鐘尽後殘陽暝，门掩松邊雨夜灯。"]', '诗', 'shi', '', NULL, '貽九華上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e0ae3c-6e96-4a01-a373-58d77de612e7', '寄賡匡圖兄弟', '寄賡匡圖兄弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["僧外閑吟樂最清，年登八十喪南荆。","風騷作者爲商確，道去碧雲爭幾程。"]', '["僧外闲吟乐最清，年登八十喪南荆。","风騷作者爲商確，道去碧云爭幾程。"]', '诗', 'shi', '', NULL, '寄賡匡圖兄弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5dc58f4-2b75-4545-aa69-af394aed671a', '句', '句', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春晴游寺客，花落閉門僧。","香傳天下口。","□貴火前名，角開香滿室，爐動綠凝鐺。","園林將向夕，風雨更吹花相思坐溪石，□□□山風。","夕照背高臺，殘鐘殘角催。","五老峰前相見時，兩無言語各揚眉。","高人愛惜藏岩裏，白甀封題寄火前。"]', '["春晴游寺客，花落閉门僧。","香傳天下口。","□貴火前名，角开香满室，爐动綠凝鐺。","园林將向夕，风雨更吹花相思坐溪石，□□□山风。","夕照背高台，殘鐘殘角催。","五老峰前相见时，兩無言語各揚眉。","高人愛惜藏岩裏，白甀封題寄火前。"]', '诗', 'shi', '', NULL, '句 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c35d057-ae49-4086-9600-5abe856c0252', '言興', '言兴', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["矻矻被吟牽，因師賈浪仙。","江山風月處，一十二三年。","雅頌在於此，浮華致那邊。","猶慚功未至，謾道近千篇。"]', '["矻矻被吟牽，因師賈浪仙。","江山风月处，一十二三年。","雅頌在於此，浮华致那邊。","猶慚功未至，謾道近千篇。"]', '诗', 'shi', '', NULL, '言興 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668250d1-7418-47c5-b787-637e247a4a14', '江上秋思', '江上秋思', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["到來江上久，誰念旅游心。","故國無秋信，鄰家有夜砧。","坐遙翻不睡，愁極却成吟。","即恐髭連鬢，還爲白所侵。"]', '["到来江上久，誰念旅游心。","故国無秋信，鄰家有夜砧。","坐遙翻不睡，愁極却成吟。","即恐髭連鬢，還爲白所侵。"]', '诗', 'shi', '', NULL, '江上秋思 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270fde6a-7957-4c84-94ec-7723a0496876', '匡山居', '匡山居', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["無才加性拙，道理合藏蹤。","是處非深遠，其山已萬重。","經時隣境戰，獨夜隔雲舂。","昨日泉中見，常魚亦化龍。"]', '["無才加性拙，道理合藏蹤。","是处非深远，其山已万重。","經时隣境戰，独夜隔云舂。","昨日泉中见，常鱼亦化龙。"]', '诗', 'shi', '', NULL, '匡山居 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f987a9a-a349-4c29-8c84-b4123e0efe52', '夷陵即事', '夷陵即事', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["不難饒白髮，相續是灘波。","避世嫌身晚，思家乞夢多。","暑衣經雪着，凍硯向陽呵。","豈謂臨岐路，還聞聖主過。"]', '["不难饒白髮，相續是灘波。","避世嫌身晚，思家乞梦多。","暑衣經雪着，凍硯向陽呵。","豈謂臨岐路，還闻聖主過。"]', '诗', 'shi', '', NULL, '夷陵即事 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56db223b-ff2e-476c-823f-94cfdbf4dd96', '紫閣隱者', '紫閣隐者', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["天高紫閣侵，隱者信沈沈。","道長年兼長，雲深草復深。","如非禪客見，即是獵人尋。","北笑長安道，埃塵古到今。"]', '["天高紫閣侵，隐者信沈沈。","道长年兼长，云深草复深。","如非禪客见，即是獵人尋。","北笑长安道，埃塵古到今。"]', '诗', 'shi', '', NULL, '紫閣隱者 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb54622e-164a-4a22-bfac-c1bde33b785b', '與陳陶處士', '與陳陶处士', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["鍾陵城外住，喻似玉沈泥。","道直貧嫌殺，神清語亦低。","雪深加酒債，春盡減詩題。","記得曾邀宿，山茶獨自攜。"]', '["鍾陵城外住，喻似玉沈泥。","道直貧嫌殺，神清語亦低。","雪深加酒債，春尽減诗題。","記得曾邀宿，山茶独自携。"]', '诗', 'shi', '', NULL, '與陳陶處士 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ca159c-233c-4139-b806-ad229af2c67a', '與王嵩隱', '與王嵩隐', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["一生吟興僻，方見業精微。","事若終難得，鄉應不易歸。","亂收西日葉，雙掩北風扉。","合國諸卿相，皆曾着布衣。"]', '["一生吟兴僻，方见業精微。","事若終难得，乡應不易归。","亂收西日葉，雙掩北风扉。","合国諸卿相，皆曾着布衣。"]', '诗', 'shi', '', NULL, '與王嵩隱 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b9e2de-f918-40a1-8268-48997009b1be', '懷陸龜蒙處士', '懷陸龟蒙处士', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["布褐東南隱，相傳繼謝敷。","高譚夫子道，靜看海山圖。","事免傷心否，碁逢敵手無。","關中花數內，獨不見菖蒲。"]', '["布褐东南隐，相傳繼謝敷。","高譚夫子道，静看海山圖。","事免傷心否，碁逢敵手無。","关中花數內，独不见菖蒲。"]', '诗', 'shi', '', NULL, '懷陸龜蒙處士 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a02387b-b2ee-418a-ba00-2ddbdd8f22d2', '寄華陰司空侍郎', '寄华陰司空侍郎', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["劒[佩]已深扃，茅爲嶽面亭。","詩猶少綺美，畫肯愛丹青。","換筆修僧史，焚香閱道經。","相邀來未得，但想鶴儀形。"]', '["劒[佩]已深扃，茅爲嶽面亭。","诗猶少綺美，畫肯愛丹青。","換笔修僧史，焚香閱道經。","相邀来未得，但想鹤儀形。"]', '诗', 'shi', '', NULL, '寄華陰司空侍郎 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fef05e6-d56f-437c-b06f-a8c111ebf80f', '送陸肱入關', '送陸肱入关', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["舟行復陸行，始得到咸京。","准擬何人口，吹噓六義名。","亂山遙減翠，叢菊早含英。","衣錦還鄉日，他時有此榮。"]', '["舟行复陸行，始得到咸京。","准擬何人口，吹噓六義名。","亂山遙減翠，叢菊早含英。","衣錦還乡日，他时有此榮。"]', '诗', 'shi', '', NULL, '送陸肱入關 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05ecb53-2f33-4175-8750-7352d6fc970f', '送劉必先', '送劉必先', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["力進憑詩業，心焦闕問安。","遠行無處易，孤立本來難。","楚月船中沒，秦星馬上殘。","明年有公道，更以命推看。"]', '["力進憑诗業，心焦闕问安。","远行無处易，孤立本来难。","楚月船中沒，秦星马上殘。","明年有公道，更以命推看。"]', '诗', 'shi', '', NULL, '送劉必先 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2375300-e087-40dc-b7b8-fdbbad0ec0ca', '寄方干處士', '寄方干处士', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["格外綴清詩，詩名獨得知。","閑居公道日，醉臥牡丹時。","海鳥和濤望，山僧帶雪期。","仍聞稱處士，聖主肯相違。"]', '["格外綴清诗，诗名独得知。","闲居公道日，醉臥牡丹时。","海鸟和濤望，山僧带雪期。","仍闻稱处士，聖主肯相違。"]', '诗', 'shi', '', NULL, '寄方干處士 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc080c4-b886-4586-9337-755823541a29', '寄劉逸士', '寄劉逸士', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["無愁無累者，偶向市朝游。","此後乘孤艇，依前入亂流。","高眠歌聖日，下釣坐清秋。","道不離方寸，而能混俗求。"]', '["無愁無累者，偶向市朝游。","此後乘孤艇，依前入亂流。","高眠歌聖日，下釣坐清秋。","道不離方寸，而能混俗求。"]', '诗', 'shi', '', NULL, '寄劉逸士 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf296377-319c-4224-85bc-c3b1b426ae8b', '送獨孤處士', '送独孤处士', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["萬里去非忙，惟攜貯藥囊。","山家消夜景，酒肆過年光。","立鶴洲侵浪，喧蛬壁近床。","誰人臨上路，乞得變髭方。"]', '["万里去非忙，惟携貯藥囊。","山家消夜景，酒肆過年光。","立鹤洲侵浪，喧蛬壁近床。","誰人臨上路，乞得变髭方。"]', '诗', 'shi', '', NULL, '送獨孤處士 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce47beba-69cd-4ac1-84dd-e84efbf2964d', '早春送人歸岳陽', '早春送人归岳陽', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["久食主人魚，春來復舊居。","遠無千里浪，輕有半船書。","過片晴雲淡，消殘暮雪虛。","岳陽多異境，搜思勿令疎。"]', '["久食主人鱼，春来复旧居。","远無千里浪，轻有半船书。","過片晴云淡，消殘暮雪虛。","岳陽多異境，搜思勿令疎。"]', '诗', 'shi', '', NULL, '早春送人歸岳陽 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5bd41e-c3ce-40d3-808b-b1ddb5c35933', '冬暮送人', '冬暮送人', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["長安冬欲盡，又送一遺賢。","醉後情渾可，言休理不然。","射衣秦嶺雪，搖月漢江船。","亦過春兼夏，回期信有蟬。"]', '["长安冬欲尽，又送一遺賢。","醉後情渾可，言休理不然。","射衣秦嶺雪，搖月漢江船。","亦過春兼夏，回期信有蟬。"]', '诗', 'shi', '', NULL, '冬暮送人 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c7e3c3-614e-4ed9-b627-81bd40ae0158', '送徐道人東游', '送徐道人东游', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["長安人擾擾，獨自有閑心。","海上山中去，風前月下吟。","引猿秋果熟，藏鶴曉雲深。","易姓更名數，難教弟子尋。"]', '["长安人擾擾，独自有闲心。","海上山中去，风前月下吟。","引猿秋果熟，藏鹤晓云深。","易姓更名數，难教弟子尋。"]', '诗', 'shi', '', NULL, '送徐道人東游 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6ecf10-61e1-474d-b619-077fb0416b08', '自紀', '自紀', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["諸機忘盡未忘詩，似向詩中有所依。","遠境等閑支枕覓，空山容易杖藜歸。","清猿一一居林叫，白鳥雙雙避釣飛。","欲畫淨名居士像，焚香願見陸探微。"]', '["諸機忘尽未忘诗，似向诗中有所依。","远境等闲支枕覓，空山容易杖藜归。","清猿一一居林叫，白鸟雙雙避釣飞。","欲畫淨名居士像，焚香願见陸探微。"]', '诗', 'shi', '', NULL, '自紀 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d750b9a-016e-49c1-8d37-3c37f10cc091', '懷智栖上人', '懷智栖上人', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["臨水登山自有期，不同游子暮何之。","閑眠默坐身堪賞，已去還來事可知。","林鳥隔雲飛一餉，草蟲和雨叫多時。","思君最易令人老，倚檻空吟所寄詩。"]', '["臨水登山自有期，不同游子暮何之。","闲眠默坐身堪賞，已去還来事可知。","林鸟隔云飞一餉，草蟲和雨叫多时。","思君最易令人老，倚檻空吟所寄诗。"]', '诗', 'shi', '', NULL, '懷智栖上人 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff4ae18-fb4a-4d28-b73c-9682000095db', '峽中酬荆南鄭準', '峽中酬荆南鄭準', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["山齋西向蜀江濆，四載安居復有羣。","風雁勢高猶可見，雪猿聲苦不堪聞。","新詩寫出難勝寶，破衲披行却類雲。","每喜泝流賓客說，元瑜刀筆潤雄軍。"]', '["山斋西向蜀江濆，四載安居复有羣。","风雁勢高猶可见，雪猿声苦不堪闻。","新诗寫出难勝寶，破衲披行却類云。","每喜泝流賓客说，元瑜刀笔潤雄軍。"]', '诗', 'shi', '', NULL, '峽中酬荆南鄭準 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e8facb-79ed-4258-974f-97412c4786a5', '寄荆門鄭準', '寄荆门鄭準', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["傳衣傳鉢理難論，綺靡銷磨二雅尊。","不許姓名留月觀，終攜瓶錫去雲門。","窗間挂燭通宵在，竹上題詩隔歲存。","珍重荆門鄭從事，十年同受景升恩。"]', '["傳衣傳鉢理难論，綺靡銷磨二雅尊。","不許姓名留月观，終携瓶錫去云门。","窗间挂燭通宵在，竹上題诗隔歲存。","珍重荆门鄭從事，十年同受景升恩。"]', '诗', 'shi', '', NULL, '寄荆門鄭準 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b39770e-4aa5-46f9-ae2c-e145a51e31a9', '將欲再游荆渚留辭岐下司徒', '將欲再游荆渚留辞岐下司徒', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["竹錫銅瓶配衲衣，殷公樓畔偶然離。","白蓮幾看從開日，明月長吟到落時。","活計本無桑柘潤，疎慵尋有水雲資。","今朝回去精神別，爲得頭廳宰相詩。"]', '["竹錫銅瓶配衲衣，殷公楼畔偶然離。","白蓮幾看從开日，明月长吟到落时。","活計本無桑柘潤，疎慵尋有水云資。","今朝回去精神別，爲得头廳宰相诗。"]', '诗', 'shi', '', NULL, '將欲再游荆渚留辭岐下司徒 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9637703-529c-416a-afbe-7085bf658799', '贈村公', '贈村公', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["紬衣木突此鄉尊，白盡鬚眉眼未昏。","醉舞神筵隨鼓笛，閑歌聖代和兒孫。","黍苗一頃垂秋日，茅棟三間映古原。","也笑長安名利處，紅塵半是馬蹄翻。"]', '["紬衣木突此乡尊，白尽鬚眉眼未昏。","醉舞神筵隨鼓笛，闲歌聖代和兒孫。","黍苗一頃垂秋日，茅棟三间映古原。","也笑长安名利处，紅塵半是马蹄翻。"]', '诗', 'shi', '', NULL, '贈村公 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a65a08-50dd-4e8f-acaa-7e535932e6df', '秋夜吟', '秋夜吟', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["梧桐雨畔夜愁吟，抖擻衣裾蘚色侵。","枉道一生無繫着，湘南山水別人尋。"]', '["梧桐雨畔夜愁吟，抖擻衣裾蘚色侵。","枉道一生無繫着，湘南山水別人尋。"]', '诗', 'shi', '', NULL, '秋夜吟 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76398943-d3fe-4e9e-9d04-e40410c1d561', '讀齊己上人集', '读齊己上人集', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["詩爲儒者禪，此格的惟仙。","古雅如周頌，清和甚舜弦。","冰生聽瀑句，香發早梅篇。","想得吟成夜，文星照楚天。"]', '["诗爲儒者禪，此格的惟仙。","古雅如周頌，清和甚舜弦。","冰生听瀑句，香發早梅篇。","想得吟成夜，文星照楚天。"]', '诗', 'shi', '', NULL, '讀齊己上人集 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ebd9ca3-ea82-4f6a-9017-5275f8915a79', '除夜', '除夜', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["九冬三十夜，寒與暖分開。","坐到四更後，身添一歲來。","魚燈延臘火，獸炭化春灰。","青帝今應老，迎新見幾迴。"]', '["九冬三十夜，寒與暖分开。","坐到四更後，身添一歲来。","鱼灯延臘火，獸炭化春灰。","青帝今應老，迎新见幾迴。"]', '诗', 'shi', '', NULL, '除夜 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b57220-2acf-4fad-b544-64f28c051c33', '送人歸鄉', '送人归乡', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["多才與命違，末路憶柴扉。","白髮何人問，青山一劒歸。","晴煙獨鳥沒，野渡亂花飛。","寂寞長亭外，依然空落暉。"]', '["多才與命違，末路憶柴扉。","白髮何人问，青山一劒归。","晴煙独鸟沒，野渡亂花飞。","寂寞长亭外，依然空落暉。"]', '诗', 'shi', '', NULL, '送人歸鄉 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07818486-2e99-4c98-8c4e-896a92f9ed0c', '述懷 一', '述懷 一', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["青門聊極望，何事久離羣。","芳草失歸路，故鄉空暮雲。","信回陵樹老，夢斷灞流分。","兄弟正南北，鴻聲堪獨聞。"]', '["青门聊極望，何事久離羣。","芳草失归路，故乡空暮云。","信回陵樹老，梦斷灞流分。","兄弟正南北，鴻声堪独闻。"]', '诗', 'shi', '', NULL, '述懷 一 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d54be8-d5d8-4baa-adc6-3a7788a27172', '述懷 二', '述懷 二', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["五城初罷構，海上憶閑行。","觸雪麻衣靜，登山竹錫輕。","天寒嶽寺出，日晚島泉清。","坐與幽期遇，何湖心渺冥。"]', '["五城初罷構，海上憶闲行。","觸雪麻衣静，登山竹錫轻。","天寒嶽寺出，日晚島泉清。","坐與幽期遇，何湖心渺冥。"]', '诗', 'shi', '', NULL, '述懷 二 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9927f7a8-e7d8-48a3-aea9-081eabd53655', '宿壽安甘棠館 一', '宿壽安甘棠館 一', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["行人方倦役，到此似還鄉。","流水來關外，青山近洛陽。","溪雲歸洞鶴，松月半軒霜。","坐恐晨鐘動，天涯道路長。"]', '["行人方倦役，到此似還乡。","流水来关外，青山近洛陽。","溪云归洞鹤，松月半軒霜。","坐恐晨鐘动，天涯道路长。"]', '诗', 'shi', '', NULL, '宿壽安甘棠館 一 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc5037f-583f-4dda-889c-888c18a3acf2', '宿壽安甘棠館 二', '宿壽安甘棠館 二', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["山空蕙氣香，乳管折雲房。","願值壺中客，親傳肘後方。","三更禮星斗，寸匕服丹霜。","默坐樹陰下，仙經橫石床。"]', '["山空蕙氣香，乳管折云房。","願值壺中客，親傳肘後方。","三更禮星斗，寸匕服丹霜。","默坐樹陰下，仙經橫石床。"]', '诗', 'shi', '', NULL, '宿壽安甘棠館 二 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ce0374-406e-4ee3-8e70-ef99c119d190', '送朴山人歸新羅', '送朴山人归新羅', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["浩渺行無極，揚帆但信風。","雲山過海半，鄉樹入舟中。","波定遙天出，沙平遠岸窮。","離心寄何處，目擊曙霞東。"]', '["浩渺行無極，揚帆但信风。","云山過海半，乡樹入舟中。","波定遙天出，沙平远岸窮。","離心寄何处，目擊曙霞东。"]', '诗', 'shi', '', NULL, '送朴山人歸新羅 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4b533f-e0ad-4e1f-a492-aa0b45d28482', '宿清遠峽山寺', '宿清远峽山寺', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["寺近朝天路，多聞玉佩音。","鑒人開慧眼，歸鳥息禪心。","磬接星河曙，窗連夏木深。","此中能宴坐，何必在雲林。"]', '["寺近朝天路，多闻玉佩音。","鑒人开慧眼，归鸟息禪心。","磬接星河曙，窗連夏木深。","此中能宴坐，何必在云林。"]', '诗', 'shi', '', NULL, '宿清遠峽山寺 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687d1418-a6b6-4ff4-b446-44e5bd9935d8', '松山嶺', '松山嶺', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["平生閑放久，野鹿許爲羣。","居止隣西嶽，軒窗度白雲。","齋心飯松子，話道接茅君。","漢主恩情去，空山起夕氛。"]', '["平生闲放久，野鹿許爲羣。","居止隣西嶽，軒窗度白云。","斋心飯松子，話道接茅君。","漢主恩情去，空山起夕氛。"]', '诗', 'shi', '', NULL, '松山嶺 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273368a8-8c26-4736-bf01-939f582685f8', '句', '句', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["浸浸三楚白，渺渺九江寒。"]', '["浸浸三楚白，渺渺九江寒。"]', '诗', 'shi', '', NULL, '句 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08c14bd-385a-4be6-a954-c5d106110edc', '泊洞庭', '泊洞庭', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["槐柳未知秋，依依舘驛頭。","客心俱念遠，時雨自相留。","浪沒貨魚市，帆高賣酒樓。","夜來思展轉，故里在南州。"]', '["槐柳未知秋，依依舘驛头。","客心俱念远，时雨自相留。","浪沒貨鱼市，帆高賣酒楼。","夜来思展轉，故里在南州。"]', '诗', 'shi', '', NULL, '泊洞庭 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cafa341-07c3-4071-9069-1f77081c28e3', '善卷壇', '善卷壇', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["耕荒鑿原時，高趣在希夷。","大舜欲遜國，先生空歛眉。","五溪清不足，千古美無虧。","縱遣亡淳者，何人投所思。"]', '["耕荒鑿原时，高趣在希夷。","大舜欲遜国，先生空歛眉。","五溪清不足，千古美無虧。","縱遣亡淳者，何人投所思。"]', '诗', 'shi', '', NULL, '善卷壇 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34345b1e-92d4-4713-933b-d9d0bdbba149', '石城金谷', '石城金谷', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["晉祚一傾摧，驕奢去不回。","只應荆棘地，猶作綺羅灰。","狐兔閑生長，樵蘇靜往來。","踟躕意無盡，寒日又西頹。"]', '["晉祚一傾摧，驕奢去不回。","只應荆棘地，猶作綺羅灰。","狐兔闲生长，樵蘇静往来。","踟躕意無尽，寒日又西頹。"]', '诗', 'shi', '', NULL, '石城金谷 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9715cfbe-8ab3-44e0-90d0-a80c382a94de', '庾樓', '庾楼', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["郡樓名甚遠，幾換見樓人。","庾亮魂應在，清風到白蘋。","晴軒分楚漢，夜酒揖星辰。","何必匡山上，獨言無世塵。"]', '["郡楼名甚远，幾換见楼人。","庾亮魂應在，清风到白蘋。","晴軒分楚漢，夜酒揖星辰。","何必匡山上，独言無世塵。"]', '诗', 'shi', '', NULL, '庾樓 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1064f15-c3f7-42e8-8c82-0f03743437b7', '經賀監舊居', '經賀監旧居', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["不戀明皇寵，歸來鏡水隅。","道裝汀鶴識，春醉釣人扶。","逐朵雲如吐，成行雁侶驅。","蘭亭名景在，蹤跡未爲孤。"]', '["不戀明皇寵，归来镜水隅。","道裝汀鹤識，春醉釣人扶。","逐朵云如吐，成行雁侶驱。","蘭亭名景在，蹤跡未爲孤。"]', '诗', 'shi', '', NULL, '經賀監舊居 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4b05c6-98bc-4e70-bf01-9d26f3cca3b6', '獻鄭都官', '獻鄭都官', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["早晚辭班列，歸尋舊隱峰。","代移家集在，身老詔書重。","藥秘仙都訣，茶開蜀國封。","何當荅羣望，高躡傅巖蹤。"]', '["早晚辞班列，归尋旧隐峰。","代移家集在，身老詔书重。","藥秘仙都訣，茶开蜀国封。","何當荅羣望，高躡傅巖蹤。"]', '诗', 'shi', '', NULL, '獻鄭都官 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b49788-12e5-42b3-9662-387e0e252805', '寄華山司空圖二首 一', '寄华山司空圖二首 一', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["門徑放莎垂，往來投刺稀。","有時開御札，特地掛朝衣。","嶽信僧傳去，仙香鶴帶歸。","他年二南化，無復更衰微。"]', '["门徑放莎垂，往来投刺稀。","有时开御札，特地掛朝衣。","嶽信僧傳去，仙香鹤带归。","他年二南化，無复更衰微。"]', '诗', 'shi', '', NULL, '寄華山司空圖二首 一 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b316389-b872-4912-ae40-10058b633bfa', '寄華山司空圖二首 二', '寄华山司空圖二首 二', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["逍遙短褐成，一劒動精靈。","白晝夢仙島，清晨禮道經。","黍苗侵野徑，桑椹汚閑庭。","肯要爲隣者，西南太華青。"]', '["逍遙短褐成，一劒动精靈。","白晝梦仙島，清晨禮道經。","黍苗侵野徑，桑椹汚闲庭。","肯要爲隣者，西南太华青。"]', '诗', 'shi', '', NULL, '寄華山司空圖二首 二 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65085bd6-6bb6-43e3-8816-4b1d7b7084cb', '贈屏風巖栖蟾上人', '贈屏风巖栖蟾上人', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["巖房高且靜，住此幾寒暄。","鹿嗅安禪石，猿啼乞食村。","朝陽生樹罅，古路透雲根。","獨我閑相覓，淒涼碧洞門。"]', '["巖房高且静，住此幾寒暄。","鹿嗅安禪石，猿啼乞食村。","朝陽生樹罅，古路透云根。","独我闲相覓，淒涼碧洞门。"]', '诗', 'shi', '', NULL, '贈屏風巖栖蟾上人 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52cbb85b-45a7-44d2-ae18-bf18fbe9b776', '贈秀才', '贈秀才', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["筠陽多勝致，夫子縱游遨。","鳳鳥瑞不見，鱸魚價轉高。","門開沙觜靜，船繫樹根牢。","誰解伊人趣，村沽對鬱陶。"]', '["筠陽多勝致，夫子縱游遨。","鳳鸟瑞不见，鱸鱼價轉高。","门开沙觜静，船繫樹根牢。","誰解伊人趣，村沽对鬱陶。"]', '诗', 'shi', '', NULL, '贈秀才 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b887966-6c20-4f5f-9c18-d4aead5c6517', '送遷客', '送遷客', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["倏忽墮鵷行，天南去路長。","片言曾不諂，獲罪亦何傷。","象戀藏牙浦，人貪賣子鄉。","此心終合雪，去已莫思量。"]', '["倏忽墮鵷行，天南去路长。","片言曾不諂，獲罪亦何傷。","象戀藏牙浦，人貪賣子乡。","此心終合雪，去已莫思量。"]', '诗', 'shi', '', NULL, '送遷客 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f47c3d0-21eb-48ca-80da-94baa2fa5ccc', '哭悼朝賢', '哭悼朝賢', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["前昨回私第，旋聞寢疾終。","四隣方響絕，二月牡丹空。","冢已遷名境，碑仍待至公。","秪應遺愛理，長在楚南風。"]', '["前昨回私第，旋闻寢疾終。","四隣方响絕，二月牡丹空。","冢已遷名境，碑仍待至公。","秪應遺愛理，长在楚南风。"]', '诗', 'shi', '', NULL, '哭悼朝賢 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936c1ba5-e210-4f7c-a1b2-ccc6791b9b31', '悼方干處士', '悼方干处士', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["先生在世日，秪向鏡湖居。","明主未巡狩，白頭閑釣魚。","煙莎一徑小，洲島四隣疎。","獨有爲儒者，時來弔舊廬。"]', '["先生在世日，秪向镜湖居。","明主未巡狩，白头闲釣鱼。","煙莎一徑小，洲島四隣疎。","独有爲儒者，时来弔旧廬。"]', '诗', 'shi', '', NULL, '悼方干處士 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc4cc6f-de8f-4666-a268-96e926fb8644', '聽軒轅先生琴', '听軒轅先生琴', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["訣妙與功精，通宵膝上橫。","一堂風冷淡，千古意分明。","坐客禪魂凝，巢禽耳目傾。","酷哉商紂世，曾不遇先生。"]', '["訣妙與功精，通宵膝上橫。","一堂风冷淡，千古意分明。","坐客禪魂凝，巢禽耳目傾。","酷哉商紂世，曾不遇先生。"]', '诗', 'shi', '', NULL, '聽軒轅先生琴 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec985f9-1def-4e04-8129-5690c355ac5c', '芳草', '芳草', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["綿綿芳草綠，何處動深思。","金谷人亡後，沙塲日暖時。","龍鱗藏有瑞，風雨灑無私。","欲採蘭兼蕙，清香可贈誰。"]', '["綿綿芳草綠，何处动深思。","金谷人亡後，沙塲日暖时。","龙鱗藏有瑞，风雨灑無私。","欲採蘭兼蕙，清香可贈誰。"]', '诗', 'shi', '', NULL, '芳草 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebe1586-9399-45d2-a42f-168cab2fff0d', '句', '句', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["喜魚在深處，幽鳥立多時。","菖蒲花不豔，鸜鵒性多靈。","盤中是祥瑞，天下恰炎蒸。","待暖還須去，門前有路岐。","春雨無高下，花枝有短長。","老負峨眉月，閑看雲水心。"]', '["喜鱼在深处，幽鸟立多时。","菖蒲花不豔，鸜鵒性多靈。","盤中是祥瑞，天下恰炎蒸。","待暖還須去，门前有路岐。","春雨無高下，花枝有短长。","老負峨眉月，闲看云水心。"]', '诗', 'shi', '', NULL, '句 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd04194c-ad1c-4635-a9cc-0c057f1f6bcc', '短歌行', '短歌行', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["蟾光堪自笑，浮世懶思量。","身得幾時活，眼開終日忙。","千門無壽藥，一鏡有愁霜。","早向塵埃外，光陰任短長。"]', '["蟾光堪自笑，浮世懶思量。","身得幾时活，眼开終日忙。","千门無壽藥，一镜有愁霜。","早向塵埃外，光陰任短长。"]', '诗', 'shi', '', NULL, '短歌行 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1925c281-86a5-43e5-a464-a07c8c30f866', '除夜', '除夜', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["九冬三十夜，寒與暖分開。","坐到四更後，身添一歲來。","魚燈延臘火，獸炭化春灰。","青帝今應老，迎新見幾回。"]', '["九冬三十夜，寒與暖分开。","坐到四更後，身添一歲来。","鱼灯延臘火，獸炭化春灰。","青帝今應老，迎新见幾回。"]', '诗', 'shi', '', NULL, '除夜 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a717944f-1652-4184-a9b8-bdd48f413328', '宿巴江', '宿巴江', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["江聲五十里，瀉碧急于弦。","不覺日又夜，爭教人少年。","一汀巫峽月，兩岸子規天。","山影似相伴，濃遮到曉船。"]', '["江声五十里，瀉碧急于弦。","不覺日又夜，爭教人少年。","一汀巫峽月，兩岸子規天。","山影似相伴，濃遮到晓船。"]', '诗', 'shi', '', NULL, '宿巴江 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ab3ff3-26f6-43b3-ac55-dfc56341a970', '游邊', '游邊', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["邊雲四顧濃，飢馬嗅枯叢。","萬里八九月，一身西北風。","偷營天正黑，戰地雪多紅。","昨夜東歸夢，桃花煖色中。"]', '["邊云四顧濃，飢马嗅枯叢。","万里八九月，一身西北风。","偷營天正黑，戰地雪多紅。","昨夜东归梦，桃花煖色中。"]', '诗', 'shi', '', NULL, '游邊 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba7be46f-15f0-497d-ba81-7e731c6b8fc2', '居南嶽懷沈彬', '居南嶽懷沈彬', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["石房開竹扉，茗外獨支頤。","萬木還無葉，百年能幾時。","隔雲聞狖過，截雨見虹垂。","因憶嶽南客，晏眠吟好詩。"]', '["石房开竹扉，茗外独支頤。","万木還無葉，百年能幾时。","隔云闻狖過，截雨见虹垂。","因憶嶽南客，晏眠吟好诗。"]', '诗', 'shi', '', NULL, '居南嶽懷沈彬 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd631736-f18f-45dd-a65a-2c61d5785bd9', '南中懷友生', '南中懷友生', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["荔枝江上立，望北幾思量。","隔海無書劄，前年在漢陽。","瘴村人起早，銅柱象揩光。","居此成何事，尋君過碧湘。"]', '["荔枝江上立，望北幾思量。","隔海無书劄，前年在漢陽。","瘴村人起早，銅柱象揩光。","居此成何事，尋君過碧湘。"]', '诗', 'shi', '', NULL, '南中懷友生 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fff94eb7-4c7c-43f2-9d0a-9ff2c66a2186', '贈南嶽玄泰布衲', '贈南嶽玄泰布衲', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["曹溪入室人，終老甚難羣。","四十餘年內，青山與白雲。","松和巢鶴看，果共野猨分。","海外僧來說，名高自小聞。"]', '["曹溪入室人，終老甚难羣。","四十餘年內，青山與白云。","松和巢鹤看，果共野猨分。","海外僧来说，名高自小闻。"]', '诗', 'shi', '', NULL, '贈南嶽玄泰布衲 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97cea944-7823-436d-a241-3801ab018d2d', '寄問政山聶威儀', '寄问政山聶威儀', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["先生臥碧岑，諸祖是知音。","得道無一法，孤雲同寸心。","嵐光薰鶴詔，茶味敵人參。","苦向壺中去，他年許我尋。"]', '["先生臥碧岑，諸祖是知音。","得道無一法，孤云同寸心。","嵐光薰鹤詔，茶味敵人參。","苦向壺中去，他年許我尋。"]', '诗', 'shi', '', NULL, '寄問政山聶威儀 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('946c715d-44c6-4899-8744-ba71b4a36f6e', '送遷客', '送遷客', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["諫頻甘得罪，一騎入南深。","若順吾皇意，即無臣子心。","織花蠻市布，擣月象州砧。","蒙雪知何日，凭樓望北吟。"]', '["諫頻甘得罪，一騎入南深。","若順吾皇意，即無臣子心。","织花蠻市布，擣月象州砧。","蒙雪知何日，凭楼望北吟。"]', '诗', 'shi', '', NULL, '送遷客 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f73f990-4a4d-4e94-b59e-06654888b990', '讀齊己上人集', '读齊己上人集', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["詩爲儒者禪，此格的惟仙。","古雅如周頌，清和甚舜弦。","冰生聽瀑句，香發早梅篇。","想得吟成夜，文星照楚天。"]', '["诗爲儒者禪，此格的惟仙。","古雅如周頌，清和甚舜弦。","冰生听瀑句，香發早梅篇。","想得吟成夜，文星照楚天。"]', '诗', 'shi', '', NULL, '讀齊己上人集 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159a79d5-d709-4258-9a7d-47ec058cc11e', '牧童', '牧童', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["牛得自由騎，春風細雨飛。","青山青草裏，一笛一蓑衣。","日出唱歌去，月明撫掌歸。","何人得似爾，無是亦無非。"]', '["牛得自由騎，春风細雨飞。","青山青草裏，一笛一蓑衣。","日出唱歌去，月明撫掌归。","何人得似爾，無是亦無非。"]', '诗', 'shi', '', NULL, '牧童 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4462d7aa-576b-4b06-b2b9-12a0b8fe725a', '再宿京口禪院', '再宿京口禪院', '19390c66-fb2c-476c-8fc0-a8a60518e76d', '唐', '["灘聲依舊水溶溶，岸影參差對梵宮。","楚樹七回凋舊葉，江人兩至宿秋風。","蟾蜍竹老搖疎白，菡萏池乾落碎紅。","多病支郎念行止，晚年生計轉如蓬。"]', '["灘声依旧水溶溶，岸影參差对梵宮。","楚樹七回凋旧葉，江人兩至宿秋风。","蟾蜍竹老搖疎白，菡萏池乾落碎紅。","多病支郎念行止，晚年生計轉如蓬。"]', '诗', 'shi', '', NULL, '再宿京口禪院 棲蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4caea753-1511-4f21-9ef2-f87486b87b20', '耕田鼓詩', '耕田鼓诗', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["農舍田頭鼓，王孫筵上鼓。","擊鼓兮皆爲鼓，一何樂兮一何苦。","上有烈日，下有焦土。","願我天翁，降之以雨。","令桑麻熟，倉箱富。","不飢不寒，上下一般。"]', '["農舍田头鼓，王孫筵上鼓。","擊鼓兮皆爲鼓，一何乐兮一何苦。","上有烈日，下有焦土。","願我天翁，降之以雨。","令桑麻熟，倉箱富。","不飢不寒，上下一般。"]', '诗', 'shi', '', NULL, '耕田鼓詩 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f5d8ee-f575-48be-b551-2dfd9c3db937', '賦洞庭', '賦洞庭', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["周極八百里，凝眸望則勞。","水涵天影闊，山拔地形高。","賈客停非久，漁翁轉幾遭。","颯然風起處，又是鼓波濤。"]', '["周極八百里，凝眸望則勞。","水涵天影闊，山拔地形高。","賈客停非久，漁翁轉幾遭。","颯然风起处，又是鼓波濤。"]', '诗', 'shi', '', NULL, '賦洞庭 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8135987e-407b-4790-a56c-951db9cdf4d7', '贈方干', '贈方干', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["盛名傳出自皇州，一舉參差便縮頭。","月裏豈無攀桂分，湖中剛愛釣魚休。","童偷詩藁呈鄰叟，客乞書題謁郡侯。","獨泛短舟何限景，波濤西接洞庭秋。"]', '["盛名傳出自皇州，一舉參差便縮头。","月裏豈無攀桂分，湖中剛愛釣鱼休。","童偷诗藁呈鄰叟，客乞书題謁郡侯。","独泛短舟何限景，波濤西接洞庭秋。"]', '诗', 'shi', '', NULL, '贈方干 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('907611ce-a590-422e-af15-4681d72c2a43', '桐花鳥', '桐花鸟', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["五色毛衣比鳳雛，深花叢裏祗如無。","美人買得偏憐惜，移向金釵重幾銖。"]', '["五色毛衣比鳳雛，深花叢裏祗如無。","美人買得偏怜惜，移向金釵重幾銖。"]', '诗', 'shi', '', NULL, '桐花鳥 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41d4a79-10ef-45b6-80a1-ff2b0e754d9c', '句', '句', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["來多不似客，坐久却垂簾。","虹收千嶂雨，潮展半江天。","詩因試客分題僻，棊爲饒人下著低。","傷心盡日有啼鳥，獨步殘春空落花。","唯陪北楚三千客，多話東林十八賢。","乍當暖景飛仍慢，欲就芳叢舞更高。"]', '["来多不似客，坐久却垂簾。","虹收千嶂雨，潮展半江天。","诗因試客分題僻，棊爲饒人下著低。","傷心尽日有啼鸟，独步殘春空落花。","唯陪北楚三千客，多話东林十八賢。","乍當暖景飞仍慢，欲就芳叢舞更高。"]', '诗', 'shi', '', NULL, '句 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f87fd39b-48c1-4744-9007-492620647204', '宿鄭諫議山居', '宿鄭諫議山居', 'a01e7db2-b546-406a-bec1-601d1daba132', '唐', '["堂開星斗邊，大諫採薇還。","禽隱石中樹，月生池上山。","涼風吹詠思，幽語隔禪關。","莫擬歸城計，終妨此地閑。"]', '["堂开星斗邊，大諫採薇還。","禽隐石中樹，月生池上山。","涼风吹詠思，幽語隔禪关。","莫擬归城計，終妨此地闲。"]', '诗', 'shi', '', NULL, '宿鄭諫議山居 曇域 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('166fd5fa-a55f-4ef6-b03d-7ad19fb07857', '懷齊己', '懷齊己', 'a01e7db2-b546-406a-bec1-601d1daba132', '唐', '["鬢髯秋景兩蒼蒼，靜對茅齋一炷香。","病後身心俱澹泊，老來朋友半凋傷。","峨眉山色侵雲直，巫峽灘聲入夜長。","猶喜深交有支遁，時時音信到松房。"]', '["鬢髯秋景兩蒼蒼，静对茅斋一炷香。","病後身心俱澹泊，老来朋友半凋傷。","峨眉山色侵云直，巫峽灘声入夜长。","猶喜深交有支遁，时时音信到松房。"]', '诗', 'shi', '', NULL, '懷齊己 曇域 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62819c51-0ce0-4d87-8093-6bdbed30aa84', '贈島雲禪師', '贈島云禪師', 'a01e7db2-b546-406a-bec1-601d1daba132', '唐', '["遠庵枯葉滿，羣鹿亦相隨。","頂骨生新髮，庭松長舊枝。","禪高太白月，行出祖師碑。","亂後潛來此，南人總不知。"]', '["远庵枯葉满，羣鹿亦相隨。","頂骨生新髮，庭松长旧枝。","禪高太白月，行出祖師碑。","亂後潛来此，南人總不知。"]', '诗', 'shi', '', NULL, '贈島雲禪師 曇域 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a8fb60-2a91-43ec-8b27-0b5ed1939f24', '垓下懷古', '垓下懷古', 'e5ab67f0-acd2-4589-a627-37624a6afb6d', '唐', '["緬想咸陽事可嗟，楚歌哀怨思無涯。","八千子弟歸何處，萬里鴻溝屬漢家。","弓指陣前爭日月，血流垓下定龍蛇。","拔山力盡烏江水，今古悠悠空浪花。"]', '["緬想咸陽事可嗟，楚歌哀怨思無涯。","八千子弟归何处，万里鴻溝屬漢家。","弓指陣前爭日月，血流垓下定龙蛇。","拔山力尽烏江水，今古悠悠空浪花。"]', '诗', 'shi', '', NULL, '垓下懷古 栖一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb001d8b-9f57-43b4-884a-2cd5d29f44ea', '武昌懷古', '武昌懷古', 'e5ab67f0-acd2-4589-a627-37624a6afb6d', '唐', '["戰國城池盡悄然，昔人遺迹遍山川。","笙歌罷吹幾多日，臺榭荒涼七百年。","蟬響夕陽風滿樹，雁橫秋島雨漫天。","堪嗟世事如流水，空見蘆花一釣船。"]', '["戰国城池尽悄然，昔人遺迹遍山川。","笙歌罷吹幾多日，台榭荒涼七百年。","蟬响夕陽风满樹，雁橫秋島雨漫天。","堪嗟世事如流水，空见蘆花一釣船。"]', '诗', 'shi', '', NULL, '武昌懷古 栖一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b8805d-725e-42d5-9eab-60ad0f580982', '聖果寺', '聖果寺', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["路自中峰上，盤回出薜蘿。","到江吳地盡，隔岸越山多。","古木叢青靄，遙天浸白波。","下方城郭近，鐘磬雜笙歌。"]', '["路自中峰上，盤回出薜蘿。","到江吳地尽，隔岸越山多。","古木叢青靄，遙天浸白波。","下方城郭近，鐘磬杂笙歌。"]', '诗', 'shi', '', NULL, '聖果寺 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e371a6ae-c713-4bc9-823f-c29f940d22a3', '送僧游西域', '送僧游西域', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["一盂兼一錫，秪此度流沙。","野性雖爲客，禪心即是家。","寺披雲嶠雪，路入曉天霞。","自說游諸國，回應歲月賒。"]', '["一盂兼一錫，秪此度流沙。","野性雖爲客，禪心即是家。","寺披云嶠雪，路入晓天霞。","自说游諸国，回應歲月賒。"]', '诗', 'shi', '', NULL, '送僧游西域 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbef36be-4107-49c7-a04d-44aed14f192e', '遠煙', '远煙', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["靄靄前山上，凝光滿薜蘿。","高風吹不盡，遠樹得偏多。","翠與晴雲合，輕將淑氣和。","正堪流野目，朱閣意如何。"]', '["靄靄前山上，凝光满薜蘿。","高风吹不尽，远樹得偏多。","翠與晴云合，轻將淑氣和。","正堪流野目，朱閣意如何。"]', '诗', 'shi', '', NULL, '遠煙 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1cd574-9e71-4128-aeaa-0c61cea4a307', '螢', '螢', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["熠熠與娟娟，池塘竹樹邊。","亂飛如拽火，成聚却無煙。","微雨灑不滅，輕風吹欲燃。","昔時書案上，頻把作囊懸。"]', '["熠熠與娟娟，池塘竹樹邊。","亂飞如拽火，成聚却無煙。","微雨灑不滅，轻风吹欲燃。","昔时书案上，頻把作囊懸。"]', '诗', 'shi', '', NULL, '螢 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9094d5-7bb7-4867-811c-83ac4449dcd7', '憶廬山舊居', '憶廬山旧居', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["麤衣糲食老煙霞，勉把衰顏惜歲華。","獨鶴秪爲山客伴，閑雲常在野僧家。","叢生嫩蕨黏松粉，自落乾薪帶蘚花。","明月清風舊相得，十年歸恨可能賒。"]', '["麤衣糲食老煙霞，勉把衰顏惜歲华。","独鹤秪爲山客伴，闲云常在野僧家。","叢生嫩蕨黏松粉，自落乾薪带蘚花。","明月清风旧相得，十年归恨可能賒。"]', '诗', 'shi', '', NULL, '憶廬山舊居 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cfa4e3f-a3b0-4db7-9caa-08e2d8efb25d', '題棲霞寺僧房', '題棲霞寺僧房', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["名山不取買山錢，任構花宮近碧巔。","松檜老依雲裏寺，樓臺深鎖洞中天。","風經絕嶂回疎雨，石倚危屏挂落泉。","欲結茅菴共師住，肯饒多少薜蘿煙。"]', '["名山不取買山錢，任構花宮近碧巔。","松檜老依云裏寺，楼台深鎖洞中天。","风經絕嶂回疎雨，石倚危屏挂落泉。","欲結茅菴共師住，肯饒多少薜蘿煙。"]', '诗', 'shi', '', NULL, '題棲霞寺僧房 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd92c23c-af43-4f85-a310-31fd3b15ba63', '山中作', '山中作', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["席簾高捲枕高攲，門掩垂蘿蘸碧溪。","閑把史書眠一覺，起來山日過松西。"]', '["席簾高捲枕高攲，门掩垂蘿蘸碧溪。","闲把史书眠一覺，起来山日過松西。"]', '诗', 'shi', '', NULL, '山中作 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df95f1da-9e42-4f3b-b34b-50e23b3b0d86', '織婦', '织婦', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["蓬鬢蓬門積恨多，夜闌燈下不停梭。","成縑猶自陪錢納，未直青樓一曲歌。"]', '["蓬鬢蓬门積恨多，夜闌灯下不停梭。","成縑猶自陪錢納，未直青楼一曲歌。"]', '诗', 'shi', '', NULL, '織婦 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021259c6-3fb7-4e1e-9fce-17b453c4e106', '句', '句', '5814e145-f829-4e87-a05d-baa99c491450', '唐', '["太平時節無人看，雪刃閑封滿匣塵。"]', '["太平时節無人看，雪刃闲封满匣塵。"]', '诗', 'shi', '', NULL, '句 處默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f6bfb2-a329-465b-82b5-75400f5ecfd4', '秋日閑居', '秋日闲居', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["是事不相關，誰人似此閑。","卷簾當白晝，移榻對青山。","野鶴眠松上，秋苔長雨間。","岳僧頻有信，昨日得書還。"]', '["是事不相关，誰人似此闲。","卷簾當白晝，移榻对青山。","野鹤眠松上，秋苔长雨间。","岳僧頻有信，昨日得书還。"]', '诗', 'shi', '', NULL, '秋日閑居 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15234a58-dec1-45d7-9e3a-e06a1484b1c7', '宿岳陽開元寺', '宿岳陽开元寺', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["竟夕憑虛檻，何當興歎頻。","往來人自老，今古月常新。","風逆沈魚唱，松疎露鶴身。","無眠鐘又動，幾客在迷津。"]', '["竟夕憑虛檻，何當兴歎頻。","往来人自老，今古月常新。","风逆沈鱼唱，松疎露鹤身。","無眠鐘又动，幾客在迷津。"]', '诗', 'shi', '', NULL, '宿岳陽開元寺 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1aa3c81-c47f-4201-bfe0-d85f933fd671', '送邊將', '送邊將', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["人盡有離別，而君獨可嗟。","言將身報國，敢望祿榮家。","戰思風吹野，鄉心月照沙。","歸期定何日，塞北樹無花。"]', '["人尽有離別，而君独可嗟。","言將身報国，敢望祿榮家。","戰思风吹野，乡心月照沙。","归期定何日，塞北樹無花。"]', '诗', 'shi', '', NULL, '送邊將 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d806b2e-0e90-4790-9aa8-1bd34ebd186b', '雪中送人北遊', '雪中送人北游', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["然知心去速，其奈雪飛頻。","莫喜無危道，雖平更陷人。","遠郊光接漢，曠野色通秦。","此去迢遙極，却回應過春。"]', '["然知心去速，其奈雪飞頻。","莫喜無危道，雖平更陷人。","远郊光接漢，曠野色通秦。","此去迢遙極，却回應過春。"]', '诗', 'shi', '', NULL, '雪中送人北遊 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ce7c9c-eab7-4d70-ac69-4bf7cf7db5a7', '落葉', '落葉', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["雨過閑田地，重重落葉紅。","翻思向春日，肯信有秋風。","幾處隨流水，河邊亂暮空。","秪應松自立，而不與君同。"]', '["雨過闲田地，重重落葉紅。","翻思向春日，肯信有秋风。","幾处隨流水，河邊亂暮空。","秪應松自立，而不與君同。"]', '诗', 'shi', '', NULL, '落葉 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb09df72-3dd3-4c98-8296-d3add5beec30', '落花', '落花', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["一片又一片，等閑苔面紅。","不能延數日，開亦是春風。","公子歌聲歇，詩人眼界空。","遙思故山下，經雨兩三叢。"]', '["一片又一片，等闲苔面紅。","不能延數日，开亦是春风。","公子歌声歇，诗人眼界空。","遙思故山下，經雨兩三叢。"]', '诗', 'shi', '', NULL, '落花 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e0cc50d-f64b-4f34-81f3-82162a0e5797', '題田道者院', '題田道者院', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["入門空寂寂，真箇出家兒。","有行鬼不見，無心人謂癡。","古巖寒柏對，流水落花隨。","欲別一何嬾，相從所恨遲。"]', '["入门空寂寂，真箇出家兒。","有行鬼不见，無心人謂癡。","古巖寒柏对，流水落花隨。","欲別一何嬾，相從所恨遲。"]', '诗', 'shi', '', NULL, '題田道者院 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecedbedb-0105-4c06-b1e2-6d228fcc1d66', '東林寺', '东林寺', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["欲去不忍去，徘徊吟繞廊。","水光秋澹蕩，僧好語尋常。","碑古苔文疊，山晴鐘韻長。","翻思南嶽上，欠此白蓮香。"]', '["欲去不忍去，徘徊吟繞廊。","水光秋澹蕩，僧好語尋常。","碑古苔文叠，山晴鐘韻长。","翻思南嶽上，欠此白蓮香。"]', '诗', 'shi', '', NULL, '東林寺 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc9b01a-1d32-4f48-8e6e-57608d18727e', '寄貫休上人', '寄貫休上人', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["常語亦關詩，常流安得知。","楚郊來未久，吳地住多時。","立月無人近，歸林有鶴隨。","所居渾不遠，相識偶然遲。"]', '["常語亦关诗，常流安得知。","楚郊来未久，吳地住多时。","立月無人近，归林有鹤隨。","所居渾不远，相識偶然遲。"]', '诗', 'shi', '', NULL, '寄貫休上人 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e58ff3-3798-41fb-a24c-cf426ac6a448', '喜僧友到', '喜僧友到', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["十年消息斷，空使夢煙蘿。","嵩嶽幾時下，洞庭何日過。","瓶乾離澗久，衲壞臥雲多。","意欲相留住，游方肯舍麽。"]', '["十年消息斷，空使梦煙蘿。","嵩嶽幾时下，洞庭何日過。","瓶乾離澗久，衲壞臥云多。","意欲相留住，游方肯舍麽。"]', '诗', 'shi', '', NULL, '喜僧友到 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5432009-d47e-4967-a3cf-a69df2097e82', '懷虛中上人', '懷虛中上人', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["簷雨滴更殘，思君安未安。","湘川聞不遠，道路去尋難。","吟鬢霜應蝕，禪衣雪漸寒。","倚松因獨立，一鳥下江干。"]', '["簷雨滴更殘，思君安未安。","湘川闻不远，道路去尋难。","吟鬢霜應蝕，禪衣雪漸寒。","倚松因独立，一鸟下江干。"]', '诗', 'shi', '', NULL, '懷虛中上人 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d6f59f-c5e9-41c3-b50d-425a27118e22', '簡寂觀', '簡寂观', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["正同高士坐煙霞，思著閑忙又是嗟。","碧岫觀中人似鶴，紅塵路上事如麻。","石肥滯雨添蒼蘚，松老涵風落翠花。","莫道此間無我分，遺民長在惠持家。"]', '["正同高士坐煙霞，思著闲忙又是嗟。","碧岫观中人似鹤，紅塵路上事如麻。","石肥滯雨添蒼蘚，松老涵风落翠花。","莫道此间無我分，遺民长在惠持家。"]', '诗', 'shi', '', NULL, '簡寂觀 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b2822b-c3a2-4131-b389-a26a669cbf34', '睡起作', '睡起作', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["長空秋雨歇，睡起覺精神。","看水看山坐，無名無利身。","偈吟諸祖意，茶碾去年春。","此外誰相識，孤雲到砌頻。"]', '["长空秋雨歇，睡起覺精神。","看水看山坐，無名無利身。","偈吟諸祖意，茶碾去年春。","此外誰相識，孤云到砌頻。"]', '诗', 'shi', '', NULL, '睡起作 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9286f193-d032-4fa3-bfe4-0be15744c9eb', '賣松者', '賣松者', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["求利有何限，將松入市來。","直饒人買去，也向柳邊栽。","細葉猶粘雪，孤根尚惹苔。","知君用心錯，舉世重花開。"]', '["求利有何限，將松入市来。","直饒人買去，也向柳邊栽。","細葉猶粘雪，孤根尚惹苔。","知君用心錯，舉世重花开。"]', '诗', 'shi', '', NULL, '賣松者 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048b5ca3-0baa-44d1-866a-57ba47125a58', '思齊己上人', '思齊己上人', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["同人與流俗，相謂好襟靈。","有口不他說，長年自誦經。","水聲秋後石，山色晚來庭。","客問修何法，指松千歲青。"]', '["同人與流俗，相謂好襟靈。","有口不他说，长年自誦經。","水声秋後石，山色晚来庭。","客问修何法，指松千歲青。"]', '诗', 'shi', '', NULL, '思齊己上人 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f86afd-654a-4ad9-9716-1c4b159ddbe4', '送玄泰禪師', '送玄泰禪師', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["去去去何住，一盂兼一瓶。","水邊寒草白，島外晚峰青。","宿處林聞虎，行時天有星。","回期誰可定，浮世重看經。"]', '["去去去何住，一盂兼一瓶。","水邊寒草白，島外晚峰青。","宿处林闻虎，行时天有星。","回期誰可定，浮世重看經。"]', '诗', 'shi', '', NULL, '送玄泰禪師 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f0adc7-ea5d-485d-b09b-8e8845044975', '三生石', '三生石', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["聖迹誰會得，每到亦徘徊。","一尚不可得，三從何處來。","清宵寒露滴，白晝野雲隈。","應是表靈異，凡情安可猜。"]', '["聖迹誰會得，每到亦徘徊。","一尚不可得，三從何处来。","清宵寒露滴，白晝野云隈。","應是表靈異，凡情安可猜。"]', '诗', 'shi', '', NULL, '三生石 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f020c2a1-d202-4922-bce4-387eeeea7cd4', '題僧夢微房', '題僧梦微房', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["東海日未出，九衢人已行。","吾師無事坐，苔蘚入門生。","雨過閑花落，風來古木聲。","天台頻說法，石壁欠題名。"]', '["东海日未出，九衢人已行。","吾師無事坐，苔蘚入门生。","雨過闲花落，风来古木声。","天台頻说法，石壁欠題名。"]', '诗', 'shi', '', NULL, '題僧夢微房 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d7f357-1554-43a4-8688-3bd027cadc36', '秋臺作', '秋台作', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["獨上高樓上，客情何物同。","孤雲無定處，長日信秋風。","兄弟多年別，關河此夕中。","到頭歸去是，免使歎洪濛。"]', '["独上高楼上，客情何物同。","孤云無定处，长日信秋风。","兄弟多年別，关河此夕中。","到头归去是，免使歎洪濛。"]', '诗', 'shi', '', NULL, '秋臺作 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18463c2e-0730-4b72-8214-c8448f6b8566', '懷故園', '懷故园', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["故園歸未得，此日意何傷。","獨坐水邊草，水流春日長。"]', '["故园归未得，此日意何傷。","独坐水邊草，水流春日长。"]', '诗', 'shi', '', NULL, '懷故園 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079143ac-83f5-48e4-8fc9-40297701aa69', '謝武肅王', '謝武肅王', '50ab162c-ee5c-4053-9181-cb86072221e9', '唐', '["雲鶴性孤單，爭堪名利關。","銜恩雖入國，辭命却歸山。"]', '["云鹤性孤單，爭堪名利关。","銜恩雖入国，辞命却归山。"]', '诗', 'shi', '', NULL, '謝武肅王 無作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639b3939-c861-43d4-8228-8765fc97b9f8', '哭僧', '哭僧', '258624ef-c93e-4949-8bbf-ebe1da44385b', '唐', '["道力自超然，身亡同坐禪。","水流元在海，月落不離天。","溪白葬時雪，風香焚處煙。","世人頻下淚，不見我師玄。"]', '["道力自超然，身亡同坐禪。","水流元在海，月落不離天。","溪白葬时雪，风香焚处煙。","世人頻下泪，不见我師玄。"]', '诗', 'shi', '', NULL, '哭僧 清尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fd575b-1bc3-4bc2-ae45-8bab9fc348d0', '投謁齊己', '投謁齊己', '46ffe641-a255-47bb-af99-1dc763aa3866', '唐', '["隔岸紅塵忙似火，當軒青嶂冷如冰。","烹茶童子休相問，報道門前是衲僧。"]', '["隔岸紅塵忙似火，當軒青嶂冷如冰。","烹茶童子休相问，報道门前是衲僧。"]', '诗', 'shi', '', NULL, '投謁齊己 乾康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dff6459-89b1-4569-8bb1-394183e706e3', '賦殘雪', '賦殘雪', '46ffe641-a255-47bb-af99-1dc763aa3866', '唐', '["六出奇花已住開，郡城相次見樓臺。","時人莫把和泥看，一片飛從天上來。"]', '["六出奇花已住开，郡城相次见楼台。","时人莫把和泥看，一片飞從天上来。"]', '诗', 'shi', '', NULL, '賦殘雪 乾康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84914311-08ad-4d7f-b270-96b68e642831', '句', '句', '46ffe641-a255-47bb-af99-1dc763aa3866', '唐', '["鏡湖中有月，處士後無人。","荻笋抽高節，鱸魚躍老鱗。"]', '["镜湖中有月，处士後無人。","荻笋抽高節，鱸鱼躍老鱗。"]', '诗', 'shi', '', NULL, '句 乾康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36721980-a020-45b3-a6c5-aef15ffeac13', '招隱', '招隐', '17cc8cb5-a701-4e22-96b4-5c3e5342ec0f', '唐', '["連峰數千里，修林帶平津。","雲起遠山翳，風至□荒榛。","茅茨隱不見，雞鳴知有人。","躡磴踐其跡，處處見遺薪。","乃知百代下，固有上皇民。"]', '["連峰數千里，修林带平津。","云起远山翳，风至□荒榛。","茅茨隐不见，雞鳴知有人。","躡磴踐其跡，处处见遺薪。","乃知百代下，固有上皇民。"]', '诗', 'shi', '', NULL, '招隱 曇翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff1c567-fdc9-4074-a407-5e924babb4c3', '石橋琪樹', '石橋琪樹', 'a0c4e781-634f-4965-a48b-3eb8cbf7eca5', '唐', '["山上天將近，人間路漸遙。","誰當雲裏見，知欲渡仙橋。"]', '["山上天將近，人间路漸遙。","誰當云裏见，知欲渡仙橋。"]', '诗', 'shi', '', NULL, '石橋琪樹 隱求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('468989a5-0c33-488a-ab49-05d65c5444e0', '律僧', '律僧', '0c72b354-ebdd-4213-8236-ceb0e585b552', '唐', '["濾水與龕燈，長長護有情。","自從青草出，便不下階行。","北闕應無夢，南山舊有名。","將何喻浮世，惟指浪漚輕。"]', '["濾水與龕灯，长长護有情。","自從青草出，便不下階行。","北闕應無梦，南山旧有名。","將何喻浮世，惟指浪漚轻。"]', '诗', 'shi', '', NULL, '律僧 智遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bec8a074-2a1c-4859-a40e-24e878910fff', '暮春送人', '暮春送人', '035c51dc-700a-4c36-bdc9-c08214ec2a41', '唐', '["折柳亭邊手重攜，江煙澹澹草萋萋。","杜鵑不解離人意，更向落花枝上啼。"]', '["折柳亭邊手重携，江煙澹澹草萋萋。","杜鵑不解離人意，更向落花枝上啼。"]', '诗', 'shi', '', NULL, '暮春送人 無悶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a09c6e-99bd-4d5d-8bb5-a55d580673be', '寒林石屏', '寒林石屏', '035c51dc-700a-4c36-bdc9-c08214ec2a41', '唐', '["草堂無物伴身閑，惟有屏風枕簟間。","本向他山求得石，却於石上看他山。"]', '["草堂無物伴身闲，惟有屏风枕簟间。","本向他山求得石，却於石上看他山。"]', '诗', 'shi', '', NULL, '寒林石屏 無悶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a5c02f2-ba1a-4d02-938e-99c57e580258', '江上秋志', '江上秋志', '54842866-1344-4b5c-aaa0-b48d784be656', '唐', '["到來江上久，誰念旅游心。","故國無秋信，隣家有暮砧。","坐遙翻不睡，愁極却成吟。","即恐髭連鬢，還爲白所侵。"]', '["到来江上久，誰念旅游心。","故国無秋信，隣家有暮砧。","坐遙翻不睡，愁極却成吟。","即恐髭連鬢，還爲白所侵。"]', '诗', 'shi', '', NULL, '江上秋志 尚志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fada1a94-40e4-4c5a-a484-febb24eb2e78', '路', '路', '11c2e3c3-fcf9-4cb5-a52c-1e13c144a905', '唐', '["南北東西去，茫茫萬古塵。","關河無盡處，風雪有行人。","險極山通蜀，平多地入秦。","營營名利者，來往豈辭頻。"]', '["南北东西去，茫茫万古塵。","关河無尽处，风雪有行人。","險極山通蜀，平多地入秦。","營營名利者，来往豈辞頻。"]', '诗', 'shi', '', NULL, '路 玄寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2fd0f8-90e3-4790-94ba-7714cca5905d', '贈智舟三藏', '贈智舟三藏', '277bdb64-8fd6-4e06-a56a-2ec41990ab44', '唐', '["壯歲心難伏，師心伏豈難。","尋常獨在院，行坐不離壇。","岳雪當禪暝，松聲入咒寒。","更因文字外，多把史書看。"]', '["壯歲心难伏，師心伏豈难。","尋常独在院，行坐不離壇。","岳雪當禪暝，松声入咒寒。","更因文字外，多把史书看。"]', '诗', 'shi', '', NULL, '贈智舟三藏 懷浦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c10bec-1587-4264-9821-0c16864d5f01', '初冬旅舍早懷', '初冬旅舍早懷', '277bdb64-8fd6-4e06-a56a-2ec41990ab44', '唐', '["枕上角聲微，離情未息機。","夢回三楚寺，寒入五更衣。","月沒棲禽動，霜晴凍葉飛。","自慙行役早，深與道相違。"]', '["枕上角声微，離情未息機。","梦回三楚寺，寒入五更衣。","月沒棲禽动，霜晴凍葉飞。","自慙行役早，深與道相違。"]', '诗', 'shi', '', NULL, '初冬旅舍早懷 懷浦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f270a1-676f-4385-a33e-2d4b7db7be5e', '對御書後一絕', '对御书後一絕', 'dc03c6b5-fa5a-438f-a704-e995f8f725c0', '唐', '["通神筆法得玄門，親入長安謁至尊。","莫怪出來多意氣，草書曾悅聖明君。"]', '["通神笔法得玄门，親入长安謁至尊。","莫怪出来多意氣，草书曾悅聖明君。"]', '诗', 'shi', '', NULL, '對御書後一絕 亞棲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec2fee7-6e47-4f44-b57e-f3c4c40ceef5', '題英禪師', '題英禪師', 'dc03c6b5-fa5a-438f-a704-e995f8f725c0', '唐', '["將知德行異尋常，每見持經在道場。","欲識用心精潔處，一瓶秋水一爐香。"]', '["將知德行異尋常，每见持經在道場。","欲識用心精潔处，一瓶秋水一爐香。"]', '诗', 'shi', '', NULL, '題英禪師 亞棲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5455b735-c6e9-4a0b-ba42-b9222d745bf9', '別友人', '別友人', '6c291c2c-7bcb-467f-b451-fef0fdaa3d00', '唐', '["一身無定處，萬里獨銷魂。","芳草迷歸路，春衣滴淚痕。","幾時休旅食，向夜宿江村。","欲識異鄉苦，空山啼暮猨。"]', '["一身無定处，万里独銷魂。","芳草迷归路，春衣滴泪痕。","幾时休旅食，向夜宿江村。","欲識異乡苦，空山啼暮猨。"]', '诗', 'shi', '', NULL, '別友人 惟審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('011b8349-5bb4-4515-8c7c-15d806536c9d', '賦得聞曉鶯啼', '賦得闻晓鶯啼', '6c291c2c-7bcb-467f-b451-fef0fdaa3d00', '唐', '["捲簾清夢後，芳樹引流鶯。","隔葉傳春意，穿花送曉聲。","未調雲路翼，空負桂枝情。","莫盡關關興，羇愁正厭生。"]', '["捲簾清梦後，芳樹引流鶯。","隔葉傳春意，穿花送晓声。","未調云路翼，空負桂枝情。","莫尽关关兴，羇愁正厭生。"]', '诗', 'shi', '', NULL, '賦得聞曉鶯啼 惟審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1b26f2-0a5d-4b77-80ee-91f44dead780', '春日旅懷呈知己', '春日旅懷呈知己', '6c291c2c-7bcb-467f-b451-fef0fdaa3d00', '唐', '["生涯萬事有蒼蒼，應任流萍便越鄉。","春水獨行人漸遠，故園歸夢夜空長。","一聲隔浦猨啼處，數滴驚心淚滿裳。","不爲知音皆鮑叔，信誰江上去茫茫。"]', '["生涯万事有蒼蒼，應任流萍便越乡。","春水独行人漸远，故园归梦夜空长。","一声隔浦猨啼处，數滴驚心泪满裳。","不爲知音皆鲍叔，信誰江上去茫茫。"]', '诗', 'shi', '', NULL, '春日旅懷呈知己 惟審 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898882b9-127f-4f74-9b98-f5258036076e', '劒客', '劒客', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["去住知何處，空將一劒行。","殺人雖取次，爲事愛公平。","戟立嗔髭鬢，星流忿眼睛。","曉來湘市說，拂曙別遼城。"]', '["去住知何处，空將一劒行。","殺人雖取次，爲事愛公平。","戟立嗔髭鬢，星流忿眼睛。","晓来湘市说，拂曙別遼城。"]', '诗', 'shi', '', NULL, '劒客 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb994ba4-7e85-41f6-886f-95cb38771e7d', '酬和友人見寄', '酬和友人见寄', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["勞歌好自看，終久偶齊桓。","五字若教易，一名爭得難。","侵窓紅樹老，蔭砌雪花殘。","莫効齊僚屬，東歸翦釣竿。"]', '["勞歌好自看，終久偶齊桓。","五字若教易，一名爭得难。","侵窓紅樹老，蔭砌雪花殘。","莫効齊僚屬，东归翦釣竿。"]', '诗', 'shi', '', NULL, '酬和友人見寄 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495e2566-51a4-4aa0-ae50-8868e1942ddd', '冬日淮上別文上人', '冬日淮上別文上人', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["家國各萬里，同吟六七年。","可堪隨北雁，迢遰向南天。","水共行人遠，山將落日連。","春淮有雙鯉，莫忘尺書傳。"]', '["家国各万里，同吟六七年。","可堪隨北雁，迢遰向南天。","水共行人远，山將落日連。","春淮有雙鯉，莫忘尺书傳。"]', '诗', 'shi', '', NULL, '冬日淮上別文上人 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1379e014-4fd6-49dc-b247-f0da2f901ee2', '柳', '柳', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["今古憑君一贈行，幾回折盡復重生。","五株斜傍淵明宅，千樹低垂太尉營。","臨水帶煙藏翡翠，倚風兼雨宿流鶯。","隋皇隄畔依依在，曾惹當時歌吹聲。"]', '["今古憑君一贈行，幾回折尽复重生。","五株斜傍淵明宅，千樹低垂太尉營。","臨水带煙藏翡翠，倚风兼雨宿流鶯。","隋皇隄畔依依在，曾惹當时歌吹声。"]', '诗', 'shi', '', NULL, '柳 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27869dc6-5d63-42a1-879c-8f59d7cb8d13', '三峽聞猨', '三峽闻猨', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["誰向茲來不恨生，聲聲都是斷腸聲。","七千里外一家住，十二峰前獨自行。","瘴雨晚藏神女廟，蠻煙寒鎖夜郎城。","憑君且聽哀吟好，會待青雲道路平。"]', '["誰向茲来不恨生，声声都是斷腸声。","七千里外一家住，十二峰前独自行。","瘴雨晚藏神女廟，蠻煙寒鎖夜郎城。","憑君且听哀吟好，會待青云道路平。"]', '诗', 'shi', '', NULL, '三峽聞猨 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5c8257-7977-4e22-b1ae-0f9eeba6c10e', '燈', '灯', '802cf69a-c935-4ad7-a0fc-d610cd2eab59', '唐', '["鐘斷危樓鳥不飛，熒熒何處最相宜。","香然水寺僧開卷，筆寫春幃客著詩。","忽爾思多穿壁處，偶然心盡斷纓時。","孫康勤苦誰能念，少減餘光借與伊。"]', '["鐘斷危楼鸟不飞，熒熒何处最相宜。","香然水寺僧开卷，笔寫春幃客著诗。","忽爾思多穿壁处，偶然心尽斷纓时。","孫康勤苦誰能念，少減餘光借與伊。"]', '诗', 'shi', '', NULL, '燈 慕幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2976c300-2c2e-4853-8603-bfe0feba7b6e', '寶琴', '寶琴', '2cf66e5b-0db7-46e7-bbdd-21c4ecf2a101', '唐', '["吾有一寶琴，價重雙南金。","刻作龍鳳象，彈爲山水音。","星從徽裏發，風來弦上吟。","鍾期不可遇，誰辨曲中心。"]', '["吾有一寶琴，價重雙南金。","刻作龙鳳象，彈爲山水音。","星從徽裏發，风来弦上吟。","鍾期不可遇，誰辨曲中心。"]', '诗', 'shi', '', NULL, '寶琴 釋彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848877f9-a8d2-43eb-890d-ba7cbad2426a', '觀大駕出敘事寄懷', '观大駕出敘事寄懷', '7f48b583-e373-40ea-b060-cebac8cae691', '唐', '["紫臺宵漏竭，青門曙鼓通。","輕霞照複道，徐吹轉相風。","玉鸞光萬騎，金輿鬱五戎。","鳴笳猶度闕，清蹕尚喧宮。","雲旗亂陌紫，羽斾雜塵紅。","百城歸北麗，兩漢久慚雄。","吾曹陋薄技，餘慶洽微躬。","平原已起洛，印手亦還豐。","得奉衣冠盛，仍觀書軌同。","猶言待封告，未忍向華嵩。"]', '["紫台宵漏竭，青门曙鼓通。","轻霞照複道，徐吹轉相风。","玉鸾光万騎，金輿鬱五戎。","鳴笳猶度闕，清蹕尚喧宮。","云旗亂陌紫，羽斾杂塵紅。","百城归北丽，兩漢久慚雄。","吾曹陋薄技，餘慶洽微躬。","平原已起洛，印手亦還豐。","得奉衣冠盛，仍观书軌同。","猶言待封告，未忍向华嵩。"]', '诗', 'shi', '', NULL, '觀大駕出敘事寄懷 法輪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102a90fd-ea23-4952-841e-ea1790ad20da', '中秋旅懷', '中秋旅懷', '36eb9888-6b77-45a3-aa02-0895adb3e8ce', '唐', '["所畜惟騷雅，兼之得固窮。","望鄉連北斗，聽雨帶西風。","稼穡村坊遠，煙波路逕通。","冥搜清絕句，恰似有神功。"]', '["所畜惟騷雅，兼之得固窮。","望乡連北斗，听雨带西风。","稼穡村坊远，煙波路逕通。","冥搜清絕句，恰似有神功。"]', '诗', 'shi', '', NULL, '中秋旅懷 尚能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7381d894-f04d-4e34-b9e1-ca73a9464ebd', '句', '句', '36eb9888-6b77-45a3-aa02-0895adb3e8ce', '唐', '["霜洲楓落盡，月館竹生寒。"]', '["霜洲楓落尽，月館竹生寒。"]', '诗', 'shi', '', NULL, '句 尚能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b0385a-7165-484b-afcc-d827c4cd4223', '題伍相廟', '題伍相廟', 'a86f86a9-7ada-40ca-9731-23a74bad62b8', '唐', '["蒼蒼古廟映林巒，漠漠煙霞覆古壇。","精魄不知何處在，威風猶入浙江寒。"]', '["蒼蒼古廟映林巒，漠漠煙霞覆古壇。","精魄不知何处在，威风猶入浙江寒。"]', '诗', 'shi', '', NULL, '題伍相廟 常雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c650469-d210-4636-95ee-35d61db64c52', '懷舊山', '懷旧山', 'c34f9a31-a340-4b15-be19-da2a9c3f87d4', '唐', '["一坐西林寺，從來未下山。","不因尋長者，無事到人間。","宿雨愁爲客，寒花笑未還。","空懷舊山月，童子誦經閑。"]', '["一坐西林寺，從来未下山。","不因尋长者，無事到人间。","宿雨愁爲客，寒花笑未還。","空懷旧山月，童子誦經闲。"]', '诗', 'shi', '', NULL, '懷舊山 滄浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2798a0f7-37cc-4f0a-ab07-142f30060b4c', '題慧山泉', '題慧山泉', '4a52273c-4569-4c95-bc17-cbd3fe5098cd', '唐', '["石脈綻寒光，松根噴曉涼。","注缾雲母滑，漱齒茯苓香。","野客偷煎茗，山僧借淨牀。","安禪何所問，孤月在中央。"]', '["石脈綻寒光，松根噴晓涼。","注缾云母滑，漱齒茯苓香。","野客偷煎茗，山僧借淨牀。","安禪何所问，孤月在中央。"]', '诗', 'shi', '', NULL, '題慧山泉 若水 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c62642-6862-4ebd-b939-1b2073f2f24b', '題馬跡山', '題马跡山', '60d17e72-3aa8-40dc-b415-889f2f20f0f1', '唐', '["瀛洲西望沃洲山，山在平湖縹緲間。","常說使君千里馬，至今龍跡尚堪攀。"]', '["瀛洲西望沃洲山，山在平湖縹緲间。","常说使君千里马，至今龙跡尚堪攀。"]', '诗', 'shi', '', NULL, '題馬跡山 文鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8edb1c49-bcac-4f90-9b45-9aa8a9913ade', '和御製遊慈恩寺', '和御製游慈恩寺', 'fc7d2416-a1f1-42ab-b021-ef4b77f148e3', '唐', '["皇風扇祇樹，至德茂禪林。","仙華曜日彩，神旛曳遠陰。","綺殿籠霞影，飛閣出雲心。","細草希慈澤，恩光重更深。"]', '["皇风扇祇樹，至德茂禪林。","仙华曜日彩，神旛曳远陰。","綺殿籠霞影，飞閣出云心。","細草希慈澤，恩光重更深。"]', '诗', 'shi', '', NULL, '和御製遊慈恩寺 慈恩寺沙門 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b84a93-68f2-4417-9393-a8f9a829196e', '贈賈松先輩', '贈賈松先輩', '2d522ab6-c736-4fa6-9e45-d95ce1675b1c', '唐', '["嵯峨山上石，歲歲色長新。","若使盡成寶，誰爲知己人。"]', '["嵯峨山上石，歲歲色长新。","若使尽成寶，誰爲知己人。"]', '诗', 'shi', '', NULL, '贈賈松先輩 水心寺僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('462a9b2c-c4cf-422f-838f-9f3565a84b35', '古梅', '古梅', '790ffb86-f892-46df-885a-da9de2ac4655', '唐', '["火虐風饕水漬根，霜皴雪皺古苔痕。","東風未肯隨寒暑，又蘖清香與返魂。"]', '["火虐风饕水漬根，霜皴雪皺古苔痕。","东风未肯隨寒暑，又蘖清香與返魂。"]', '诗', 'shi', '', NULL, '古梅 無名釋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568c138d-8242-488f-bc93-400338a27dac', '月', '月', '9392d420-6e15-4dee-a3fd-7b8abd55077b', '唐', '["徐徐東海出，漸漸上天衢。","此夜一輪滿，清光何處無。"]', '["徐徐东海出，漸漸上天衢。","此夜一輪满，清光何处無。"]', '诗', 'shi', '', NULL, '月 南唐失名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b48cfab-7638-4dff-b054-f5feea86bb07', '武肅王有旨石橋設齋會進士一詩共六首 一', '武肅王有旨石橋設斋會進士一诗共六首 一', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["南有天台事可尊，孕靈含秀獨超羣。","重重曲澗侵危石，步步層巖踏碎雲。","金雀每從雲裏現，異香多向夜深聞。","當知此界非凡界，一道幽奇各自分。"]', '["南有天台事可尊，孕靈含秀独超羣。","重重曲澗侵危石，步步層巖踏碎云。","金雀每從云裏現，異香多向夜深闻。","當知此界非凡界，一道幽奇各自分。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 一 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026b6449-e74d-4bd0-a8f0-8b7a4ff7ffa0', '武肅王有旨石橋設齋會進士一詩共六首 二', '武肅王有旨石橋設斋會進士一诗共六首 二', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["仙源佛窟有天台，今古嘉名遍九垓。","石磴嵌空神匠出，瀑泉雄壯雨聲來。","景強偏感高僧上，地勝能令遠思開。","一等翹誠依此處，自然靈貺作梯媒。"]', '["仙源佛窟有天台，今古嘉名遍九垓。","石磴嵌空神匠出，瀑泉雄壯雨声来。","景強偏感高僧上，地勝能令远思开。","一等翹誠依此处，自然靈貺作梯媒。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 二 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d9400d-14e7-463f-83b0-701ee6123fc2', '武肅王有旨石橋設齋會進士一詩共六首 三', '武肅王有旨石橋設斋會進士一诗共六首 三', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["智泉福海莫能逾，親自王恩運睿謨。","感現盡冥心境界，資持全固道根株。","石梁低翥紅鸚鵡，煙嶺高翔碧鷓鴣。","勝妙重重惟禱祝，永資軍庶息災虞。"]', '["智泉福海莫能逾，親自王恩運睿謨。","感現尽冥心境界，資持全固道根株。","石梁低翥紅鸚鵡，煙嶺高翔碧鷓鴣。","勝妙重重惟禱祝，永資軍庶息災虞。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 三 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc8f7407-9df6-4071-8799-86081d66ed98', '武肅王有旨石橋設齋會進士一詩共六首 四', '武肅王有旨石橋設斋會進士一诗共六首 四', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["凌晨迎請倍精誠，親散鮮花異處清。","羅漢攀枝呈梵相，巖僧倚樹現真形。","神幡雙出紅霞動，寶塔全開白氣生。","都爲王心標意切，滿空盈月瑞分明。"]', '["凌晨迎請倍精誠，親散鲜花異处清。","羅漢攀枝呈梵相，巖僧倚樹現真形。","神幡雙出紅霞动，寶塔全开白氣生。","都爲王心標意切，满空盈月瑞分明。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 四 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9474841a-b631-4692-83f7-58e4d9f6bac4', '武肅王有旨石橋設齋會進士一詩共六首 五', '武肅王有旨石橋設斋會進士一诗共六首 五', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["幡花寶蓋滿青川，祈禱迎來聖半千。","莫道勝緣無影響，須知嘉會有因緣。","空中長似聞天樂，巖畔常疑有地仙。","何必更尋兜率去，重重靈應事昭然。"]', '["幡花寶蓋满青川，祈禱迎来聖半千。","莫道勝緣無影响，須知嘉會有因緣。","空中长似闻天乐，巖畔常疑有地仙。","何必更尋兜率去，重重靈應事昭然。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 五 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5becd9b9-3fd4-4485-a2e8-115ceaffbc99', '武肅王有旨石橋設齋會進士一詩共六首 六', '武肅王有旨石橋設斋會進士一诗共六首 六', 'd5ea39c1-481e-48a5-bdbc-bb82fd1cd6e2', '唐', '["登雲步嶺涉煙程，好景隨心次第生。","聖者已符祥瑞事，地靈全副禱祈情。","洞深重疊拖雲濕，灘淺潺湲漱水清。","願滿事圓歸去路，便風相送片帆輕。"]', '["登云步嶺涉煙程，好景隨心次第生。","聖者已符祥瑞事，地靈全副禱祈情。","洞深重叠拖云濕，灘淺潺湲漱水清。","願满事圓归去路，便风相送片帆轻。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進士一詩共六首 六 吳越僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006a07c2-01cc-4e9f-b94e-1857378337ec', '題戶詩', '題戶诗', '4494de9a-8a06-4283-a0ac-c62e7a31d57c', '唐', '["枕有思鄉淚，門無問疾人。","塵埋牀下履，風動架頭巾。"]', '["枕有思乡泪，门無问疾人。","塵埋牀下履，风动架头巾。"]', '诗', 'shi', '', NULL, '題戶詩 唐末僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c2f321-a0d3-48bd-a36c-02c4aba1de66', '逸句', '逸句', '6be03a45-f607-4c5b-bb8b-17063c7bd70b', '唐', '["鵶鳴東牖曙，草秀南湖春。"]', '["鵶鳴东牖曙，草秀南湖春。"]', '诗', 'shi', '', NULL, '逸句 神迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51049d5-bcca-44ef-a38f-01aec94313c1', '逸句', '逸句', 'e4cd0372-643d-4ffa-a58e-850b82a30e89', '唐', '["萬般思後行，一失廢前功。"]', '["万般思後行，一失廢前功。"]', '诗', 'shi', '', NULL, '逸句 可隆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f8c2662-3ed0-440f-a89d-5d6f02ea9abf', '逸句', '逸句', '12df760d-6e93-4afc-b2e1-ca6a1940c000', '唐', '["鯨目光燒半海紅，鰲頭浪蹙掀天白。"]', '["鯨目光燒半海紅，鰲头浪蹙掀天白。"]', '诗', 'shi', '', NULL, '逸句 爾鳥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1726123e-d3ac-4bee-8aab-03fdcb2d7a67', '逸句', '逸句', '4a3348fd-bc77-4419-8449-c9076954e731', '唐', '["寺隔殘潮去，採藥過泉聲。","林塘秋半宿，風雨夜深來。"]', '["寺隔殘潮去，採藥過泉声。","林塘秋半宿，风雨夜深来。"]', '诗', 'shi', '', NULL, '逸句 元礎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15a7252-5797-40a8-8a93-20cd9a617f5d', '逸句', '逸句', 'bf06b6a5-fc3b-4fb7-88e5-2f686d0993d0', '唐', '["鳥歸花影動，魚沒浪痕圓。"]', '["鸟归花影动，鱼沒浪痕圓。"]', '诗', 'shi', '', NULL, '逸句 悟清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4cb6ad-13cd-4da7-91f2-7adc70de3f1f', '逸句', '逸句', '8c8d15ef-a250-4070-a7f7-940ab93b6837', '唐', '["三千里外一條水，十二時中兩度潮。"]', '["三千里外一條水，十二时中兩度潮。"]', '诗', 'shi', '', NULL, '逸句 契盈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9858ca-7aaf-4f06-82f4-d10c7852f2ae', '逸句', '逸句', '63dc7d07-d848-4a92-a580-5278c75e0222', '唐', '["到處自鑿井，不能飲常流。"]', '["到处自鑿井，不能饮常流。"]', '诗', 'shi', '', NULL, '逸句 淡然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa0e89fd-8ab6-4ee4-8d61-8d423389866e', '逸句', '逸句', '05d2f10c-bd17-43bc-8796-c884a7172959', '唐', '["吟中雙鬢白，笑裏一生貧。"]', '["吟中雙鬢白，笑裏一生貧。"]', '诗', 'shi', '', NULL, '逸句 庭實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a907660e-e1b4-4a04-b3f2-354cac81780a', '逸句', '逸句', 'de302378-5dfb-4a26-8ce7-de19a1f80e85', '唐', '["接岸橋通何處路，倚欄人[是阿]誰家。"]', '["接岸橋通何处路，倚欄人[是阿]誰家。"]', '诗', 'shi', '', NULL, '逸句 知業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10002fb5-b269-4bf5-b1fd-c1b624915b57', '逸句', '逸句', 'a6991a31-f7ad-4594-9449-ed33f1e4b90d', '唐', '["木末上明星。"]', '["木末上明星。"]', '诗', 'shi', '', NULL, '逸句 雲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f708e169-9b50-47c6-b58d-5e2b29da7fa1', '逸句', '逸句', '458c4ad4-3159-4d36-8549-93e603a5ddf5', '唐', '["三萬蓮經三十春，半生不蹋院門塵。"]', '["三万蓮經三十春，半生不蹋院门塵。"]', '诗', 'shi', '', NULL, '逸句 玄幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0821f2-2099-4c6e-81f5-83820891699e', '逸句', '逸句', 'a2f3b4a6-c8e6-45d7-b15d-596b67e91c9a', '唐', '["惟有罇前今夜月，當時曾照墮樓人。","梧桐葉老蟬聲死，一夜洞庭波上風。"]', '["惟有罇前今夜月，當时曾照墮楼人。","梧桐葉老蟬声死，一夜洞庭波上风。"]', '诗', 'shi', '', NULL, '逸句 志定 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c883641c-c4d9-4ea5-9307-db987330fa0f', '逸句', '逸句', 'abad47ae-893b-44d2-b2a9-9d2008225faf', '唐', '["晴看漢水廣，秋覺峴山高。"]', '["晴看漢水廣，秋覺峴山高。"]', '诗', 'shi', '', NULL, '逸句 靈準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c968e274-ab29-4fc0-ab16-d4b1acef77c6', '逸句', '逸句', 'cf9d0976-9b0f-4d2a-a0e3-a6b4ad3b7ef6', '唐', '["犬熟護鄰房。"]', '["犬熟護鄰房。"]', '诗', 'shi', '', NULL, '逸句 荆州僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2c78e6-76b6-4ae9-8845-4518df36967d', '荅宋之問', '荅宋之问', '5897b472-f68f-49c0-b167-aeb689d55cde', '唐', '["時既暮兮節欲春，山林寂兮懷幽人。","登奇峰兮望白雲，悵緬邈兮象欲紛。","白雲悠悠去不返，寒風颼颼吹日晚。","不見其人誰與言，歸坐彈琴思逾遠。"]', '["时既暮兮節欲春，山林寂兮懷幽人。","登奇峰兮望白云，悵緬邈兮象欲紛。","白云悠悠去不返，寒风颼颼吹日晚。","不见其人誰與言，归坐彈琴思逾远。"]', '诗', 'shi', '', NULL, '荅宋之問 司馬承禎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afd8310a-2b65-40a3-88d0-adb26822917b', '醉吟三首 一', '醉吟三首 一', '0ab09e60-0ebb-4df3-a381-3a02288350a7', '唐', '["去歲無田種，今春乏酒材。","從他花鳥笑，佯醉臥樓臺。"]', '["去歲無田種，今春乏酒材。","從他花鸟笑，佯醉臥楼台。"]', '诗', 'shi', '', NULL, '醉吟三首 一 張氳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21c5f628-2276-4adb-8951-2f6283fb049e', '醉吟三首 二', '醉吟三首 二', '0ab09e60-0ebb-4df3-a381-3a02288350a7', '唐', '["下調無人睬，高心又被瞋。","不知時俗意，教我若爲人。"]', '["下調無人睬，高心又被瞋。","不知时俗意，教我若爲人。"]', '诗', 'shi', '', NULL, '醉吟三首 二 張氳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2283af39-ff3f-474e-9d69-7521b0ac958a', '醉吟三首 三', '醉吟三首 三', '0ab09e60-0ebb-4df3-a381-3a02288350a7', '唐', '["入市非求利，過朝不爲名。","有時隨俗物，相伴且營營。"]', '["入市非求利，過朝不爲名。","有时隨俗物，相伴且營營。"]', '诗', 'shi', '', NULL, '醉吟三首 三 張氳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('096601bd-576c-441c-a572-1b5b2ce14598', '洗心', '洗心', 'a7588542-717f-4063-bf4a-cc10eaa23182', '唐', '["不踐名利道，始覺塵土腥。","不味稻粱食，始覺精神清。","羅浮奔走外，日月無短明。","山瘦松亦勁，鶴老飛更輕。","逍遙此中客，翠髮皆長生。","草木多古色，雞犬無新聲。","君有出俗志，不貪英雄名。","傲然脫冠帶，改換人間情。","去矣丹霄路，向曉雲冥冥。"]', '["不踐名利道，始覺塵土腥。","不味稻粱食，始覺精神清。","羅浮奔走外，日月無短明。","山瘦松亦勁，鹤老飞更轻。","逍遙此中客，翠髮皆长生。","草木多古色，雞犬無新声。","君有出俗志，不貪英雄名。","傲然脫冠带，改換人间情。","去矣丹霄路，向晓云冥冥。"]', '诗', 'shi', '', NULL, '洗心 司馬退之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926f4798-8d1b-4d11-bb9b-b981667832e5', '夜醉臥街', '夜醉臥街', '5410d6a0-bdb5-41cd-9aee-1329db77074c', '唐', '["遮莫鼕鼕動，須傾滿滿杯。","金吾如借問，但道玉山頹。"]', '["遮莫鼕鼕动，須傾满满杯。","金吾如借问，但道玉山頹。"]', '诗', 'shi', '', NULL, '夜醉臥街 裴翛然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafc69a3-07c7-4347-8938-416bda2f482f', '謁堯帝廟', '謁堯帝廟', '4c61d522-be04-4985-935d-77539b4cb8c3', '唐', '["祖龍開國盡遐荒，廟建唐堯鎮此邦。","山卷白雲朝帝座，林疎紅日列仙幢。","巍巍聖蹟陵松嶠，蕩蕩恩波洽桂江。","瞻仰威靈共回首，紫霞深處鎖軒窗。"]', '["祖龙开国尽遐荒，廟建唐堯鎮此邦。","山卷白云朝帝座，林疎紅日列仙幢。","巍巍聖蹟陵松嶠，蕩蕩恩波洽桂江。","瞻仰威靈共回首，紫霞深处鎖軒窗。"]', '诗', 'shi', '', NULL, '謁堯帝廟 軒轅彌明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dfb63c-4a91-4227-ad7a-c5e7ddaf0008', '山居 一', '山居 一', 'd15753a9-9485-43d4-9f2e-e1a7d86f0e9a', '唐', '["照水冰如鑑，掃雪玉爲塵。","何須問今古，便是上皇人。"]', '["照水冰如鑑，掃雪玉爲塵。","何須问今古，便是上皇人。"]', '诗', 'shi', '', NULL, '山居 一 陳寡言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('714c780c-f630-42be-88d1-ceb90bae92e7', '山居 二', '山居 二', 'd15753a9-9485-43d4-9f2e-e1a7d86f0e9a', '唐', '["醉臥茅堂不閉關，覺來開眼見青山。","松花落處宿猨在，麋鹿羣羣林際還。"]', '["醉臥茅堂不閉关，覺来开眼见青山。","松花落处宿猨在，麋鹿羣羣林際還。"]', '诗', 'shi', '', NULL, '山居 二 陳寡言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe8eced-e7e0-4621-aaa7-4ace58739200', '臨化示弟子', '臨化示弟子', 'd15753a9-9485-43d4-9f2e-e1a7d86f0e9a', '唐', '["我本無形暫有形，偶來人世逐營營。","輪迴債負今還畢，搔首翛然歸上清。"]', '["我本無形暫有形，偶来人世逐營營。","輪迴債負今還畢，搔首翛然归上清。"]', '诗', 'shi', '', NULL, '臨化示弟子 陳寡言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4988dee8-c0d1-46b4-953d-38384f7933d5', '元白席上作', '元白席上作', 'e383a270-cc03-4c1b-8d1b-3229031e1de1', '唐', '["生在儒家遇太平，懸纓垂帶布衣輕。","誰能世路趨名利，臣事玉皇歸上清。"]', '["生在儒家遇太平，懸纓垂带布衣轻。","誰能世路趨名利，臣事玉皇归上清。"]', '诗', 'shi', '', NULL, '元白席上作 李昇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5163e2-e99f-43c1-8e1f-88d550fabc87', '一字至七字詩 書', '一字至七字诗 书', '3ca4ddd9-5703-42f9-a5d0-1643be1226b2', '唐', '["書，憑鴈，寄魚。","出王屋，入匡廬。","文生益智，道著清虛。","葛洪一萬卷，惠子五車餘。","銀鉤屈曲索靖，題橋司馬相如。","別後莫暌千里信，數封緘送到閑居。"]', '["书，憑鴈，寄鱼。","出王屋，入匡廬。","文生益智，道著清虛。","葛洪一万卷，惠子五车餘。","銀鉤屈曲索靖，題橋司马相如。","別後莫暌千里信，數封緘送到闲居。"]', '诗', 'shi', '', NULL, '一字至七字詩 書 范堯佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000c1478-af14-4ddd-b0b6-6a60eb367e7f', '言志獻浙東廉訪辭召', '言志獻浙东廉訪辞召', '51c7d9ef-5314-4ca7-8743-12924376165d', '唐', '["野性歌三樂，皇恩出九重。","那煩紫宸命，遠下白雲峰。","多媿書傳鶴，深慚紙畫龍。","將何佐明主，甘老在巖松。"]', '["野性歌三乐，皇恩出九重。","那煩紫宸命，远下白云峰。","多媿书傳鹤，深慚紙畫龙。","將何佐明主，甘老在巖松。"]', '诗', 'shi', '', NULL, '言志獻浙東廉訪辭召 徐靈府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf467a58-45e1-42b7-8bec-e6db8ed049b9', '自詠二首 一', '自詠二首 一', '51c7d9ef-5314-4ca7-8743-12924376165d', '唐', '["寂寂凝神太極初，無心應物等空虛。","性修自性非求得，欲識真人祗是渠。"]', '["寂寂凝神太極初，無心應物等空虛。","性修自性非求得，欲識真人祗是渠。"]', '诗', 'shi', '', NULL, '自詠二首 一 徐靈府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffa103a-c0a2-4cdc-a558-fc9eb861c60e', '自詠二首 二', '自詠二首 二', '51c7d9ef-5314-4ca7-8743-12924376165d', '唐', '["學道全真在此生，何須待死更求生。","今生不了無生理，縱復生知那處生。"]', '["学道全真在此生，何須待死更求生。","今生不了無生理，縱复生知那处生。"]', '诗', 'shi', '', NULL, '自詠二首 二 徐靈府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb8797cf-0bf8-4914-99ac-fc31dfc6170a', '留觀中詩二首 一', '留观中诗二首 一', '963fbe5d-3533-4f03-af17-521a84476d59', '唐', '["終日草堂間，清風常往還。","耳無塵事擾，心有翫雲閑。","對酒惟思月，餐松不厭山。","時時吟內景，自合駐童顏。"]', '["終日草堂间，清风常往還。","耳無塵事擾，心有翫云闲。","对酒惟思月，餐松不厭山。","时时吟內景，自合駐童顏。"]', '诗', 'shi', '', NULL, '留觀中詩二首 一 吳子來 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e783367-449b-4b65-8c47-dd2061bbca24', '留觀中詩二首 二', '留观中诗二首 二', '963fbe5d-3533-4f03-af17-521a84476d59', '唐', '["此生此物當生涯，白石青松便是家。","對月臥雲如野鹿，時時買酒醉煙霞。"]', '["此生此物當生涯，白石青松便是家。","对月臥云如野鹿，时时買酒醉煙霞。"]', '诗', 'shi', '', NULL, '留觀中詩二首 二 吳子來 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15310db9-e651-401d-9ff0-c9fd6112c67f', '遊仙二十四首 一', '游仙二十四首 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["啓冊觀往載，搖懷考今情。","終古已寂寂，舉世何營營。","悟彼衆仙妙，超然含至精。","凝神契沖玄，化服凌太清。","心同宇宙廣，體合雲霞輕。","翔風吹羽蓋，慶霄拂霓旌。","龍駕朝紫微，後天保令名。","豈如寰中士，軒冕矜蹔榮。"]', '["啓冊观往載，搖懷考今情。","終古已寂寂，舉世何營營。","悟彼衆仙妙，超然含至精。","凝神契沖玄，化服凌太清。","心同宇宙廣，體合云霞轻。","翔风吹羽蓋，慶霄拂霓旌。","龙駕朝紫微，後天保令名。","豈如寰中士，軒冕矜蹔榮。"]', '诗', 'shi', '', NULL, '遊仙二十四首 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5e3c07-5cb6-4dd9-a326-66238e611261', '遊仙二十四首 二', '游仙二十四首 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["鸞鳳棲瑤林，鵰鶚集平楚。","飲啄本殊好，翺翔終異所。","吾方遺諠囂，立節慕高舉。","解茲區中戀，結彼霄外侶。","誰謂天路遐，感通自無阻。"]', '["鸾鳳棲瑤林，鵰鶚集平楚。","饮啄本殊好，翺翔終異所。","吾方遺諠囂，立節慕高舉。","解茲區中戀，結彼霄外侶。","誰謂天路遐，感通自無阻。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfd38f3b-0634-483c-b5a8-37b3ffbadede', '遊仙二十四首 三', '游仙二十四首 三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["愍俗從遷謝，尋仙去淪沒。","三元有真人，與我生道骨。","凌晨吸丹景，入夜飲黃月。","百關彌調暢，方寸益清越。","棲神合虛無，洞覽周恍惚。","不覺隨玉皇，焚香詣金闕。"]', '["愍俗從遷謝，尋仙去淪沒。","三元有真人，與我生道骨。","凌晨吸丹景，入夜饮黄月。","百关彌調暢，方寸益清越。","棲神合虛無，洞覽周恍惚。","不覺隨玉皇，焚香詣金闕。"]', '诗', 'shi', '', NULL, '遊仙二十四首 三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c643f801-9491-407a-b2e1-00445bcab550', '遊仙二十四首 四', '游仙二十四首 四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["西龜初定籙，東華已校名。","三官無遺譴，七祖升雲軿。","體妙塵累隔，心微玄化幷。","一朝出天地，億載猶童嬰。","使我齊浩劫，蕭蕭宴玉清。"]', '["西龟初定籙，东华已校名。","三官無遺譴，七祖升云軿。","體妙塵累隔，心微玄化幷。","一朝出天地，億載猶童嬰。","使我齊浩劫，蕭蕭宴玉清。"]', '诗', 'shi', '', NULL, '遊仙二十四首 四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2094ffd2-5887-46e2-8e66-e6625cbf927b', '遊仙二十四首 五', '游仙二十四首 五', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["怡神在靈府，皎皎含清澄。","仙經不吾欺，輕舉信有徵。","疇昔希道念，而今果天矜。","豈非陰功著，乃致白日升。","焉用過洞府，吾其越朱陵。"]', '["怡神在靈府，皎皎含清澄。","仙經不吾欺，轻舉信有徵。","疇昔希道念，而今果天矜。","豈非陰功著，乃致白日升。","焉用過洞府，吾其越朱陵。"]', '诗', 'shi', '', NULL, '遊仙二十四首 五 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27666e82-2f90-4063-bbf5-8422f6b4bb08', '遊仙二十四首 六', '游仙二十四首 六', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["高真誠寥邈，道合不我遺。","孰謂姑射遠，神人可同嬉。","結駕從之遊，飄飄出天垂。","不理人自化，神凝物無疵。","因知至精感，足以和四時。"]', '["高真誠寥邈，道合不我遺。","孰謂姑射远，神人可同嬉。","結駕從之游，飄飄出天垂。","不理人自化，神凝物無疵。","因知至精感，足以和四时。"]', '诗', 'shi', '', NULL, '遊仙二十四首 六 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b685f8e9-e58d-4540-8534-c92b0140c88c', '遊仙二十四首 七', '游仙二十四首 七', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["碧海廣無際，三山高不極。","金臺羅中天，羽客恣遊息。","霞液朝可飲，虹芝晚堪食。","嘯歌自忘心，騰舉寧假翼。","保壽同三光，安能紀千億。"]', '["碧海廣無際，三山高不極。","金台羅中天，羽客恣游息。","霞液朝可饮，虹芝晚堪食。","嘯歌自忘心，腾舉寧假翼。","保壽同三光，安能紀千億。"]', '诗', 'shi', '', NULL, '遊仙二十四首 七 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d957d9ea-039b-4085-9e5f-b29d3989ca04', '遊仙二十四首 八', '游仙二十四首 八', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["將過太帝宮，蹔詣扶桑處。","真童已相迓，爲我清宿霧。","海若寧洪濤，羲和止奔馭。","五雲結層閣，八景動飛輿。","青霞正可挹，丹椹時一遇。","留我宴玉堂，歸軒不令遽。"]', '["將過太帝宮，蹔詣扶桑处。","真童已相迓，爲我清宿霧。","海若寧洪濤，羲和止奔馭。","五云結層閣，八景动飞輿。","青霞正可挹，丹椹时一遇。","留我宴玉堂，归軒不令遽。"]', '诗', 'shi', '', NULL, '遊仙二十四首 八 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e583b03-22b0-4e73-8280-3bee5a1691aa', '遊仙二十四首 九', '游仙二十四首 九', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["欲超洞陽界，試鑒丹極表。","赤帝躍火龍，炎官控朱鳥。","導我升絳府，長軀出天杪。","陽靈赫重暉，四達何皎皎。","爲爾流飄風，羣生遂無夭。"]', '["欲超洞陽界，試鑒丹極表。","赤帝躍火龙，炎官控朱鸟。","導我升絳府，长軀出天杪。","陽靈赫重暉，四達何皎皎。","爲爾流飄风，羣生遂無夭。"]', '诗', 'shi', '', NULL, '遊仙二十四首 九 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147447ae-84f4-4e35-93fc-be11baf0cc14', '遊仙二十四首 十', '游仙二十四首 十', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["予因詣金母，飛蓋超西極。","遂入素中天，停輪太濛側。","若華拂流影，不使白日匿。","傾曦復亭午，六合無暝色。","道化隨感遷，此理誰能測。"]', '["予因詣金母，飞蓋超西極。","遂入素中天，停輪太濛側。","若华拂流影，不使白日匿。","傾曦复亭午，六合無暝色。","道化隨感遷，此理誰能測。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daee03d9-8763-485c-a1bb-9b82b3852adc', '遊仙二十四首 十一', '游仙二十四首 十一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["九龍何蜿蜿，載我升雲綱。","臨睨懷舊國，風塵混蒼茫。","依依遠人寰，去去邇帝鄉。","上超星辰紀，下視日月光。","倏已過太微，天居煥煌煌。"]', '["九龙何蜿蜿，載我升云綱。","臨睨懷旧国，风塵混蒼茫。","依依远人寰，去去邇帝乡。","上超星辰紀，下視日月光。","倏已過太微，天居煥煌煌。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6280b2e3-2db5-47c0-9e99-b4ba884cf186', '遊仙二十四首 十二', '游仙二十四首 十二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["停驂太儀側，整服金闕前。","肅肅承上帝，鏘鏘會羣仙。","鴻鑪發靈香，廣廡張鈞天。","玉醴洽中座，霞膏充四筵。","良期無終極，俛仰移億年。"]', '["停驂太儀側，整服金闕前。","肅肅承上帝，鏘鏘會羣仙。","鴻鑪發靈香，廣廡張鈞天。","玉醴洽中座，霞膏充四筵。","良期無終極，俛仰移億年。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e66b1f36-80f3-4644-8300-ada2bb3c6c21', '遊仙二十四首 十三', '游仙二十四首 十三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["峻朗妙門闢，澄微真鑒通。","瓊林九霞上，金閣三天中。","飛虬躍慶雲，翔鶴摶靈風。","鬱彼玉京會，仙期六合同。"]', '["峻朗妙门闢，澄微真鑒通。","瓊林九霞上，金閣三天中。","飞虬躍慶云，翔鹤摶靈风。","鬱彼玉京會，仙期六合同。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79655c8-6a3a-49f5-8762-eac776699cfc', '遊仙二十四首 十四', '游仙二十四首 十四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["予昇至陽元，欲憩明霞館。","飄飄瓊輪舉，曄曄金景散。","結虛成萬有，高妙咸可翫。","玉山鬱嵯峨，琅海杳無岸。","蹔賞過千椿，遐齡誰復算。"]', '["予昇至陽元，欲憩明霞館。","飄飄瓊輪舉，曄曄金景散。","結虛成万有，高妙咸可翫。","玉山鬱嵯峨，琅海杳無岸。","蹔賞過千椿，遐齡誰复算。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b715f4a7-3866-4117-9f49-e86e3a772c15', '遊仙二十四首 十五', '游仙二十四首 十五', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["招攜紫陽友，合宴玉清臺。","排景羽衣振，浮空雲駕來。","靈旛七曜動，瓊障九光開。","鳳舞龍璈奏，虬軒殊未迴。"]', '["招携紫陽友，合宴玉清台。","排景羽衣振，浮空云駕来。","靈旛七曜动，瓊障九光开。","鳳舞龙璈奏，虬軒殊未迴。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十五 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2decc867-c816-440e-bb41-eab42e1da742', '遊仙二十四首 十六', '游仙二十四首 十六', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["高升紫極上，宴此玄都岑。","玉藻散奇香，瓊柯流雅音。","靈風生太漠，習習吹人襟。","體混希微廣，神凝空洞深。","蕭然宇宙外，自得乾坤心。"]', '["高升紫極上，宴此玄都岑。","玉藻散奇香，瓊柯流雅音。","靈风生太漠，習習吹人襟。","體混希微廣，神凝空洞深。","蕭然宇宙外，自得乾坤心。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十六 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2f6a50-e1d9-485f-839b-ca4b08536037', '遊仙二十四首 十七', '游仙二十四首 十七', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["晨登千仞嶺，俯瞰四人居。","原野間城邑，山河分里閭。","眇彼埃塵中，爭奔聲利途。","百齡寵辱盡，萬事皆爲虛。","自昔無成功，安能與爾俱。","將期駕雲景，超跡升天衢。"]', '["晨登千仞嶺，俯瞰四人居。","原野间城邑，山河分里閭。","眇彼埃塵中，爭奔声利途。","百齡寵辱尽，万事皆爲虛。","自昔無成功，安能與爾俱。","將期駕云景，超跡升天衢。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十七 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213e900e-f90f-4242-b128-7dba7d8d5856', '遊仙二十四首 十八', '游仙二十四首 十八', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["骨鍊體彌清，鑒明塵已絕。","恬夷宇宙泰，煥朗天光徹。","羽服參煙霄，童顏皎冰雪。","隱符千魔駭，鳴玉萬帝悅。","遂使區宇中，祅氣永淪滅。"]', '["骨鍊體彌清，鑒明塵已絕。","恬夷宇宙泰，煥朗天光徹。","羽服參煙霄，童顏皎冰雪。","隐符千魔駭，鳴玉万帝悅。","遂使區宇中，祅氣永淪滅。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十八 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd8d142-d6e9-4b89-91d9-449db7c2fb9d', '遊仙二十四首 十九', '游仙二十四首 十九', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["朝逾弱水北，夕憩鍾山頂。","顓頊清玄宮，禺強掃幽境。","燭龍發神曜，陰野彌煥炳。","導達三氣和，驅除六天靜。","玉樓互相暉，煙客何秀頴。","一舉流霞津，千年在俄傾。"]', '["朝逾弱水北，夕憩鍾山頂。","顓頊清玄宮，禺強掃幽境。","燭龙發神曜，陰野彌煥炳。","導達三氣和，驱除六天静。","玉楼互相暉，煙客何秀頴。","一舉流霞津，千年在俄傾。"]', '诗', 'shi', '', NULL, '遊仙二十四首 十九 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421d2289-e00e-47df-9d7c-844bb2e9effb', '遊仙二十四首 二十', '游仙二十四首 二十', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["揚蓋造辰極，乘煙遊閬風。","上元降玉闥，王母開琳宮。","天人何濟濟，高會碧堂中。","列侍奏雲歌，真音滿太空。","千年紫柰熟，四劫靈瓜豐。","斯樂異荒讌，陶陶殊未終。"]', '["揚蓋造辰極，乘煙游閬风。","上元降玉闥，王母开琳宮。","天人何濟濟，高會碧堂中。","列侍奏云歌，真音满太空。","千年紫柰熟，四劫靈瓜豐。","斯乐異荒讌，陶陶殊未終。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二十 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d3a3e06-bd9a-4c91-bf97-46cbe62b4062', '遊仙二十四首 二十一', '游仙二十四首 二十一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["整駕辭五嶽，排煙凌九霄。","紛然太虛中，羽斾更相招。","且盼蓬壺近，誰言崑閬遙。","悠悠竟安適，仰赴三天朝。"]', '["整駕辞五嶽，排煙凌九霄。","紛然太虛中，羽斾更相招。","且盼蓬壺近，誰言崑閬遙。","悠悠竟安適，仰赴三天朝。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二十一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('073a99d4-de47-4f98-b79a-70ed2cd01d09', '遊仙二十四首 二十二', '游仙二十四首 二十二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["予招三清友，逈出九天上。","撓挑絕漠中，差池遙相望。","大空含常明，八外無隱障。","鸞鳳有逸翮，泠然恣飄颺。","寥寥唯玄虛，至樂在神王。"]', '["予招三清友，逈出九天上。","撓挑絕漠中，差池遙相望。","大空含常明，八外無隐障。","鸾鳳有逸翮，泠然恣飄颺。","寥寥唯玄虛，至乐在神王。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二十二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5850dcae-3d06-4cfd-9a5c-524185befa83', '遊仙二十四首 二十三', '游仙二十四首 二十三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["縱身太霞上，眇眇虛中浮。","八威先啓行，五老同我遊。","靈景何灼灼，祥風正寥寥。","嘯歌振長空，逸響清且柔。","遨嬉無迹賞，顧眄皆真儔。","不疾而自速，萬天俄已周。"]', '["縱身太霞上，眇眇虛中浮。","八威先啓行，五老同我游。","靈景何灼灼，祥风正寥寥。","嘯歌振长空，逸响清且柔。","遨嬉無迹賞，顧眄皆真儔。","不疾而自速，万天俄已周。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二十三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf100d0d-452c-4da2-ac62-fd7bdf892509', '遊仙二十四首 二十四', '游仙二十四首 二十四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["返視太初先，與道冥至一。","空洞凝真精，乃爲虛中實。","變通有常性，合散無定質。","不行迅飛電，隱曜光白日。","玄棲忘玄深，無得固無失。"]', '["返視太初先，與道冥至一。","空洞凝真精，乃爲虛中實。","变通有常性，合散無定質。","不行迅飞電，隐曜光白日。","玄棲忘玄深，無得固無失。"]', '诗', 'shi', '', NULL, '遊仙二十四首 二十四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c772d71-c4ec-43f1-8275-d5b912caae7d', '覽古十四首 一', '覽古十四首 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["聖人重周濟，明道欲救時。","孔席不暇暖，墨突何嘗緇。","興言振頹綱，將以有所維。","君臣恣淫惑，風俗日凋衰。","三代業遽隕，七雄遂交馳。","庶物墜塗炭，區中若棼絲。","秦皇燎儒術，方冊靡孑遺。","大漢歷五葉，斯文復崇推。","乃驗經籍道，與世同屯夷。","弛張固天意，設教安能持。"]', '["聖人重周濟，明道欲救时。","孔席不暇暖，墨突何嘗緇。","兴言振頹綱，將以有所維。","君臣恣淫惑，风俗日凋衰。","三代業遽隕，七雄遂交驰。","庶物墜塗炭，區中若棼絲。","秦皇燎儒術，方冊靡孑遺。","大漢歷五葉，斯文复崇推。","乃驗經籍道，與世同屯夷。","弛張固天意，設教安能持。"]', '诗', 'shi', '', NULL, '覽古十四首 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e35c5f3-7a34-4bfa-9e81-ab44b5bc3352', '覽古十四首 二', '覽古十四首 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["興亡道之運，否泰理所全。","奈何淳古風，既往不復旋。","三皇已散朴，五帝初尚賢。","王業與霸功，浮僞日以宣。","忠誠及狙詐，殽混安可甄。","餘智入九霄，守愚淪重泉。","永懷巢居時，感涕徒泫然。"]', '["兴亡道之運，否泰理所全。","奈何淳古风，既往不复旋。","三皇已散朴，五帝初尚賢。","王業與霸功，浮僞日以宣。","忠誠及狙詐，殽混安可甄。","餘智入九霄，守愚淪重泉。","永懷巢居时，感涕徒泫然。"]', '诗', 'shi', '', NULL, '覽古十四首 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72cfcd3-37dc-45eb-b6b2-f30773bca753', '覽古十四首 三', '覽古十四首 三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["棟宇代巢穴，其來自三皇。","跡生固爲累，經始增百王。","瑤臺既滅夏，瓊室復隕湯。","覆車世不悟，秦氏興阿房。","繼踵迷反正，漢家崇建章。","力役弊萬人，瓌奇殫八方。","徇志仍未極，促齡已云亡。","侈靡竟何在，荆榛生廟堂。"]', '["棟宇代巢穴，其来自三皇。","跡生固爲累，經始增百王。","瑤台既滅夏，瓊室复隕湯。","覆车世不悟，秦氏兴阿房。","繼踵迷反正，漢家崇建章。","力役弊万人，瓌奇殫八方。","徇志仍未極，促齡已云亡。","侈靡竟何在，荆榛生廟堂。"]', '诗', 'shi', '', NULL, '覽古十四首 三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a33718c-bb81-4e66-9a74-3e0b03ca7954', '覽古十四首 四', '覽古十四首 四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["閑居覽前載，惻彼商與秦。","所殘必忠良，所寶皆兇嚚。","昵諛方自聖，不悟禍滅身。","箕子作周輔，孫通爲漢臣。","洪範及禮儀，後王用經綸。"]', '["闲居覽前載，惻彼商與秦。","所殘必忠良，所寶皆兇嚚。","昵諛方自聖，不悟禍滅身。","箕子作周輔，孫通爲漢臣。","洪範及禮儀，後王用經綸。"]', '诗', 'shi', '', NULL, '覽古十四首 四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc05249-878f-4dc4-ab18-e570d6af233f', '覽古十四首 五', '覽古十四首 五', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["吾觀采苓什，復感青蠅詩。","讒佞亂忠孝，古今同所悲。","姦邪起狡猾，骨肉相殘夷。","漢儲殞江充，晉嗣滅驪姬。","天性猶可間，君臣固其宜。","子胥烹吳鼎，文種斷越鈹。","屈原沈湘流，厥戚咸自貽。","何不若范蠡，扁舟無還期。"]', '["吾观采苓什，复感青蠅诗。","讒佞亂忠孝，古今同所悲。","姦邪起狡猾，骨肉相殘夷。","漢儲殞江充，晉嗣滅驪姬。","天性猶可间，君臣固其宜。","子胥烹吳鼎，文種斷越鈹。","屈原沈湘流，厥戚咸自貽。","何不若范蠡，扁舟無還期。"]', '诗', 'shi', '', NULL, '覽古十四首 五 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1e3717-8172-4eef-8b16-e88e92acb695', '覽古十四首 六', '覽古十四首 六', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["嘗稽真仙道，清寂祛衆煩。","秦皇及漢武，焉得遊其藩。","情擾萬機屑，位驕四海尊。","既欲先宇宙，仍規後乾坤。","崇高與久遠，物莫能兩存。","矧乃恣所慾，荒淫伐靈根。","金膏恃延期，玉色復動魂。","征戰窮外域，殺傷被中原。","天鑒諒難誣，神理不可諼。","安期返蓬萊，王母還崑崙。","異術終莫告，悲哉竟何言。"]', '["嘗稽真仙道，清寂祛衆煩。","秦皇及漢武，焉得游其藩。","情擾万機屑，位驕四海尊。","既欲先宇宙，仍規後乾坤。","崇高與久远，物莫能兩存。","矧乃恣所慾，荒淫伐靈根。","金膏恃延期，玉色复动魂。","征戰窮外域，殺傷被中原。","天鑒諒难誣，神理不可諼。","安期返蓬萊，王母還崑崙。","異術終莫告，悲哉竟何言。"]', '诗', 'shi', '', NULL, '覽古十四首 六 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb90ae08-1016-4ef8-8b74-277ca5e5bd29', '覽古十四首 七', '覽古十四首 七', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["魯侯祈政術，尼父從棄捐。","漢主思英才，賈生被排遷。","始皇重韓子，及覩乃不全。","武帝愛相如，既徵復忘賢。","貴遠世咸爾，賤今理共然。","方知古來主，難以効當年。"]', '["魯侯祈政術，尼父從棄捐。","漢主思英才，賈生被排遷。","始皇重韓子，及覩乃不全。","武帝愛相如，既徵复忘賢。","貴远世咸爾，賤今理共然。","方知古来主，难以効當年。"]', '诗', 'shi', '', NULL, '覽古十四首 七 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f5031a8-03c2-4db1-9873-baad3d385c0d', '覽古十四首 八', '覽古十四首 八', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["食其昔未偶，落魄爲狂生。","一朝君臣契，雄辯何縱橫。","運籌康漢業，憑軾下齊城。","既以智所達，還爲智所烹。","豈若終貧賤，酣歌本無營。"]', '["食其昔未偶，落魄爲狂生。","一朝君臣契，雄辯何縱橫。","運籌康漢業，憑軾下齊城。","既以智所達，還爲智所烹。","豈若終貧賤，酣歌本無營。"]', '诗', 'shi', '', NULL, '覽古十四首 八 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559febf1-d86a-4a79-a229-fef97f893569', '覽古十四首 九', '覽古十四首 九', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["晁錯抱遠策，爲君納良規。","削彼諸侯權，永用得所宜。","姦臣負舊隙，乘釁謀相危。","世主竟不辨，身戮宗且夷。","漢景稱欽明，濫罰猶如斯。","比干與龍逢，殘害何足悲。"]', '["晁錯抱远策，爲君納良規。","削彼諸侯權，永用得所宜。","姦臣負旧隙，乘釁謀相危。","世主竟不辨，身戮宗且夷。","漢景稱欽明，濫罰猶如斯。","比干與龙逢，殘害何足悲。"]', '诗', 'shi', '', NULL, '覽古十四首 九 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a6a1564-9493-4099-97bd-095930cd512e', '覽古十四首 十', '覽古十四首 十', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["絳侯成大績，賞厚位仍尊。","一朝對獄吏，榮辱安可論。","蘇生佩六印，奕奕爲殃源。","主父食五鼎，昭昭成禍根。","李斯佐二辟，巨釁鍾其門。","霍孟翼三后，伊戚及後昆。","天人忌盈滿，茲理固永存。","方知得意者，何必乘朱輪。","滅景栖遠壑，弦歌對清樽。","二疏返海濱，蔣詡歸林園。","蕭灑去物累，此謀誠足敦。"]', '["絳侯成大績，賞厚位仍尊。","一朝对獄吏，榮辱安可論。","蘇生佩六印，奕奕爲殃源。","主父食五鼎，昭昭成禍根。","李斯佐二辟，巨釁鍾其门。","霍孟翼三后，伊戚及後昆。","天人忌盈满，茲理固永存。","方知得意者，何必乘朱輪。","滅景栖远壑，弦歌对清樽。","二疏返海濱，蔣詡归林园。","蕭灑去物累，此謀誠足敦。"]', '诗', 'shi', '', NULL, '覽古十四首 十 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e335f46-51ea-4d63-ad64-c22ae3f27482', '覽古十四首 十一', '覽古十四首 十一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["至人順通塞，委命固無疵。","吾觀太史公，可謂識道規。","留滯焉足憤，感懷殄生涯。","吾歎龔夫子，秉義確不移。","晦跡一何晚，天年夭當時。","薰膏自銷鑠，楚老空餘悲。"]', '["至人順通塞，委命固無疵。","吾观太史公，可謂識道規。","留滯焉足憤，感懷殄生涯。","吾歎龔夫子，秉義確不移。","晦跡一何晚，天年夭當时。","薰膏自銷鑠，楚老空餘悲。"]', '诗', 'shi', '', NULL, '覽古十四首 十一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bfb388c-b6d2-4ad2-b512-89a916d204d3', '覽古十四首 十二', '覽古十四首 十二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["達者貴量力，至人尚知幾。","京房洞幽贊，神奧咸發揮。","如何嫉元惡，不悟禍所歸。","謀物闇謀己，誰言爾精微。"]', '["達者貴量力，至人尚知幾。","京房洞幽贊，神奧咸發揮。","如何嫉元惡，不悟禍所归。","謀物闇謀己，誰言爾精微。"]', '诗', 'shi', '', NULL, '覽古十四首 十二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b001c8f1-bc31-4ea1-9570-e04afed2f6d6', '覽古十四首 十三', '覽古十四首 十三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["玄元明知止，大雅尚保躬。","茂先洽聞者，幽賾咸該通。","弱年賦鷦鷯，可謂達養蒙。","晚節希鸞鵠，長飛戾曾穹。","知進不知退，遂令其道窮。","伊昔辨福初，胡爲迷禍終。","方驗嘉遁客，永貞天壤同。"]', '["玄元明知止，大雅尚保躬。","茂先洽闻者，幽賾咸該通。","弱年賦鷦鷯，可謂達養蒙。","晚節希鸾鵠，长飞戾曾穹。","知進不知退，遂令其道窮。","伊昔辨福初，胡爲迷禍終。","方驗嘉遁客，永貞天壤同。"]', '诗', 'shi', '', NULL, '覽古十四首 十三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c4f194-1eac-46bc-8926-e9e8a17594ea', '覽古十四首 十四', '覽古十四首 十四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["聖人垂大訓，奧義不苟設。","天道殃頑兇，神明祐懿哲。","斯言猶影響，安得復迴穴。","鯀瞍誕英睿，唐虞育昏孽。","盜跖何延期，顏生乃短折。","魯隱全克讓，禍機遂潛結。","楚穆肆巨逆，福柄奚赫烈。","田常弒其主，祚國久罔缺。","管仲存霸功，世祖成詭說。","漢氏方版蕩，羣閹恣邪譎。","謇謇陳蕃徒，孜孜抗忠節。","誓期區宇靜，爰使兇醜絕。","謀協事靡從，俄而反誅滅。","古來若茲類，紛擾難盡列。","道遐理微茫，誰爲我昭晰。","吾將詢上帝，寥廓詎躋徹。","已矣勿用言，忘懷庶自悅。"]', '["聖人垂大訓，奧義不苟設。","天道殃頑兇，神明祐懿哲。","斯言猶影响，安得复迴穴。","鯀瞍誕英睿，唐虞育昏孽。","盜跖何延期，顏生乃短折。","魯隐全克讓，禍機遂潛結。","楚穆肆巨逆，福柄奚赫烈。","田常弒其主，祚国久罔缺。","管仲存霸功，世祖成詭说。","漢氏方版蕩，羣閹恣邪譎。","謇謇陳蕃徒，孜孜抗忠節。","誓期區宇静，爰使兇醜絕。","謀協事靡從，俄而反誅滅。","古来若茲類，紛擾难尽列。","道遐理微茫，誰爲我昭晰。","吾將詢上帝，寥廓詎躋徹。","已矣勿用言，忘懷庶自悅。"]', '诗', 'shi', '', NULL, '覽古十四首 十四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd73612c-aa92-4796-91ec-ba034d26081f', '步虛詞十首 一', '步虛词十首 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["衆仙仰靈範，肅駕朝神宗。","金景相照曜，逶迤升太空。","七玄已高飛，火鍊生珠宮。","餘慶逮天壤，平和王道融。","八威清遊氣，十絕舞祥風。","使我躋陽源，其來自陰功。","逍遙太霞上，真鑒靡不通。"]', '["衆仙仰靈範，肅駕朝神宗。","金景相照曜，逶迤升太空。","七玄已高飞，火鍊生珠宮。","餘慶逮天壤，平和王道融。","八威清游氣，十絕舞祥风。","使我躋陽源，其来自陰功。","逍遙太霞上，真鑒靡不通。"]', '诗', 'shi', '', NULL, '步虛詞十首 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('775c0ac7-9838-4add-aa2a-15b7b088c778', '步虛詞十首 二', '步虛词十首 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["逸轡登紫清，乘光邁奔電。","閬風隔三天，俯視猶可見。","玉闥摽敞朗，瓊林鬱葱蒨。","自非挺金骨，焉得諧夙願。","真朋何森森，合景恣遊宴。","良會忘淹留，千齡纔一眄。"]', '["逸轡登紫清，乘光邁奔電。","閬风隔三天，俯視猶可见。","玉闥摽敞朗，瓊林鬱葱蒨。","自非挺金骨，焉得諧夙願。","真朋何森森，合景恣游宴。","良會忘淹留，千齡纔一眄。"]', '诗', 'shi', '', NULL, '步虛詞十首 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411bc735-9cb8-4840-b61a-feec24121f6d', '步虛詞十首 三', '步虛词十首 三', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["三宮發明景，朗照同鬱儀。","紛然馳飆歘，上釆空清蕤。","令我洞金色，後天耀瓊姿。","心協太虛靜，寥寥竟何思。","玄中有至樂，淡泊終無爲。","但與正真友，飄颻散遨嬉。"]', '["三宮發明景，朗照同鬱儀。","紛然驰飆歘，上釆空清蕤。","令我洞金色，後天耀瓊姿。","心協太虛静，寥寥竟何思。","玄中有至乐，淡泊終無爲。","但與正真友，飄颻散遨嬉。"]', '诗', 'shi', '', NULL, '步虛詞十首 三 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b829150-d577-48a6-9093-75a51558ae14', '步虛詞十首 四', '步虛词十首 四', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["稟化凝正氣，鍊形爲真仙。","忘心符元宗，返本協自然。","帝一集絳宮，流光出丹玄。","元英與桃君，朗詠長生篇。","六府煥明霞，百關羅紫煙。","飆車涉寥廓，靡靡乘景遷。","不覺雲路遠，斯須遊萬天。"]', '["稟化凝正氣，鍊形爲真仙。","忘心符元宗，返本協自然。","帝一集絳宮，流光出丹玄。","元英與桃君，朗詠长生篇。","六府煥明霞，百关羅紫煙。","飆车涉寥廓，靡靡乘景遷。","不覺云路远，斯須游万天。"]', '诗', 'shi', '', NULL, '步虛詞十首 四 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baefb1bb-b0de-476b-85ab-c67bc5007d91', '步虛詞十首 五', '步虛词十首 五', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["扶桑誕初景，羽蓋凌晨霞。","倏歘造西域，嬉遊金母家。","碧津湛洪源，灼爍敷荷花。","煌煌青琳宮，粲粲列玉華。","真氣溢絳府，自然思無邪。","俯矜區中士，夭濁良可嗟。"]', '["扶桑誕初景，羽蓋凌晨霞。","倏歘造西域，嬉游金母家。","碧津湛洪源，灼爍敷荷花。","煌煌青琳宮，粲粲列玉华。","真氣溢絳府，自然思無邪。","俯矜區中士，夭濁良可嗟。"]', '诗', 'shi', '', NULL, '步虛詞十首 五 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc0c432-41e3-4d28-9ea6-c2b44100364a', '步虛詞十首 六', '步虛词十首 六', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["瓊臺劫萬仞，孤映大羅表。","常有三素雲，凝光自飛繞。","羽幢泛明霞，升降何縹緲。","鸞鳳吹雅音，栖翔絳林標。","玉虛無晝夜，靈景何皎皎。","一覩太上京，方知衆天小。"]', '["瓊台劫万仞，孤映大羅表。","常有三素云，凝光自飞繞。","羽幢泛明霞，升降何縹緲。","鸾鳳吹雅音，栖翔絳林標。","玉虛無晝夜，靈景何皎皎。","一覩太上京，方知衆天小。"]', '诗', 'shi', '', NULL, '步虛詞十首 六 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('053edf34-23b5-454f-9221-130fe6d50ac5', '步虛詞十首 七', '步虛词十首 七', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["灼灼青華林，靈風振瓊柯。","三光無冬春，一氣清且和。","迴首邇結靈，傾眸親曜羅。","豁落制六天，流鈴威百魔。","緜緜慶不極，誰謂椿齡多。"]', '["灼灼青华林，靈风振瓊柯。","三光無冬春，一氣清且和。","迴首邇結靈，傾眸親曜羅。","豁落制六天，流鈴威百魔。","緜緜慶不極，誰謂椿齡多。"]', '诗', 'shi', '', NULL, '步虛詞十首 七 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb4b2d7b-1327-4300-8dd7-7857ae619dd4', '步虛詞十首 八', '步虛词十首 八', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["高情無侈靡，遇物生華光。","至樂無簫歌，金玉音琅琅。","或登明真臺，宴此羽景堂。","杳靄結寶雲，霏微散靈香。","天人誠遐曠，歡泰不可量。"]', '["高情無侈靡，遇物生华光。","至乐無簫歌，金玉音琅琅。","或登明真台，宴此羽景堂。","杳靄結寶云，霏微散靈香。","天人誠遐曠，歡泰不可量。"]', '诗', 'shi', '', NULL, '步虛詞十首 八 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a09d87a-ba13-4a0f-9ef2-396a987f222b', '步虛詞十首 九', '步虛词十首 九', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["爰從太微上，肆覲虛皇尊。","騰我八景輿，威遲入天門。","既登玉宸庭，肅肅仰紫軒。","敢問龍漢末，如何闢乾坤。","怡然輟雲璈，告我希夷言。","幸聞至精理，方見造化源。"]', '["爰從太微上，肆覲虛皇尊。","腾我八景輿，威遲入天门。","既登玉宸庭，肅肅仰紫軒。","敢问龙漢末，如何闢乾坤。","怡然輟云璈，告我希夷言。","幸闻至精理，方见造化源。"]', '诗', 'shi', '', NULL, '步虛詞十首 九 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a97f541a-39b9-486b-b962-d6b05303c43f', '步虛詞十首 十', '步虛词十首 十', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["二氣播萬有，化機無停輪。","而我操其端，乃能出陶鈞。","寥寥大漠上，所遇皆清真。","澄瑩含元和，氣同自相親。","絳樹結丹實，紫霞流碧津。","以茲保童嬰，永用超形神。"]', '["二氣播万有，化機無停輪。","而我操其端，乃能出陶鈞。","寥寥大漠上，所遇皆清真。","澄瑩含元和，氣同自相親。","絳樹結丹實，紫霞流碧津。","以茲保童嬰，永用超形神。"]', '诗', 'shi', '', NULL, '步虛詞十首 十 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865a0bf9-b994-4ce1-ba27-d1bbfc599c3a', '登北固山望海', '登北固山望海', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["此山鎮京口，逈出滄海湄。","躋覽何所見，茫茫潮汐馳。","雲生蓬萊島，日出扶桑枝。","萬里混一色，焉能分兩儀。","願言策煙駕，縹緲尋安期。","揮手謝人境，吾將從此辭。"]', '["此山鎮京口，逈出滄海湄。","躋覽何所见，茫茫潮汐驰。","云生蓬萊島，日出扶桑枝。","万里混一色，焉能分兩儀。","願言策煙駕，縹緲尋安期。","揮手謝人境，吾將從此辞。"]', '诗', 'shi', '', NULL, '登北固山望海 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f16de20-4d22-47ea-8602-467351731f10', '聽尹鍊師彈琴', '听尹鍊師彈琴', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["至樂本太一，幽琴和乾坤。","鄭聲久亂雅，此道稀能尊。","吾見尹仙翁，伯牙今復存。","衆人乘其流，夫子達其源。","在山峻峰峙，在水洪濤奔。","都忘邇城闕，但覺清心魂。","代乏識微者，幽音誰與論。"]', '["至乐本太一，幽琴和乾坤。","鄭声久亂雅，此道稀能尊。","吾见尹仙翁，伯牙今复存。","衆人乘其流，夫子達其源。","在山峻峰峙，在水洪濤奔。","都忘邇城闕，但覺清心魂。","代乏識微者，幽音誰與論。"]', '诗', 'shi', '', NULL, '聽尹鍊師彈琴 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0160b6eb-58f0-4b17-95ae-31ff6dce6265', '題龔山人草堂', '題龔山人草堂', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["世人負一美，未肯甘陸沉。","獨抱匡濟器，能懷真隱心。","結廬邇城郭，及到雲木深。","滅跡慕潁陽，忘機同漢陰。","啓戶面白水，憑軒對蒼岑。","但歌考槃詩，不學梁父吟。","茲道我所適，感君齊素襟。","勗哉龔夫子，勿使囂塵侵。"]', '["世人負一美，未肯甘陸沉。","独抱匡濟器，能懷真隐心。","結廬邇城郭，及到云木深。","滅跡慕潁陽，忘機同漢陰。","啓戶面白水，憑軒对蒼岑。","但歌考槃诗，不学梁父吟。","茲道我所適，感君齊素襟。","勗哉龔夫子，勿使囂塵侵。"]', '诗', 'shi', '', NULL, '題龔山人草堂 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c309e188-c4dc-4df1-8130-7d42c42f4c00', '遊廬山五老峰', '游廬山五老峰', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["彭蠡隱深翠，滄波照芙蓉。","日初金光滿，景落黛色濃。","雲外聽猨鳥，煙中見杉松。","自然符幽情，瀟灑愜所從。","整策務探討，嬉遊任從容。","玉膏正滴瀝，瑤草多䒠茸。","羽人栖層崖，道合乃一逢。","揮手欲輕舉，爲余扣瓊鐘。","空香清人心，正氣信有宗。","永用謝物累，吾將乘鸞龍。"]', '["彭蠡隐深翠，滄波照芙蓉。","日初金光满，景落黛色濃。","云外听猨鸟，煙中见杉松。","自然符幽情，瀟灑愜所從。","整策務探討，嬉游任從容。","玉膏正滴瀝，瑤草多䒠茸。","羽人栖層崖，道合乃一逢。","揮手欲轻舉，爲余扣瓊鐘。","空香清人心，正氣信有宗。","永用謝物累，吾將乘鸾龙。"]', '诗', 'shi', '', NULL, '遊廬山五老峰 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b65e9b1-3c1c-47a2-a4a2-ccc418f1ae5d', '登廬山東峰觀九江合彭蠡湖', '登廬山东峰观九江合彭蠡湖', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["百川灌彭蠡，秋水方浩浩。","九派混東流，朝宗合天沼。","寫心陟雲峰，縱目還縹緲。","宛轉衆浦分，差池羣山繞。","江妃弄明霞，彷彿呈窈窕。","而我臨長風，飄然欲騰矯。","昔懷滄洲興，斯志果已紹。","焉得忘機人，相從洽魚鳥。"]', '["百川灌彭蠡，秋水方浩浩。","九派混东流，朝宗合天沼。","寫心陟云峰，縱目還縹緲。","宛轉衆浦分，差池羣山繞。","江妃弄明霞，彷彿呈窈窕。","而我臨长风，飄然欲腾矯。","昔懷滄洲兴，斯志果已紹。","焉得忘機人，相從洽鱼鸟。"]', '诗', 'shi', '', NULL, '登廬山東峰觀九江合彭蠡湖 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995a5b70-d807-44c4-bf29-f98ede5fb7f8', '建業懷古', '建業懷古', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["炎精既失御，宇內爲三分。","吳王霸荆越，建都長江濱。","爰資股肱力，以靜淮海民。","魏后欲濟師，臨流遽旋軍。","豈惟限天塹，所忌在有人。","惜哉歸命侯，淫虐敗前勳。","銜璧入洛陽，委躬爲晉臣。","無何覆宗社，爲爾含悲辛。","俄及永嘉末，中原塞胡塵。","五馬浮渡江，一龍躍天津。","此時成大業，實賴賢縉紳。","闢土雖未遠，規模亦振振。","謝公佐王室，仗節掃僞秦。","誰爲吳兵孱，用之在有倫。","荏苒宋齊末，斯須變梁陳。","綿歷已六代，興亡互紛綸。","在德不在險，成敗良有因。","高堞復于隍，廣殿摧于榛。","王風久泯滅，勝氣猶氤氳。","皇家一區域，玄化通無垠。","常言宇宙泰，忽遘雲雷屯。","極目梁宋郊，茫茫晦妖氛。","安得倚天劒，斬茲橫海鱗。","徘徊江山暮，感激爲誰申。"]', '["炎精既失御，宇內爲三分。","吳王霸荆越，建都长江濱。","爰資股肱力，以静淮海民。","魏后欲濟師，臨流遽旋軍。","豈惟限天塹，所忌在有人。","惜哉归命侯，淫虐敗前勳。","銜璧入洛陽，委躬爲晉臣。","無何覆宗社，爲爾含悲辛。","俄及永嘉末，中原塞胡塵。","五马浮渡江，一龙躍天津。","此时成大業，實賴賢縉紳。","闢土雖未远，規模亦振振。","謝公佐王室，仗節掃僞秦。","誰爲吳兵孱，用之在有倫。","荏苒宋齊末，斯須变梁陳。","綿歷已六代，兴亡互紛綸。","在德不在險，成敗良有因。","高堞复于隍，廣殿摧于榛。","王风久泯滅，勝氣猶氤氳。","皇家一區域，玄化通無垠。","常言宇宙泰，忽遘云雷屯。","極目梁宋郊，茫茫晦妖氛。","安得倚天劒，斬茲橫海鱗。","徘徊江山暮，感激爲誰申。"]', '诗', 'shi', '', NULL, '建業懷古 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b47ac94-7d04-4104-b2dd-101e3ed99d2f', '經羊角哀墓作', '經羊角哀墓作', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["祇召出江國，路傍旌古墳。","伯桃葬角哀，墓近荆將軍。","神道不相得，稱兵解其紛。","幽明信難知，勝負理莫分。","長呼遂刎頸，此節古未聞。","兩賢結情愛，骨肉何足云。","感子初併糧，我心正氛氳。","遲迴駐征騎，不覺空林醺。"]', '["祇召出江国，路傍旌古墳。","伯桃葬角哀，墓近荆將軍。","神道不相得，稱兵解其紛。","幽明信难知，勝負理莫分。","长呼遂刎頸，此節古未闻。","兩賢結情愛，骨肉何足云。","感子初併糧，我心正氛氳。","遲迴駐征騎，不覺空林醺。"]', '诗', 'shi', '', NULL, '經羊角哀墓作 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1422a3b8-f6db-44e5-a842-3a1c44359b59', '過天門山懷友', '過天门山懷友', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["舉帆遇風勁，逸勢如飛奔。","縹緲凌煙波，崩騰走川原。","兩山夾滄江，豁爾開天門。","須臾輕舟遠，想象孤嶼存。","歸路日已近，怡然慰心魂。","所經多奇趣，待與吾友論。","一日如三秋，相思意彌敦。"]', '["舉帆遇风勁，逸勢如飞奔。","縹緲凌煙波，崩腾走川原。","兩山夾滄江，豁爾开天门。","須臾轻舟远，想象孤嶼存。","归路日已近，怡然慰心魂。","所經多奇趣，待與吾友論。","一日如三秋，相思意彌敦。"]', '诗', 'shi', '', NULL, '過天門山懷友 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7f5880-f3e4-4d14-94c3-9051c847cfae', '舟中遇柳伯存歸潛山因有此贈 一', '舟中遇柳伯存归潛山因有此贈 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["澆風久成俗，真隱不可求。","何悟非所冀，得君在扁舟。","目擊道已存，一笑遂忘言。","況觀絕交書，兼覩箴隱文。"]', '["澆风久成俗，真隐不可求。","何悟非所冀，得君在扁舟。","目擊道已存，一笑遂忘言。","況观絕交书，兼覩箴隐文。"]', '诗', 'shi', '', NULL, '舟中遇柳伯存歸潛山因有此贈 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24fe613-0c93-4256-b0b4-7d85ef1359e2', '舟中遇柳伯存歸潛山因有此贈 二', '舟中遇柳伯存归潛山因有此贈 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["見君浩然心，視世如浮空。","君歸潛山曲，我復廬山中。","形間心不隔，誰能嗟異同。","他日或相訪，無辭馭冷風。"]', '["见君浩然心，視世如浮空。","君归潛山曲，我复廬山中。","形间心不隔，誰能嗟異同。","他日或相訪，無辞馭冷风。"]', '诗', 'shi', '', NULL, '舟中遇柳伯存歸潛山因有此贈 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1113e339-6271-481a-9f5c-8514d36134e9', '舟中夜行', '舟中夜行', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["榜人識江路，挂席從宵征。","莫辨洲渚狀，但聞風波驚。","陰雲正飄颻，落月無光晶。","豈不畏艱險，所憑在忠誠。","何時達遙夜，佇見初日明。"]', '["榜人識江路，挂席從宵征。","莫辨洲渚狀，但闻风波驚。","陰云正飄颻，落月無光晶。","豈不畏艱險，所憑在忠誠。","何时達遙夜，佇见初日明。"]', '诗', 'shi', '', NULL, '舟中夜行 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c998ab-04ca-412c-98fc-f7e128be9340', '晚到湖口見廬山作呈諸故人', '晚到湖口见廬山作呈諸故人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["夜舟達湖口，漸近廬山側。","高高標橫天，隱隱何峻極。","石鏡啓晨暉，罏煙凝寒色。","旅泊將休暇，歸心已隮陟。","虛名久爲累，使我辭逸域。","良願道不違，幽襟果茲得。","故人在雲嶠，乃復同晏息。","鴻飛入青冥，虞氏罷繒弋。"]', '["夜舟達湖口，漸近廬山側。","高高標橫天，隐隐何峻極。","石镜啓晨暉，罏煙凝寒色。","旅泊將休暇，归心已隮陟。","虛名久爲累，使我辞逸域。","良願道不違，幽襟果茲得。","故人在云嶠，乃复同晏息。","鴻飞入青冥，虞氏罷繒弋。"]', '诗', 'shi', '', NULL, '晚到湖口見廬山作呈諸故人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b74e99-e532-4bd3-b382-643ee57f9ea1', '苦春霖作寄友', '苦春霖作寄友', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["應龍遷南方，霪雨備江干。","俯望失平陸，仰瞻隱崇巒。","陰風斂暄氣，殘月淒已寒。","時鳥戢好音，衆芳亦微殘。","萬流注江湖，日夜增波瀾。","數君曠不接，悄然無與歡。","對酒聊自娛，援琴爲誰彈。","彈爲愁霖引，曲罷仍永歎。","此歎因感物，誰能識其端。","寫懷寄同心，詞極意未殫。"]', '["應龙遷南方，霪雨備江干。","俯望失平陸，仰瞻隐崇巒。","陰风斂暄氣，殘月淒已寒。","时鸟戢好音，衆芳亦微殘。","万流注江湖，日夜增波瀾。","數君曠不接，悄然無與歡。","对酒聊自娛，援琴爲誰彈。","彈爲愁霖引，曲罷仍永歎。","此歎因感物，誰能識其端。","寫懷寄同心，词極意未殫。"]', '诗', 'shi', '', NULL, '苦春霖作寄友 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28d04d1-9f9b-492e-8f1f-2d70542ffa27', '酬葉縣劉明府避地廬山言懷詒鄭錄事昆季苟尊師兼見贈之', '酬葉縣劉明府避地廬山言懷詒鄭錄事昆季苟尊師兼见贈之', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["明哲良罕遇，遇君輙思齊。","挺生著天爵，自可析人珪。","河洛初沸騰，方期掃虹霓。","時命竟未合，安能親鼓鼙。","從此罷飛鳧，投簪辭割雞。","驅車適南土，忠孝兩不暌。","廬嶽鎮江介，於焉愜林棲。","入門披綵服，出谷杖紅藜。","隱令舊閭里，而今復成躋。","鄭公解簪紱，華萼曜松谿。","賢哉苟徵君，滅跡爲圃畦。","顧已成非薄，忝茲忘筌蹄。","相觀對綠樽，逸思凌丹梯。","道泰我長往，時清君勿迷。","王孫且無歸，芳草正萋萋。"]', '["明哲良罕遇，遇君輙思齊。","挺生著天爵，自可析人珪。","河洛初沸腾，方期掃虹霓。","时命竟未合，安能親鼓鼙。","從此罷飞鳧，投簪辞割雞。","驱车適南土，忠孝兩不暌。","廬嶽鎮江介，於焉愜林棲。","入门披綵服，出谷杖紅藜。","隐令旧閭里，而今复成躋。","鄭公解簪紱，华萼曜松谿。","賢哉苟徵君，滅跡爲圃畦。","顧已成非薄，忝茲忘筌蹄。","相观对綠樽，逸思凌丹梯。","道泰我长往，时清君勿迷。","王孫且無归，芳草正萋萋。"]', '诗', 'shi', '', NULL, '酬葉縣劉明府避地廬山言懷詒鄭錄事昆季苟尊師兼見贈之 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b3b94e4-5b5b-4577-8a4c-9b7278518111', '高士詠 混元皇帝', '高士詠 混元皇帝', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["玄元九仙主，道冠三氣初。","應物方佐命，棲真亦歸居。","貽篇訓終古，駕景還太虛。","孔父歎猶龍，誰能知所如。"]', '["玄元九仙主，道冠三氣初。","應物方佐命，棲真亦归居。","貽篇訓終古，駕景還太虛。","孔父歎猶龙，誰能知所如。"]', '诗', 'shi', '', NULL, '高士詠 混元皇帝 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('815fbf8d-d9ee-4abe-846d-52d9ab730177', '高士詠 廣成子', '高士詠 廣成子', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["廣成臥雲岫，緬邈逾千齡。","軒轅來順風，問道修神形。","至言發玄理，告以從杳冥。","三光入無窮，寂默返太寧。"]', '["廣成臥云岫，緬邈逾千齡。","軒轅来順风，问道修神形。","至言發玄理，告以從杳冥。","三光入無窮，寂默返太寧。"]', '诗', 'shi', '', NULL, '高士詠 廣成子 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e9d3e1-d1da-417f-a62c-d2157b443aa9', '高士詠 許先生', '高士詠 許先生', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["大名賢所尚，寶位聖所珍。","皎皎許仲武，遺之若纖塵。","棄瓢箕山下，洗耳潁水濱。","物外兩寂寞，獨與玄冥均。"]', '["大名賢所尚，寶位聖所珍。","皎皎許仲武，遺之若纖塵。","棄瓢箕山下，洗耳潁水濱。","物外兩寂寞，独與玄冥均。"]', '诗', 'shi', '', NULL, '高士詠 許先生 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f47f79b-5c79-4b1b-8780-58600f08053a', '高士詠 樊先生', '高士詠 樊先生', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["巢父志何遠，潛精人莫知。","耻聞讓王事，飲犢方見移。","不欲散大朴，焉能爲堯師。","鍊真自輕舉，浮世何足遺。"]', '["巢父志何远，潛精人莫知。","耻闻讓王事，饮犢方见移。","不欲散大朴，焉能爲堯師。","鍊真自轻舉，浮世何足遺。"]', '诗', 'shi', '', NULL, '高士詠 樊先生 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618d7c33-d856-4465-a8bf-f0adf1df3564', '高士詠 柏成子高', '高士詠 柏成子高', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["大禹受禪讓，子高辭諸侯。","退躬適外野，放浪夫何求。","萬乘造中畝，一言良見酬。","俋俋耕不顧，斯情邈難儔。"]', '["大禹受禪讓，子高辞諸侯。","退躬適外野，放浪夫何求。","万乘造中畝，一言良见酬。","俋俋耕不顧，斯情邈难儔。"]', '诗', 'shi', '', NULL, '高士詠 柏成子高 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361e8e0c-082b-4461-aad2-a0c0eabfae58', '高士詠 臧丈人', '高士詠 臧丈人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["臧叟隱中壑，垂綸心浩然。","文王感昔夢，授政道斯全。","一遵無爲術，三載淳化宣。","功成遂不處，遁跡符沖玄。"]', '["臧叟隐中壑，垂綸心浩然。","文王感昔梦，授政道斯全。","一遵無爲術，三載淳化宣。","功成遂不处，遁跡符沖玄。"]', '诗', 'shi', '', NULL, '高士詠 臧丈人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29759b6-ffce-4b78-b057-faf25480945e', '高士詠 伯夷叔齊', '高士詠 伯夷叔齊', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["夷齊互崇讓，棄國從所欽。","聿來及宗周，乃復非其心。","世濁不可處，冰清首陽岑。","采薇詠羲農，高義越古今。"]', '["夷齊互崇讓，棄国從所欽。","聿来及宗周，乃复非其心。","世濁不可处，冰清首陽岑。","采薇詠羲農，高義越古今。"]', '诗', 'shi', '', NULL, '高士詠 伯夷叔齊 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a05218-fbf2-4dba-b102-8152e85b0956', '高士詠 南華真人', '高士詠 南华真人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["南華源道宗，玄遠故不測。","動與造化遊，靜合太和息。","放曠生死外，逍遙神明域。","況乃資九丹，輕舉歸太極。"]', '["南华源道宗，玄远故不測。","动與造化游，静合太和息。","放曠生死外，逍遙神明域。","況乃資九丹，轻舉归太極。"]', '诗', 'shi', '', NULL, '高士詠 南華真人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e62b92d-ee8c-4064-9bfc-be55479eca2a', '高士詠 沖虛真人', '高士詠 沖虛真人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["沖虛冥至理，體道自玄通。","不受子陽祿，但飲壺丘宗。","泠然竟何依，撓挑遊大空。","未知風乘我，爲是我乘風。"]', '["沖虛冥至理，體道自玄通。","不受子陽祿，但饮壺丘宗。","泠然竟何依，撓挑游大空。","未知风乘我，爲是我乘风。"]', '诗', 'shi', '', NULL, '高士詠 沖虛真人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a9ba2c-0a7d-4375-9e5d-af110f6bd598', '高士詠 洞靈真人', '高士詠 洞靈真人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["亢倉致虛極，潛跡依遠岫。","智去愚獨留，日虧歲方就。","鄉人謀尸祝，不欲聞俎豆。","尚賢非至理，堯舜固爲陋。"]', '["亢倉致虛極，潛跡依远岫。","智去愚独留，日虧歲方就。","乡人謀尸祝，不欲闻俎豆。","尚賢非至理，堯舜固爲陋。"]', '诗', 'shi', '', NULL, '高士詠 洞靈真人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f35660-4b6f-4c40-8117-6a13571a55cd', '高士詠 通玄真人', '高士詠 通玄真人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["通玄貴陰德，利物非市朝。","悠然大江上，散髮揮輕橈。","已陳緇帷說，復表滄浪謠。","滅跡竟何往，遺文獨昭昭。"]', '["通玄貴陰德，利物非市朝。","悠然大江上，散髮揮轻橈。","已陳緇帷说，复表滄浪謠。","滅跡竟何往，遺文独昭昭。"]', '诗', 'shi', '', NULL, '高士詠 通玄真人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297ebe1c-f57b-4280-83cf-6e501c319505', '高士詠 文始真人', '高士詠 文始真人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["文始通道源，含光隱關吏。","遙欣紫氣浮，果驗真人至。","玄誥已云錫，世榮何足累。","高步三清境，超登九仙位。"]', '["文始通道源，含光隐关吏。","遙欣紫氣浮，果驗真人至。","玄誥已云錫，世榮何足累。","高步三清境，超登九仙位。"]', '诗', 'shi', '', NULL, '高士詠 文始真人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af0bf48-264c-4397-9c1c-5ef4ff2279da', '高士詠 榮啓期', '高士詠 榮啓期', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["榮期信知止，帶索無所求。","外物非我尚，琴歌自優游。","三樂通至道，一言醉孔丘。","居常以待終，嘯傲夫何憂。"]', '["榮期信知止，带索無所求。","外物非我尚，琴歌自優游。","三乐通至道，一言醉孔丘。","居常以待終，嘯傲夫何憂。"]', '诗', 'shi', '', NULL, '高士詠 榮啓期 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce4385f4-a8fd-4e6a-a091-c86e07b65bb9', '高士詠 長沮桀溺', '高士詠 长沮桀溺', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["賢哉彼沮溺，避世全其真。","孔父棲棲者，征途方問津。","行藏既異跡，語默豈同倫。","耦耕長林下，甘與鳥雀羣。"]', '["賢哉彼沮溺，避世全其真。","孔父棲棲者，征途方问津。","行藏既異跡，語默豈同倫。","耦耕长林下，甘與鸟雀羣。"]', '诗', 'shi', '', NULL, '高士詠 長沮桀溺 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7610ff06-b818-481b-9b9e-57071093312e', '高士詠 顏闔', '高士詠 顏闔', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["世情矜寵譽，傚節徼當時。","顏闔遵無名，飯牛聊自怡。","逃聘鄙束帛，鑿坏欣茅茨。","託聘囂塵表，放浪世莫知。"]', '["世情矜寵譽，傚節徼當时。","顏闔遵無名，飯牛聊自怡。","逃聘鄙束帛，鑿坏欣茅茨。","託聘囂塵表，放浪世莫知。"]', '诗', 'shi', '', NULL, '高士詠 顏闔 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2008d984-4395-4f91-b88c-45b305a482bd', '高士詠 老萊夫妻', '高士詠 老萊夫妻', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["萊氏道已遠，懿妻德彌清。","一遁囂煩趣，永契雲壑情。","祿位非所重，拂衣遂遐征。","杳然從我願，豈爲物所攖。"]', '["萊氏道已远，懿妻德彌清。","一遁囂煩趣，永契云壑情。","祿位非所重，拂衣遂遐征。","杳然從我願，豈爲物所攖。"]', '诗', 'shi', '', NULL, '高士詠 老萊夫妻 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3974ab94-a6e0-43db-8838-ec48bea1fd80', '高士詠 楚狂接輿夫妻', '高士詠 楚狂接輿夫妻', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["接輿耽沖玄，伉儷亦真逸。","傲然辭徵聘，耕績代祿秩。","鳳歌誡文宣，龍德遂隱密。","一遊峨嵋上，千載保靈術。"]', '["接輿耽沖玄，伉儷亦真逸。","傲然辞徵聘，耕績代祿秩。","鳳歌誡文宣，龙德遂隐密。","一游峨嵋上，千載保靈術。"]', '诗', 'shi', '', NULL, '高士詠 楚狂接輿夫妻 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9cad435-e097-45ce-a8f2-19bb273fc97e', '高士詠 鄭商人弦高', '高士詠 鄭商人弦高', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["卓哉弦高子，商隱獨摽奇。","傚謀全鄭國，矯命犒秦師。","賞神義不受，存公滅其私。","虛心貴無名，遠跡居九夷。"]', '["卓哉弦高子，商隐独摽奇。","傚謀全鄭国，矯命犒秦師。","賞神義不受，存公滅其私。","虛心貴無名，远跡居九夷。"]', '诗', 'shi', '', NULL, '高士詠 鄭商人弦高 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83795a0e-0f13-4c85-a682-464b6d461fad', '高士詠 柳下惠', '高士詠 柳下惠', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["展禽抱純粹，滅跡和光塵。","高情遺軒冕，降志救世人。","百行既無點，三黜道彌真。","信謂德超古，豈惟言中倫。"]', '["展禽抱純粹，滅跡和光塵。","高情遺軒冕，降志救世人。","百行既無点，三黜道彌真。","信謂德超古，豈惟言中倫。"]', '诗', 'shi', '', NULL, '高士詠 柳下惠 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101f606f-e0a3-4d91-9851-bf63c20bd824', '高士詠 荷蓧晨門', '高士詠 荷蓧晨门', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["荷蓧隱耕藝，晨門潛抱關。","道尊名可賤，理愜心彌閑。","混跡是非域，縱懷天地間。","同譏孔宣父，匿景杳不還。"]', '["荷蓧隐耕藝，晨门潛抱关。","道尊名可賤，理愜心彌闲。","混跡是非域，縱懷天地间。","同譏孔宣父，匿景杳不還。"]', '诗', 'shi', '', NULL, '高士詠 荷蓧晨門 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97eb79e4-088d-456c-9c53-f0356a3f6621', '高士詠 漢陰丈人', '高士詠 漢陰丈人', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["野哉漢陰叟，好古遂忘機。","抱甕誠亦勤，守朴全道微。","子貢初不達，聽言識其非。","已爲風波人，怳惘失所依。"]', '["野哉漢陰叟，好古遂忘機。","抱甕誠亦勤，守朴全道微。","子貢初不達，听言識其非。","已爲风波人，怳惘失所依。"]', '诗', 'shi', '', NULL, '高士詠 漢陰丈人 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d059add4-8828-4772-a5e6-a160c09e0448', '高士詠 於陵夫妻', '高士詠 於陵夫妻', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["皎皎於陵子，己賢妻亦明。","安茲道德重，顧彼浮華輕。","琴書不爲務，祿位不可榮。","逃跡終灌園，誰能達世情。"]', '["皎皎於陵子，己賢妻亦明。","安茲道德重，顧彼浮华轻。","琴书不爲務，祿位不可榮。","逃跡終灌园，誰能達世情。"]', '诗', 'shi', '', NULL, '高士詠 於陵夫妻 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5897e695-5ebe-4ae9-b493-380210088784', '高士詠 項槖', '高士詠 項槖', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["太項冥虛極，微遠不可究。","稟量合太初，返形寄童幼。","孔父慙至理，顏生賴真授。","泛然同萬流，無跡世莫覯。"]', '["太項冥虛極，微远不可究。","稟量合太初，返形寄童幼。","孔父慙至理，顏生賴真授。","泛然同万流，無跡世莫覯。"]', '诗', 'shi', '', NULL, '高士詠 項槖 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88329648-6912-4775-846d-75dbc2e18ec8', '高士詠 太伯延陵', '高士詠 太伯延陵', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["太伯全至讓，遠投蠻夷間。","延陵嗣高風，去國不復還。","尊榮比蟬翼，道義侔崇山。","元規與峻節，歷世無能攀。"]', '["太伯全至讓，远投蠻夷间。","延陵嗣高风，去国不复還。","尊榮比蟬翼，道義侔崇山。","元規與峻節，歷世無能攀。"]', '诗', 'shi', '', NULL, '高士詠 太伯延陵 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2d3dc8-3c7b-4de2-aa4a-3ed0d50f3eb4', '高士詠 壺丘子', '高士詠 壺丘子', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["壺丘道爲量，玄虛固難知。","季咸曜淺術，禦寇初深疑。","至人忘禍福，感變靡定期。","太沖杳無朕，元化誰能知。"]', '["壺丘道爲量，玄虛固难知。","季咸曜淺術，禦寇初深疑。","至人忘禍福，感变靡定期。","太沖杳無朕，元化誰能知。"]', '诗', 'shi', '', NULL, '高士詠 壺丘子 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94cfe70-fe7c-4677-84c7-99a7f121fc7c', '高士詠 段干木', '高士詠 段干木', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["干木布衣者，守道杜衡門。","德光義且富，肯易王侯尊。","魏主欽其賢，軾廬情亦敦。","秦兵遂不舉，高臥爲國藩。"]', '["干木布衣者，守道杜衡门。","德光義且富，肯易王侯尊。","魏主欽其賢，軾廬情亦敦。","秦兵遂不舉，高臥爲国藩。"]', '诗', 'shi', '', NULL, '高士詠 段干木 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b72f5c9e-bcc2-434c-a760-92d3d1e7036c', '高士詠 魯仲連', '高士詠 魯仲連', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["仲連秉奇節，釋難含道情。","一言却秦圍，片札降聊城。","辭金義何遠，讓祿心益清。","處世功已立，拂衣蹈滄溟。"]', '["仲連秉奇節，釋难含道情。","一言却秦圍，片札降聊城。","辞金義何远，讓祿心益清。","处世功已立，拂衣蹈滄溟。"]', '诗', 'shi', '', NULL, '高士詠 魯仲連 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4701377e-18fd-4c56-8859-76aa051cb716', '高士詠 顏歜', '高士詠 顏歜', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["高哉彼顏歜，逸氣陵齊宣。","道尊義不屈，士重王來前。","榮祿安可誘，保和從自然。","放情任所尚，長揖歸山泉。"]', '["高哉彼顏歜，逸氣陵齊宣。","道尊義不屈，士重王来前。","榮祿安可誘，保和從自然。","放情任所尚，长揖归山泉。"]', '诗', 'shi', '', NULL, '高士詠 顏歜 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5e87bc-fc60-492b-b211-d27267be0eb2', '高士詠 周豐', '高士詠 周豐', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["周豐貴隱耀，靜默尊無名。","魯侯詢政體，喻以治道精。","莅人在忠慤，疑叛由會盟。","一言達至義，千載良爲程。"]', '["周豐貴隐耀，静默尊無名。","魯侯詢政體，喻以治道精。","莅人在忠慤，疑叛由會盟。","一言達至義，千載良爲程。"]', '诗', 'shi', '', NULL, '高士詠 周豐 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9fd06f9-04d9-4eec-b3f1-150997ac1f07', '高士詠 師金', '高士詠 師金', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["聖人貴素朴，禮義非玄同。","師金告顏生，可謂達化宗。","夫子飾芻狗，自然道斯窮。","應物方矯行，俯仰靡不通。"]', '["聖人貴素朴，禮義非玄同。","師金告顏生，可謂達化宗。","夫子飾芻狗，自然道斯窮。","應物方矯行，俯仰靡不通。"]', '诗', 'shi', '', NULL, '高士詠 師金 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5d5c5d-8485-4bc1-a27b-716d9f0e2d19', '高士詠 南郭子綦', '高士詠 南郭子綦', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["子綦方隱几，冥寂久灰心。","悟來應顏游，清義杳何深。","含響盡天籟，有言同鷇音。","是非不足辯，安用勞神襟。"]', '["子綦方隐几，冥寂久灰心。","悟来應顏游，清義杳何深。","含响尽天籟，有言同鷇音。","是非不足辯，安用勞神襟。"]', '诗', 'shi', '', NULL, '高士詠 南郭子綦 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa77330-21b3-4ee6-910c-9b43b7cd7aa1', '高士詠 黔婁先生', '高士詠 黔婁先生', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["黔婁蘊雅操，守約遺代華。","淡然常有怡，與物固無瑕。","哲妻配明德，既沒辯正邪。","辭祿乃餘貴，表謚良可嘉。"]', '["黔婁蘊雅操，守約遺代华。","淡然常有怡，與物固無瑕。","哲妻配明德，既沒辯正邪。","辞祿乃餘貴，表謚良可嘉。"]', '诗', 'shi', '', NULL, '高士詠 黔婁先生 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9302550-3c6c-4bc5-954e-d8aeb6bbe6e3', '高士詠 原憲', '高士詠 原憲', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["原生何淡漠，觀妙自怡性。","蓬戶常晏如，弦歌樂天命。","無財方是貧，有道固非病。","木賜欽高風，退慙車馬盛。"]', '["原生何淡漠，观妙自怡性。","蓬戶常晏如，弦歌乐天命。","無財方是貧，有道固非病。","木賜欽高风，退慙车马盛。"]', '诗', 'shi', '', NULL, '高士詠 原憲 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a375e3-64d6-4bdd-8b7d-a6b9daad709d', '高士詠 商山四皓', '高士詠 商山四皓', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["萬方厭秦德，戰伐何紛紛。","四皓同無爲，丘中臥白雲。","自漢成帝業，一來翼儲君。","知幾道可尚，隱括成元勳。"]', '["万方厭秦德，戰伐何紛紛。","四皓同無爲，丘中臥白云。","自漢成帝業，一来翼儲君。","知幾道可尚，隐括成元勳。"]', '诗', 'shi', '', NULL, '高士詠 商山四皓 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae3e7581-87eb-4ee5-9042-382ceb341ca2', '高士詠 河上公', '高士詠 河上公', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["邈邈河上叟，無名契虛沖。","靈關暢玄旨，萬乘趨道風。","寵辱不可累，飄然在雲空。","獨與造化友，誰能測無窮。"]', '["邈邈河上叟，無名契虛沖。","靈关暢玄旨，万乘趨道风。","寵辱不可累，飄然在云空。","独與造化友，誰能測無窮。"]', '诗', 'shi', '', NULL, '高士詠 河上公 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1199e635-03be-4fe4-9bfc-a241552cbf5c', '高士詠 東方曼倩', '高士詠 东方曼倩', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["東方稟易象，翫世隱廊廟。","棲心抱清微，混跡秘光耀。","玄覽寄數術，納規在談笑。","賣藥五湖中，還從九仙妙。"]', '["东方稟易象，翫世隐廊廟。","棲心抱清微，混跡秘光耀。","玄覽寄數術，納規在談笑。","賣藥五湖中，還從九仙妙。"]', '诗', 'shi', '', NULL, '高士詠 東方曼倩 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a73dbc-3957-4f99-bda4-94a6628d14d8', '高士詠 嚴君平', '高士詠 嚴君平', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["漢皇舉遺逸，多士咸已寧。","至德不可拔，嚴君獨湛冥。","卜筮訓流俗，指歸暢玄經。","閉關動元象，何必遊紫庭。"]', '["漢皇舉遺逸，多士咸已寧。","至德不可拔，嚴君独湛冥。","卜筮訓流俗，指归暢玄經。","閉关动元象，何必游紫庭。"]', '诗', 'shi', '', NULL, '高士詠 嚴君平 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6c65602-4f55-4cce-a31d-b9381e8ca603', '高士詠 司馬季主', '高士詠 司马季主', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["季主超常倫，沈跡寄卜筮。","宋賈二大夫，停車試觀藝。","高談哂朝列，洪辯不可際。","終秉鸞鳳心，翛然已遐逝。"]', '["季主超常倫，沈跡寄卜筮。","宋賈二大夫，停车試观藝。","高談哂朝列，洪辯不可際。","終秉鸾鳳心，翛然已遐逝。"]', '诗', 'shi', '', NULL, '高士詠 司馬季主 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00afd22a-dab6-4e8d-bae1-7af498965c73', '高士詠 鄭子真張仲蔚', '高士詠 鄭子真張仲蔚', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["子真巖石下，仲蔚蓬蒿居。","禮聘終不屈，清貧長晏如。","心情在耕藝，養壽資玄虛。","至樂非外物，道冥歡有餘。"]', '["子真巖石下，仲蔚蓬蒿居。","禮聘終不屈，清貧长晏如。","心情在耕藝，養壽資玄虛。","至乐非外物，道冥歡有餘。"]', '诗', 'shi', '', NULL, '高士詠 鄭子真張仲蔚 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25cf602-6344-43ed-a417-7cd56e69de4e', '高士詠 嚴子陵', '高士詠 嚴子陵', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["漢皇敦故友，物色訪嚴生。","三聘迨深澤，一來遇帝庭。","紫宸同御寢，玄象驗客星。","祿位終不屈，雲山樂躬耕。"]', '["漢皇敦故友，物色訪嚴生。","三聘迨深澤，一来遇帝庭。","紫宸同御寢，玄象驗客星。","祿位終不屈，云山乐躬耕。"]', '诗', 'shi', '', NULL, '高士詠 嚴子陵 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('452b7ad7-0a78-4a0a-aba7-67cf6056acf2', '高士詠 向子平', '高士詠 向子平', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["子平好真隱，清淨翫老易。","探玄樂無爲，觀象驗損益。","常抱方外心，且紆人間跡。","一朝畢婚娶，五嶽遂長適。"]', '["子平好真隐，清淨翫老易。","探玄乐無爲，观象驗損益。","常抱方外心，且紆人间跡。","一朝畢婚娶，五嶽遂长適。"]', '诗', 'shi', '', NULL, '高士詠 向子平 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3c1351-ddef-4689-abb4-b08b46b54028', '高士詠 韓康', '高士詠 韓康', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["伯休抱遐心，隱括自爲美。","賣藥不二價，有名反深耻。","安能受玄纁，秉願終素履。","逃遁從所尚，蕭蕭絕塵軌。"]', '["伯休抱遐心，隐括自爲美。","賣藥不二價，有名反深耻。","安能受玄纁，秉願終素履。","逃遁從所尚，蕭蕭絕塵軌。"]', '诗', 'shi', '', NULL, '高士詠 韓康 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9640bced-7420-4493-9fc6-4d3f2b52c419', '高士詠 臺佟管寧', '高士詠 台佟管寧', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["吾嘉臺孝威，樂道隱巖穴。","吾尚管幼安，棲真養高節。","採藥聊自給，觀書任所悅。","風塵不可混，真素比松雪。"]', '["吾嘉台孝威，乐道隐巖穴。","吾尚管幼安，棲真養高節。","採藥聊自給，观书任所悅。","风塵不可混，真素比松雪。"]', '诗', 'shi', '', NULL, '高士詠 臺佟管寧 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466f6f7f-be93-433f-88c6-9d8d224330e0', '高士詠 高鳳', '高士詠 高鳳', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["吾觀時人趣，矯跡務馳聲。","獨有高文通，訟田求翳名。","公車徒見累，爵祿非所榮。","隱身樂魚釣，世網不可攖。"]', '["吾观时人趣，矯跡務驰声。","独有高文通，訟田求翳名。","公车徒见累，爵祿非所榮。","隐身乐鱼釣，世網不可攖。"]', '诗', 'shi', '', NULL, '高士詠 高鳳 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf009b06-d79c-4f5e-96cc-0d619c29690d', '高士詠 龐德公', '高士詠 龐德公', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["龐公棲鹿門，絕跡遠城市。","超然風塵外，自得丘壑美。","耕鑿勤厥躬，耘鋤課妻子。","保茲永無患，軒冕何足紀。"]', '["龐公棲鹿门，絕跡远城市。","超然风塵外，自得丘壑美。","耕鑿勤厥躬，耘鋤課妻子。","保茲永無患，軒冕何足紀。"]', '诗', 'shi', '', NULL, '高士詠 龐德公 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae6886a-e9ed-4ddf-9879-fedf9d73d30b', '高士詠 玄晏先生', '高士詠 玄晏先生', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["士安逾弱冠，落魄未修餙。","一朝因感激，志學忘寢食。","著書窮天人，辭聘守玄默。","薄葬信昭儉，可爲將來則。"]', '["士安逾弱冠，落魄未修餙。","一朝因感激，志学忘寢食。","著书窮天人，辞聘守玄默。","薄葬信昭儉，可爲將来則。"]', '诗', 'shi', '', NULL, '高士詠 玄晏先生 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d584d5-bc12-4271-a66d-bc7a1abc28ac', '高士詠 孫公和', '高士詠 孫公和', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["孫登好淳古，卉服從穴居。","彈琴合天和，讀易見象初。","終日無慍色，恬然在玄虛。","貽言誡叔夜，超跡安所如。"]', '["孫登好淳古，卉服從穴居。","彈琴合天和，读易见象初。","終日無慍色，恬然在玄虛。","貽言誡叔夜，超跡安所如。"]', '诗', 'shi', '', NULL, '高士詠 孫公和 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c28e3b7-93ca-46ce-8c4b-2945c5d2c80f', '高士詠 董威輦', '高士詠 董威輦', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["董京依白社，散髮詠玄風。","心出區宇外，跡參城市中。","囂塵不能雜，名位安可籠。","匿影留雅什，精微信難窮。"]', '["董京依白社，散髮詠玄风。","心出區宇外，跡參城市中。","囂塵不能杂，名位安可籠。","匿影留雅什，精微信难窮。"]', '诗', 'shi', '', NULL, '高士詠 董威輦 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a8e77d-f591-4b65-8867-e89bbb7b8476', '高士詠 郭文舉', '高士詠 郭文舉', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["郭生在童稚，已得方外心。","絕跡遺世務，棲真入長林。","元和感異類，猛獸懷德音。","不憶固無情，斯言微且深。"]', '["郭生在童稚，已得方外心。","絕跡遺世務，棲真入长林。","元和感異類，猛獸懷德音。","不憶固無情，斯言微且深。"]', '诗', 'shi', '', NULL, '高士詠 郭文舉 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc618c5-28de-4bbc-b78d-779afdd6bdb6', '高士詠 陶徵君', '高士詠 陶徵君', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["吾重陶淵明，達生知止足。","怡情在樽酒，此外無所欲。","彭澤非我榮，折腰信爲辱。","歸來北窗下，復採東籬菊。"]', '["吾重陶淵明，達生知止足。","怡情在樽酒，此外無所欲。","彭澤非我榮，折腰信爲辱。","归来北窗下，复採东籬菊。"]', '诗', 'shi', '', NULL, '高士詠 陶徵君 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11269717-6d9f-438a-8fc9-3cfa25deff6a', '元日言懷因以自勵詒諸同志', '元日言懷因以自勵詒諸同志', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["馳光無時憩，加我五十年。","知非慕伯玉，讀易宗文宣。","經世匪吾事，庶幾唯道全。","誰言帝鄉遠，自古多真仙。","餘滓永可滌，秉心方杳然。","孰能無相與，滅跡俱忘筌。","安用感時變，當期升九天。"]', '["驰光無时憩，加我五十年。","知非慕伯玉，读易宗文宣。","經世匪吾事，庶幾唯道全。","誰言帝乡远，自古多真仙。","餘滓永可滌，秉心方杳然。","孰能無相與，滅跡俱忘筌。","安用感时变，當期升九天。"]', '诗', 'shi', '', NULL, '元日言懷因以自勵詒諸同志 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0758c48-84be-455c-b4cc-48aef493230b', '同劉主簿承介建昌江泛舟作', '同劉主簿承介建昌江泛舟作', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["吾友從吏隱，和光心杳然。","鳴琴正多暇，嘯侶浮清川。","風霽遠澄映，昭昭涵洞天。","坐驚衆峰轉，乃覺孤舟遷。","崖嶼非一狀，差池過目前。","徘徊白日暮，月色江中鮮。","真興殊未已，滔滔且泝沿。","時歌滄浪曲，或誦逍遙篇。","酣暢迷夜久，遲遲方告旋。","此時無相與，其旨在忘筌。"]', '["吾友從吏隐，和光心杳然。","鳴琴正多暇，嘯侶浮清川。","风霽远澄映，昭昭涵洞天。","坐驚衆峰轉，乃覺孤舟遷。","崖嶼非一狀，差池過目前。","徘徊白日暮，月色江中鲜。","真兴殊未已，滔滔且泝沿。","时歌滄浪曲，或誦逍遙篇。","酣暢迷夜久，遲遲方告旋。","此时無相與，其旨在忘筌。"]', '诗', 'shi', '', NULL, '同劉主簿承介建昌江泛舟作 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfca031-5eec-47a5-ae45-6bc4a0836f52', '緱山廟', '緱山廟', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["朝吾自嵩山，驅駕遵洛汭。","逶遲轘轅側，仰望緱山際。","王子謝時人，笙歌此賓帝。","仙材夙所稟，寶位焉足繫。","爲迫丹霄期，闕流蒼生惠。","高蹤邈千載，遺廟今一詣。","肅肅生風雲，森森列松桂。","大君弘至道，層構何壯麗。","稽首環金壇，焚香陟瑤砌。","伊余超浮俗，塵慮久已閉。","況復清夙心，蕭然叶真契。"]', '["朝吾自嵩山，驱駕遵洛汭。","逶遲轘轅側，仰望緱山際。","王子謝时人，笙歌此賓帝。","仙材夙所稟，寶位焉足繫。","爲迫丹霄期，闕流蒼生惠。","高蹤邈千載，遺廟今一詣。","肅肅生风云，森森列松桂。","大君弘至道，層構何壯丽。","稽首环金壇，焚香陟瑤砌。","伊余超浮俗，塵慮久已閉。","況复清夙心，蕭然叶真契。"]', '诗', 'shi', '', NULL, '緱山廟 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a1bd22-29b6-405d-92f3-18712e537cdf', '胡無人行', '胡無人行', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["劍頭利如芒，恆持照眼光。","鐵騎追驍虜，金羈討黠羌。","高秋八九月，胡地早風霜。","男兒不惜死，破膽與君嘗。"]', '["劍头利如芒，恆持照眼光。","鐵騎追驍虜，金羈討黠羌。","高秋八九月，胡地早风霜。","男兒不惜死，破膽與君嘗。"]', '诗', 'shi', '', NULL, '胡無人行 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617d4c8a-3953-4439-95f7-5bdc911bf633', '別章叟', '別章叟', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["平昔同邑里，經年不相思。","今日成遠別，相對心悽其。"]', '["平昔同邑里，經年不相思。","今日成远別，相对心悽其。"]', '诗', 'shi', '', NULL, '別章叟 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f91e478-2809-4ccd-8a17-aa2c17c9c6c1', '題縉雲嶺永望館', '題縉云嶺永望館', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["人驚此路險，我愛山前深。","猶恐佳趣盡，欲行且沈吟。"]', '["人驚此路險，我愛山前深。","猶恐佳趣尽，欲行且沈吟。"]', '诗', 'shi', '', NULL, '題縉雲嶺永望館 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80eeb36-8f99-4daa-8e07-fc8000834112', '題華山人所居', '題华山人所居', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["故人住南郭，邀我對芳樽。","歡暢日云暮，不知城市喧。"]', '["故人住南郭，邀我对芳樽。","歡暢日云暮，不知城市喧。"]', '诗', 'shi', '', NULL, '題華山人所居 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75e5437-816a-472d-84e4-356229ef297b', '初月', '初月', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["始看東上又西浮，圓缺何曾得自由。","照物不能長似鏡，當天多是曲如鈎。","定無列宿敢爭耀，好伴晴河相映流。","直使奔波急於箭，祗應白盡世間頭。"]', '["始看东上又西浮，圓缺何曾得自由。","照物不能长似镜，當天多是曲如鈎。","定無列宿敢爭耀，好伴晴河相映流。","直使奔波急於箭，祗應白尽世间头。"]', '诗', 'shi', '', NULL, '初月 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f73583e-1c2b-4fb8-b338-c9a31441e625', '題仙居觀', '題仙居观', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["往歲真人朝玉皇，四真三代住繁陽。","初開九鼎丹華熟，繼躡五雲天路長。","烟鎖翠嵐迷舊隱，池凝寒鏡貯秋光。","時從白鹿岩前往，應許潛通不死鄉。"]', '["往歲真人朝玉皇，四真三代住繁陽。","初开九鼎丹华熟，繼躡五云天路长。","烟鎖翠嵐迷旧隐，池凝寒镜貯秋光。","时從白鹿岩前往，應許潛通不死乡。"]', '诗', 'shi', '', NULL, '題仙居觀 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc847a19-8828-4118-9386-66528717906a', '題鴻都觀', '題鴻都观', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["亡吳霸越已功全，深隱雲林始學仙。","鸞鶴自飄三蜀駕，波濤猶憶五湖船。","雙溪夜月明寒玉，衆嶺秋空歛翠烟。","也有扁舟歸去興，故鄉東望思悠然。"]', '["亡吳霸越已功全，深隐云林始学仙。","鸾鹤自飄三蜀駕，波濤猶憶五湖船。","雙溪夜月明寒玉，衆嶺秋空歛翠烟。","也有扁舟归去兴，故乡东望思悠然。"]', '诗', 'shi', '', NULL, '題鴻都觀 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a73b4b62-4807-41ed-8d0a-aec08fb669fa', '題都慶觀', '題都慶观', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["三仙一一駕紅鸞，仙去雲閑遶古壇。","煉藥舊臺空處所，掛衣喬木兩摧殘。","清風嶺接猿聲近，白石溪涵水影寒。","二十四峯皆古隱，振纓長往亦何難。"]', '["三仙一一駕紅鸾，仙去云闲遶古壇。","煉藥旧台空处所，掛衣喬木兩摧殘。","清风嶺接猿声近，白石溪涵水影寒。","二十四峯皆古隐，振纓长往亦何难。"]', '诗', 'shi', '', NULL, '題都慶觀 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f84248-7fa2-4cd3-a6a7-af5e13d76a69', '贈將軍', '贈將軍', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["□□□□□□□，□□□□□□□。","八表順風驚雨露，四溟隨劒息波濤。","手扶北極鴻圖永，雲卷長天聖日高。","未會漢家青史上，韓彭何處有功勞。"]', '["□□□□□□□，□□□□□□□。","八表順风驚雨露，四溟隨劒息波濤。","手扶北極鴻圖永，云卷长天聖日高。","未會漢家青史上，韓彭何处有功勞。"]', '诗', 'shi', '', NULL, '贈將軍 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('666be20b-a036-40ef-93aa-4ca280c13b9b', '題鶴鳴山', '題鹤鳴山', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["五氣雲龍下泰清，三天真客已功成。","人間回首山川小，天上凌雲劒佩輕。","花擁石壇何寂寞，草平轍跡自分明。","鹿裘高士如相遇，不待岩前鶴有聲。"]', '["五氣云龙下泰清，三天真客已功成。","人间回首山川小，天上凌云劒佩轻。","花擁石壇何寂寞，草平轍跡自分明。","鹿裘高士如相遇，不待岩前鹤有声。"]', '诗', 'shi', '', NULL, '題鶴鳴山 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb838d44-9336-4290-94d5-65024eeb035d', '題空明洞', '題空明洞', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["窅然靈岫五雲深，落翮標名振古今。","芝朮迎風香馥馥，松檉蔽日影森森。","從師祗擬尋司馬，訪道終期謁奉林。","欲問空明奇勝處，地藏方石恰如金。"]', '["窅然靈岫五云深，落翮標名振古今。","芝朮迎风香馥馥，松檉蔽日影森森。","從師祗擬尋司马，訪道終期謁奉林。","欲问空明奇勝处，地藏方石恰如金。"]', '诗', 'shi', '', NULL, '題空明洞 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31f3a9d-c131-4e76-be4d-44b50ba7e24f', '題北平沼', '題北平沼', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["桐柏真人曾此居，焚香厓下誦靈書。","朝回時宴三山客，澗盡閑飛五色魚。","天柱一峰凝碧玉，神燈千點散紅蕖。","寶芝常在知誰得，好駕金蟾入太虛。"]', '["桐柏真人曾此居，焚香厓下誦靈书。","朝回时宴三山客，澗尽闲飞五色鱼。","天柱一峰凝碧玉，神灯千点散紅蕖。","寶芝常在知誰得，好駕金蟾入太虛。"]', '诗', 'shi', '', NULL, '題北平沼 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e924b201-2702-4a6f-8a27-d82fc870b9e9', '題平蓋沼', '題平蓋沼', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["勢壓長江空八陣，吳都仙客此脩真。","寒江向晚波濤急，深洞無風草木春。","江上玉人應可見，洞中仙鹿已來馴。","龍車鳳輦非難遇，只要塵心早出塵。"]', '["勢壓长江空八陣，吳都仙客此脩真。","寒江向晚波濤急，深洞無风草木春。","江上玉人應可见，洞中仙鹿已来馴。","龙车鳳輦非难遇，只要塵心早出塵。"]', '诗', 'shi', '', NULL, '題平蓋沼 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd48ff0b-d3cb-464b-9d3f-5451354d2563', '題本竹觀', '題本竹观', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["樓閣層層冠此山，雕軒朱檻一躋攀。","碑刊古篆龍蛇動，洞接諸天日月閑。","帝子影堂香漠漠，真人丹澗水潺潺。","掃空雙竹今何在，只恐投波去不還。"]', '["楼閣層層冠此山，雕軒朱檻一躋攀。","碑刊古篆龙蛇动，洞接諸天日月闲。","帝子影堂香漠漠，真人丹澗水潺潺。","掃空雙竹今何在，只恐投波去不還。"]', '诗', 'shi', '', NULL, '題本竹觀 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7c7be0-77e0-4d17-9cfb-1bb2322ae99d', '題福唐觀二首 一', '題福唐观二首 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["盤空躡翠到山巔，竹殿雲樓勢逼天。","古洞草深微有路，舊碑文滅不知年。","八州物象通簷外，萬里烟霞在目前。","自是人間輕舉地，何須蓬島訪真仙。"]', '["盤空躡翠到山巔，竹殿云楼勢逼天。","古洞草深微有路，旧碑文滅不知年。","八州物象通簷外，万里烟霞在目前。","自是人间轻舉地，何須蓬島訪真仙。"]', '诗', 'shi', '', NULL, '題福唐觀二首 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c3712c-ea71-49ad-a7fd-fdbf076f0042', '題福唐觀二首 二', '題福唐观二首 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["曾隨雲水此山遊，行盡層峯更上樓。","九月登臨須有意，七年岐路亦堪愁。","樹紅樹碧高低影，烟淡烟濃遠近秋。","暫熟爐香不須去，佇陪天仗入神州。"]', '["曾隨云水此山游，行尽層峯更上楼。","九月登臨須有意，七年岐路亦堪愁。","樹紅樹碧高低影，烟淡烟濃远近秋。","暫熟爐香不須去，佇陪天仗入神州。"]', '诗', 'shi', '', NULL, '題福唐觀二首 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15ff0e5-b4b8-4223-b75b-6887a23d3c68', '題莫公臺', '題莫公台', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["奇絕巍臺峙濁流，古來人號小瀛州。","路通霄漢雲迷晚，洞隱魚龍月浸秋。","舉手摘星河有浪，自天圖畫筆無鈎。","將軍悟却希夷訣，贏得清名萬古流。"]', '["奇絕巍台峙濁流，古来人號小瀛州。","路通霄漢云迷晚，洞隐鱼龙月浸秋。","舉手摘星河有浪，自天圖畫笔無鈎。","將軍悟却希夷訣，贏得清名万古流。"]', '诗', 'shi', '', NULL, '題莫公臺 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5b4903-45a3-41ff-bd56-bb2e02cea39b', '讀書臺', '读书台', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["山中猶有讀書臺，風掃晴嵐畫障開。","華月冰壺依舊在，青蓮居士幾時來。"]', '["山中猶有读书台，风掃晴嵐畫障开。","华月冰壺依旧在，青蓮居士幾时来。"]', '诗', 'shi', '', NULL, '讀書臺 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe65fd6-bc84-4231-9d64-24245ed11c0a', '贈人', '贈人', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["靜神凝思仰青冥，此夕長天降瑞星。","海上昨聞鵬羽翼，人間初見鶴儀形。"]', '["静神凝思仰青冥，此夕长天降瑞星。","海上昨闻鵬羽翼，人间初见鹤儀形。"]', '诗', 'shi', '', NULL, '贈人 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03bb035b-1565-448a-811a-c13530e0d5d2', '贈蜀州刺史', '贈蜀州刺史', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["再扶日月歸行殿，却領山河鎮夢刀。","從此雄名壓寰海，八溟爭敢起波濤。"]', '["再扶日月归行殿，却領山河鎮梦刀。","從此雄名壓寰海，八溟爭敢起波濤。"]', '诗', 'shi', '', NULL, '贈蜀州刺史 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deeac160-0839-483a-b67c-266f5c2b75a0', '題劒門', '題劒门', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["誰運乾坤陶冶功，鑄爲雙劒倚蒼穹。","題詩曾駐三天駕，礙日長含八海風。"]', '["誰運乾坤陶冶功，鑄爲雙劒倚蒼穹。","題诗曾駐三天駕，礙日长含八海风。"]', '诗', 'shi', '', NULL, '題劒門 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61094a4-4e8c-45f1-8862-c6fec73a266a', '題龍鵠山', '題龙鵠山', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["抽得閑身伴瘦筇，亂敲青碧喚蛟龍。","道人掃徑收松子，缺月初圓天柱峰。"]', '["抽得闲身伴瘦筇，亂敲青碧喚蛟龙。","道人掃徑收松子，缺月初圓天柱峰。"]', '诗', 'shi', '', NULL, '題龍鵠山 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e898fe0d-8cf2-46ae-a21d-59816355e1b7', '富貴曲', '富貴曲', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["美人梳洗時，滿頭間珠翠。","豈知兩片雲，戴却數鄉稅。"]', '["美人梳洗时，满头间珠翠。","豈知兩片云，戴却數乡稅。"]', '诗', 'shi', '', NULL, '富貴曲 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24a9b64-eb29-4a3f-8dc1-de86415f6ea0', '詠西施', '詠西施', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["素面已云妖，更著花鈿飾。","臉橫一寸波，浸破吳王國。"]', '["素面已云妖，更著花鈿飾。","臉橫一寸波，浸破吳王国。"]', '诗', 'shi', '', NULL, '詠西施 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6504b29e-b122-4ea8-8f7f-bd12b30f1bbb', '傷時', '傷时', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["帆力劈開滄海浪，馬蹄踏破亂山青。","浮名浮利過於酒，醉得人心死不醒。"]', '["帆力劈开滄海浪，马蹄踏破亂山青。","浮名浮利過於酒，醉得人心死不醒。"]', '诗', 'shi', '', NULL, '傷時 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92bc7ed1-45c0-49fc-947a-af5771ff4c0d', '題霍山秦尊師', '題霍山秦尊師', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["老鶴玄猿伴採芝，有時長嘆獨移時。","翠娥紅粉嬋娟劒，殺盡世人人不知。"]', '["老鹤玄猿伴採芝，有时长嘆独移时。","翠娥紅粉嬋娟劒，殺尽世人人不知。"]', '诗', 'shi', '', NULL, '題霍山秦尊師 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cef0b00-5ac6-4047-95d7-1950f37b4880', '偶題', '偶題', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["似鶴如雲一箇身，不憂家國不憂貧。","擬將枕上日高睡，賣與世間榮貴人。"]', '["似鹤如云一箇身，不憂家国不憂貧。","擬將枕上日高睡，賣與世间榮貴人。"]', '诗', 'shi', '', NULL, '偶題 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd0a42f-6b89-43a6-9200-69c70c1ae200', '思山詠', '思山詠', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["因賣丹砂下白雲，鹿裘惟惹九衢塵。","不如將耳入山去，萬是千非愁殺人。"]', '["因賣丹砂下白云，鹿裘惟惹九衢塵。","不如將耳入山去，万是千非愁殺人。"]', '诗', 'shi', '', NULL, '思山詠 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d687e169-b293-4a84-af21-f476fe3044b9', '景福中作', '景福中作', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["悶見戈鋋匝四溟，恨無奇策救生靈。","如何飲酒得長醉，直到太平時節醒。"]', '["悶见戈鋋匝四溟，恨無奇策救生靈。","如何饮酒得长醉，直到太平时節醒。"]', '诗', 'shi', '', NULL, '景福中作 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('268a3ed6-dad4-4c42-ae5f-30e283589193', '招友人遊春', '招友人游春', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["難把長繩繫日烏，芳時偷取醉功夫。","任堆金璧磨星斗，買得花枝不老無。"]', '["难把长繩繫日烏，芳时偷取醉功夫。","任堆金璧磨星斗，買得花枝不老無。"]', '诗', 'shi', '', NULL, '招友人遊春 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce5c277-0f7f-4459-9cad-d7a7f94d9376', '山居三首 一', '山居三首 一', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["悶見有人尋，移菴更入深。","落花流澗水，明月照松林。","醉勸頭陀酒，閑教孺子吟。","身同雲外鶴，斷得世塵侵。"]', '["悶见有人尋，移菴更入深。","落花流澗水，明月照松林。","醉勸头陀酒，闲教孺子吟。","身同云外鹤，斷得世塵侵。"]', '诗', 'shi', '', NULL, '山居三首 一 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f020388-0b7b-46f6-8aea-46a37083f541', '山居三首 二', '山居三首 二', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["冥心栖太室，散髮浸流泉。","採柏時逢麝，看雲忽見仙。","夏狂衝雨戲，春醉戴花眠。","絕頂登雲望，東都一點煙。"]', '["冥心栖太室，散髮浸流泉。","採柏时逢麝，看云忽见仙。","夏狂衝雨戲，春醉戴花眠。","絕頂登云望，东都一点煙。"]', '诗', 'shi', '', NULL, '山居三首 二 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2d07a5-ef54-41d9-9bec-447c5ff0131b', '山居三首 三', '山居三首 三', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["不求朝野知，臥見歲華移。","採藥歸侵夜，聽松飯過時。","荷竿尋水釣，背局上岩棊。","祭廟人來說，中原正亂離。"]', '["不求朝野知，臥见歲华移。","採藥归侵夜，听松飯過时。","荷竿尋水釣，背局上岩棊。","祭廟人来说，中原正亂離。"]', '诗', 'shi', '', NULL, '山居三首 三 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e52042-fe23-4354-b08c-5d047e636ec1', '紀道德', '紀道德', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["道，德。","清虛，玄默。","生帝先，爲聖則。","聽之不聞，摶之不得。","至德本無爲，人中多自惑。","在洗心而息慮，亦知白而守黑。","百姓日用而不知，上士勤行而必克。","既鼓鑄於乾坤品物，信充仞乎東西南北。","三皇高拱兮任以自然，五帝垂衣兮修之不忒。","以心體之者爲四海之主，以身彎之者爲萬夫之特。","有皓齒青娥者爲伐命之斧，蘊奇謀廣智者爲盜國之賊。","曾未若軒后順風兮清靜自化，曾未若臯陶邁種兮溫恭允塞。","故可以越圓清方濁兮不始不終，何止乎居九流五常兮理家理國。","豈不聞乎天地於道德也無以清寧，豈不聞乎道德於天地也有踰繩墨。","語不云乎仲尼有言朝聞道夕死可矣，所以垂萬古歷百王不敢離之於頃刻。"]', '["道，德。","清虛，玄默。","生帝先，爲聖則。","听之不闻，摶之不得。","至德本無爲，人中多自惑。","在洗心而息慮，亦知白而守黑。","百姓日用而不知，上士勤行而必克。","既鼓鑄於乾坤品物，信充仞乎东西南北。","三皇高拱兮任以自然，五帝垂衣兮修之不忒。","以心體之者爲四海之主，以身彎之者爲万夫之特。","有皓齒青娥者爲伐命之斧，蘊奇謀廣智者爲盜国之賊。","曾未若軒后順风兮清静自化，曾未若臯陶邁種兮溫恭允塞。","故可以越圓清方濁兮不始不終，何止乎居九流五常兮理家理国。","豈不闻乎天地於道德也無以清寧，豈不闻乎道德於天地也有踰繩墨。","語不云乎仲尼有言朝闻道夕死可矣，所以垂万古歷百王不敢離之於頃刻。"]', '诗', 'shi', '', NULL, '紀道德 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc5a6c0-8ffa-47c5-a56d-02a62848e266', '懷古今', '懷古今', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["古，今。","感事，傷心。","驚得喪，歎浮沈。","風駈寒署，川注光陰。","始衒朱顏麗，俄悲白髮侵。","嗟四豪之不返，痛七貴以難尋。","夸父興懷於落照，田文起怨於鳴琴。","鴈足淒涼兮傳恨緒，鳳臺寂寞兮有遺音。","朔漠幽囚兮天長地久，瀟湘隔別兮水闊煙深。","誰能絕聖韜賢餐芝餌朮，誰能含光遁世鍊石燒金。","君不見屈大夫紉蘭而發諫，君不見賈太傅忌鵩而愁吟。","君不見四皓避秦峨峨戀商嶺，君不見二疎辭漢飄飄歸故林。","胡爲乎冒進貪名踐危途與傾轍，胡爲乎怙權恃寵顧華飾與彫簪。","吾所以思抗跡忘機用虛無爲師範，吾所以思去奢滅慾保道德爲規箴。","不能勞神傚蘇子張生兮於時而縱辯，不能勞神傚楊朱墨翟兮揮涕以沾襟。"]', '["古，今。","感事，傷心。","驚得喪，歎浮沈。","风駈寒署，川注光陰。","始衒朱顏丽，俄悲白髮侵。","嗟四豪之不返，痛七貴以难尋。","夸父兴懷於落照，田文起怨於鳴琴。","鴈足淒涼兮傳恨緒，鳳台寂寞兮有遺音。","朔漠幽囚兮天长地久，瀟湘隔別兮水闊煙深。","誰能絕聖韜賢餐芝餌朮，誰能含光遁世鍊石燒金。","君不见屈大夫紉蘭而發諫，君不见賈太傅忌鵩而愁吟。","君不见四皓避秦峨峨戀商嶺，君不见二疎辞漢飄飄归故林。","胡爲乎冒進貪名踐危途與傾轍，胡爲乎怙權恃寵顧华飾與彫簪。","吾所以思抗跡忘機用虛無爲師範，吾所以思去奢滅慾保道德爲規箴。","不能勞神傚蘇子張生兮於时而縱辯，不能勞神傚楊朱墨翟兮揮涕以沾襟。"]', '诗', 'shi', '', NULL, '懷古今 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d17d1f-bfe1-4f57-a310-8b880f34402d', '句', '句', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["銅壺滴滴禁漏起，三十六宮爭捲簾。","斜陽古岸歸鴉晚，紅蓼低沙宿雁愁。","霜彫曲徑寒蕪白，雁下遙村落照黃。","恩威欲寄黃丞相，仁信先聞郭細侯。","兵氣此時來世上，文星今日到人間。","降因天下思姚宋，出爲儒門繼孔顏。","丹竈河車休矻矻，蚌胎龜息且緜緜。","馭景必能趨日域，騎箕終擬躡星躔。","返樸還淳皆至理，遺形忘性盡真銓。"]', '["銅壺滴滴禁漏起，三十六宮爭捲簾。","斜陽古岸归鴉晚，紅蓼低沙宿雁愁。","霜彫曲徑寒蕪白，雁下遙村落照黄。","恩威欲寄黄丞相，仁信先闻郭細侯。","兵氣此时来世上，文星今日到人间。","降因天下思姚宋，出爲儒门繼孔顏。","丹竈河车休矻矻，蚌胎龟息且緜緜。","馭景必能趨日域，騎箕終擬躡星躔。","返樸還淳皆至理，遺形忘性尽真銓。"]', '诗', 'shi', '', NULL, '句 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df6ef7b-d31d-4feb-9f65-938edb8106f9', '山居 一', '山居 一', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["悶見有人尋，移庵更入深。","落花流澗水，明月照松林。","醉勸頭陀酒，閑教孺子吟。","身同雲外鶴，斷得世塵侵。"]', '["悶见有人尋，移庵更入深。","落花流澗水，明月照松林。","醉勸头陀酒，闲教孺子吟。","身同云外鹤，斷得世塵侵。"]', '诗', 'shi', '', NULL, '山居 一 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba7999a-efb2-422e-bd1a-ec7faa57f6e5', '山居 二', '山居 二', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["冥心棲太室，散髮浸流泉。","採柏時逢麝，看雲忽見山。","夏狂衝雨戲，春醉戴花眠。","絕頂登雲望，東都一點煙。"]', '["冥心棲太室，散髮浸流泉。","採柏时逢麝，看云忽见山。","夏狂衝雨戲，春醉戴花眠。","絕頂登云望，东都一点煙。"]', '诗', 'shi', '', NULL, '山居 二 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3deb5cd3-49f3-40d3-a0bd-9d554fdb1369', '山居 三', '山居 三', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["不求朝野知，臥見歲華移。","採藥歸侵夜，聽松飯過時。","荷竿尋水釣，背局上巖碁。","祭廟人來說，中原正亂離。"]', '["不求朝野知，臥见歲华移。","採藥归侵夜，听松飯過时。","荷竿尋水釣，背局上巖碁。","祭廟人来说，中原正亂離。"]', '诗', 'shi', '', NULL, '山居 三 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217daaab-0171-486d-acfe-c358b2182742', '茶詩', '茶诗', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["嫩芽香且靈，吾謂草中英。","夜臼和煙搗，寒鑪對雪烹。","惟憂碧粉散，常見綠花生。","最是堪珍重，能令睡思清。"]', '["嫩芽香且靈，吾謂草中英。","夜臼和煙捣，寒鑪对雪烹。","惟憂碧粉散，常见綠花生。","最是堪珍重，能令睡思清。"]', '诗', 'shi', '', NULL, '茶詩 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1567285f-556a-4c74-828d-3434c66439f1', '哭張道古', '哭張道古', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["曾陳章疏忤昭皇，撲落西南事可傷。","豈使諫臣終屈辱，直疑天道惡忠良。","生前賣卜居三蜀，死後馳名遍大唐。","誰是後來脩史者，言君力死正頹綱。"]', '["曾陳章疏忤昭皇，撲落西南事可傷。","豈使諫臣終屈辱，直疑天道惡忠良。","生前賣卜居三蜀，死後驰名遍大唐。","誰是後来脩史者，言君力死正頹綱。"]', '诗', 'shi', '', NULL, '哭張道古 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0748716d-b669-4347-a5f0-a1579355a486', '富貴曲', '富貴曲', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["美人梳洗時，滿頭間珠翠。","豈知兩片雲，戴却數鄉稅。"]', '["美人梳洗时，满头间珠翠。","豈知兩片云，戴却數乡稅。"]', '诗', 'shi', '', NULL, '富貴曲 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b543959-9716-4cb5-aaf8-12cc6946fdad', '傷農', '傷農', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["一粒紅稻飯，幾滴牛頷血。","珊瑚枝下人，銜杯吐不歇。"]', '["一粒紅稻飯，幾滴牛頷血。","珊瑚枝下人，銜杯吐不歇。"]', '诗', 'shi', '', NULL, '傷農 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f2ce83-f6c6-4187-ba8e-c4ec2672287f', '詠西施', '詠西施', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["素面已云妖，更著花鈿餙。","臉橫一寸波，浸破吳王國。"]', '["素面已云妖，更著花鈿餙。","臉橫一寸波，浸破吳王国。"]', '诗', 'shi', '', NULL, '詠西施 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ba7bcd-92f8-4ca9-befb-609f0e2e4526', '思山詠', '思山詠', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["因賣丹砂下白雲，鹿裘惟惹九衢塵。","不如將耳入山去，萬是千非愁殺人。"]', '["因賣丹砂下白云，鹿裘惟惹九衢塵。","不如將耳入山去，万是千非愁殺人。"]', '诗', 'shi', '', NULL, '思山詠 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71e31d3b-1984-450b-b130-5e07881647dd', '招友人遊春', '招友人游春', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["難把長繩繫日烏，芳時偷取醉工夫。","任堆金璧磨星斗，買得花枝不老無。"]', '["难把长繩繫日烏，芳时偷取醉工夫。","任堆金璧磨星斗，買得花枝不老無。"]', '诗', 'shi', '', NULL, '招友人遊春 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d94f54-64a8-4a1f-be70-b14b2ee6e0f2', '宿洞庭', '宿洞庭', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["月到君山酒半醒，朗吟疑有水仙聽。","無人識我真閑事，贏得高秋看洞庭。"]', '["月到君山酒半醒，朗吟疑有水仙听。","無人識我真闲事，贏得高秋看洞庭。"]', '诗', 'shi', '', NULL, '宿洞庭 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7891f1-abbb-4cab-ba6d-423449815c10', '題病僧寮', '題病僧寮', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["佛前香印廢晨燒，金錫當門照寂寥。","童子不知師病困，報風吹折好芭蕉。"]', '["佛前香印廢晨燒，金錫當门照寂寥。","童子不知師病困，報风吹折好芭蕉。"]', '诗', 'shi', '', NULL, '題病僧寮 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef10faf-f259-472f-81e7-9fc6613974e7', '題霍山秦尊師', '題霍山秦尊師', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["老鶴玄猨伴採芝，有時長歎獨移時。","翠娥紅粉渾如劒，殺盡世人人不知。"]', '["老鹤玄猨伴採芝，有时长歎独移时。","翠娥紅粉渾如劒，殺尽世人人不知。"]', '诗', 'shi', '', NULL, '題霍山秦尊師 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a016f202-51e3-4dce-9ad2-ed5bcd9799d3', '偶題 一', '偶題 一', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["似鶴如雲一箇身，不憂家國不憂貧。","擬將枕上日高睡，賣與世間榮貴人。"]', '["似鹤如云一箇身，不憂家国不憂貧。","擬將枕上日高睡，賣與世间榮貴人。"]', '诗', 'shi', '', NULL, '偶題 一 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435c06d8-5129-483c-b02a-2731b0eeedca', '偶題 二', '偶題 二', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["帆力劈開滄海浪，馬蹄踏破亂山青。","浮名浮利濃於酒，醉得人心死不醒。"]', '["帆力劈开滄海浪，马蹄踏破亂山青。","浮名浮利濃於酒，醉得人心死不醒。"]', '诗', 'shi', '', NULL, '偶題 二 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb2345e-65f2-4bce-b84a-9467dab0a9f0', '景福中作', '景福中作', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["悶見戈鋋匝四溟，恨無奇策救生靈。","如何飲酒得長醉，直到太平時節醒。"]', '["悶见戈鋋匝四溟，恨無奇策救生靈。","如何饮酒得长醉，直到太平时節醒。"]', '诗', 'shi', '', NULL, '景福中作 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7bba4d-eb5a-493f-accf-012b8e375600', '題中條靜觀', '題中條静观', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["松頂留衣上玉霄，永傳異迹在中條。","不知揖徧諸仙否，欲請還丹問昨宵。"]', '["松頂留衣上玉霄，永傳異迹在中條。","不知揖徧諸仙否，欲請還丹问昨宵。"]', '诗', 'shi', '', NULL, '題中條靜觀 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19252fe2-b344-49ee-8b88-5ab241d82a20', '送臥雲道士', '送臥云道士', 'e352233f-1078-450e-a270-ede078a7f5b7', '唐', '["臥雲道士來相辭，相辭倏忽何所之。","紫閣春深煙靄靄，東風花柳折枝枝。","藥成酒熟有時節，寒食恐失松間期。","冥鴻一見傷弓翼，高飛展轉心無疑。","滿酌數杯酒，狂吟幾首詩。","留不住，去不悲，醯雞蜉蝣安得知。"]', '["臥云道士来相辞，相辞倏忽何所之。","紫閣春深煙靄靄，东风花柳折枝枝。","藥成酒熟有时節，寒食恐失松间期。","冥鴻一见傷弓翼，高飞展轉心無疑。","满酌數杯酒，狂吟幾首诗。","留不住，去不悲，醯雞蜉蝣安得知。"]', '诗', 'shi', '', NULL, '送臥雲道士 虞有賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ec433e-8bd5-45a7-a676-c0fa91bbe5a7', '示守庚申衆', '示守庚申衆', 'e72586d0-5c02-40f9-8dc9-df6dbe5c3ff4', '唐', '["不守庚申亦不疑，此心長與道相依。","玉皇已自知行止，仁汝三彭說是非。"]', '["不守庚申亦不疑，此心长與道相依。","玉皇已自知行止，仁汝三彭说是非。"]', '诗', 'shi', '', NULL, '示守庚申衆 程紫霄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64146c3-c6b7-41a9-a6b3-4160bc007d43', '蘭谿靈瑞觀', '蘭谿靈瑞观', 'f978ffdc-91d3-403b-b5fe-0b58675135c1', '唐', '["澄心坐清境，虛白生林端。","夜靜笑聲出，月明松影寒。","絳霞封藥竈，碧竇濺齋壇。","海樹幾回老，先生棊未殘。"]', '["澄心坐清境，虛白生林端。","夜静笑声出，月明松影寒。","絳霞封藥竈，碧竇濺斋壇。","海樹幾回老，先生棊未殘。"]', '诗', 'shi', '', NULL, '蘭谿靈瑞觀 舒道紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b604ea3b-6364-4841-b985-d8b40c491d15', '題赤松宮', '題赤松宮', 'f978ffdc-91d3-403b-b5fe-0b58675135c1', '唐', '["松老赤松原，松間廟宛然。","人皆有兄弟，誰得共神仙。","雙鶴沖天去，羣羊化石眠。","至今丹井水，香滿北山邊。"]', '["松老赤松原，松间廟宛然。","人皆有兄弟，誰得共神仙。","雙鹤沖天去，羣羊化石眠。","至今丹井水，香满北山邊。"]', '诗', 'shi', '', NULL, '題赤松宮 舒道紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0cf424-64a3-4779-8e7b-c21136034ab1', '參同契明鏡圖訣詩二首 一', '參同契明镜圖訣诗二首 一', 'af327edd-ba06-42e8-a938-0be0d0794650', '唐', '["造化潛施跡莫窮，簇成真訣指蒙童。","三篇祕列八環內，萬象門開一鏡中。","離女駕龍爲木壻，坎男乘虎作金翁。","同人好道宜精究，究得長生路便通。"]', '["造化潛施跡莫窮，簇成真訣指蒙童。","三篇祕列八环內，万象门开一镜中。","離女駕龙爲木壻，坎男乘虎作金翁。","同人好道宜精究，究得长生路便通。"]', '诗', 'shi', '', NULL, '參同契明鏡圖訣詩二首 一 彭曉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc3bab63-46c3-4010-973a-251f97b433a7', '參同契明鏡圖訣詩二首 二', '參同契明镜圖訣诗二首 二', 'af327edd-ba06-42e8-a938-0be0d0794650', '唐', '["至道希夷妙且深，燒丹先認大還心。","日爻陰耦生真汞，月卦陽奇產正金。","女妊朱砂男孕雪，北藏熒惑丙含壬。","兩端指的鉛金祖，莫向諸般取次尋。"]', '["至道希夷妙且深，燒丹先認大還心。","日爻陰耦生真汞，月卦陽奇產正金。","女妊朱砂男孕雪，北藏熒惑丙含壬。","兩端指的鉛金祖，莫向諸般取次尋。"]', '诗', 'shi', '', NULL, '參同契明鏡圖訣詩二首 二 彭曉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3cc1386-bfb9-4c25-abd7-12ead8f97b62', '題柳公權書度人經後', '題柳公權书度人經後', '860c32a0-5d4c-4dbc-a7e3-aeeb1c93b193', '唐', '["臥雲道士來相辭，相辭倏忽何所之。","紫閣當春凝煙靄，東風吹岸花枝枝。","藥成酒熟有時節，寒食恐失松間期。","冥鴻復見傷弓翼，高飛展轉心無疑。","滿瀉數杯酒，狂吟幾首詩。","留不住，去不悲，醯雞蜉蝣可得知。"]', '["臥云道士来相辞，相辞倏忽何所之。","紫閣當春凝煙靄，东风吹岸花枝枝。","藥成酒熟有时節，寒食恐失松间期。","冥鴻复见傷弓翼，高飞展轉心無疑。","满瀉數杯酒，狂吟幾首诗。","留不住，去不悲，醯雞蜉蝣可得知。"]', '诗', 'shi', '', NULL, '題柳公權書度人經後 魚又玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27737fca-8666-46d6-b5bf-fd6599d8a976', '呈鍾離雲房', '呈鍾離云房', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["生在儒家遇太平，懸纓重滯布衣輕。","誰能世上爭名利，臣事玉皇歸上清。"]', '["生在儒家遇太平，懸纓重滯布衣轻。","誰能世上爭名利，臣事玉皇归上清。"]', '诗', 'shi', '', NULL, '呈鍾離雲房 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6090aa67-1d8b-45c0-8c58-f28e6be621e0', '獻鄭思遠施真人二仙', '獻鄭思远施真人二仙', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["萬劫千生到此生，此生身始覺飛輕。","拋家別國雲山外，煉魄全魂日月精。","比見至人論九鼎，欲窮大藥訪三清。","如今獲遇真仙面，紫府仙扉得姓名。"]', '["万劫千生到此生，此生身始覺飞轻。","拋家別国云山外，煉魄全魂日月精。","比见至人論九鼎，欲窮大藥訪三清。","如今獲遇真仙面，紫府仙扉得姓名。"]', '诗', 'shi', '', NULL, '獻鄭思遠施真人二仙 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d12c024-1618-4647-80b3-d5364d24f83e', '得火龍真人劒法', '得火龙真人劒法', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["昔年曾遇火龍君，一劒相傳伴此身。","天地山河從結沫，星辰日月任停輪。","須知本性綿多劫，空向人間歷萬春。","昨夜鍾離傳一語，六天宮殿欲成塵。"]', '["昔年曾遇火龙君，一劒相傳伴此身。","天地山河從結沫，星辰日月任停輪。","須知本性綿多劫，空向人间歷万春。","昨夜鍾離傳一語，六天宮殿欲成塵。"]', '诗', 'shi', '', NULL, '得火龍真人劒法 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f22eba-b039-4724-b569-fb13b9240bd9', '七言 一', '七言 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["周行獨力出群倫，默默昏昏亙古存。","無象無形潛造化，有門有戶在乾坤。","色非色際誰窮處，空不空中自得根。","此道非從它外得，千言萬語謾評論。"]', '["周行独力出群倫，默默昏昏亙古存。","無象無形潛造化，有门有戶在乾坤。","色非色際誰窮处，空不空中自得根。","此道非從它外得，千言万語謾評論。"]', '诗', 'shi', '', NULL, '七言 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4eabf55-932b-4cc4-850a-fddcef11efc7', '七言 二', '七言 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["通靈一顆正金丹，不在天涯地角安。","討論窮經深莫究，登山臨水杳無看。","光明暗寄希夷頂，赫赤高居混沌端。","舉世若能知所寓，超凡入聖弗爲難。"]', '["通靈一顆正金丹，不在天涯地角安。","討論窮經深莫究，登山臨水杳無看。","光明暗寄希夷頂，赫赤高居混沌端。","舉世若能知所寓，超凡入聖弗爲难。"]', '诗', 'shi', '', NULL, '七言 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4043b2-5fac-4b3d-9a08-a79ca05f7553', '七言 三', '七言 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["落魄紅塵四十春，無爲無事信天真。","生涯只在乾坤鼎，活計惟憑日月輪。","八卦氣中潛至寶，五行光裏隱元神。","桑田改變依然在，永作人間出世人。"]', '["落魄紅塵四十春，無爲無事信天真。","生涯只在乾坤鼎，活計惟憑日月輪。","八卦氣中潛至寶，五行光裏隐元神。","桑田改变依然在，永作人间出世人。"]', '诗', 'shi', '', NULL, '七言 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe64a05-e514-4b1e-bdd5-79543a32e607', '七言 四', '七言 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["獨處乾坤萬象中，從頭歷歷運元功。","縱橫北斗心機大，顛倒南辰膽氣雄。","鬼哭神號金鼎結，雞飛犬化玉爐空。","如何俗士尋常覓，不達希夷不可窮。"]', '["独处乾坤万象中，從头歷歷運元功。","縱橫北斗心機大，顛倒南辰膽氣雄。","鬼哭神號金鼎結，雞飞犬化玉爐空。","如何俗士尋常覓，不達希夷不可窮。"]', '诗', 'shi', '', NULL, '七言 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dca253a-f490-4f11-b90c-d034883b7ff1', '七言 五', '七言 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰信華池路最深，非遐非邇奧難尋。","九年採煉如紅玉，一日圓成似紫金。","得了永袪寒署逼，服之應免死生侵。","勸君門外修身者，端念思惟此道心。"]', '["誰信华池路最深，非遐非邇奧难尋。","九年採煉如紅玉，一日圓成似紫金。","得了永袪寒署逼，服之應免死生侵。","勸君门外修身者，端念思惟此道心。"]', '诗', 'shi', '', NULL, '七言 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4d758b-f73d-4cc6-9dba-448fbd3cfcf9', '七言 六', '七言 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["水府尋鉛合火鉛，黑紅紅黑又玄玄。","氣中生氣肌膚換，精裏含精性命專。","藥返便爲真道士，丹還本是聖胎仙。","出神入定虛華語，徒費功夫萬萬年。"]', '["水府尋鉛合火鉛，黑紅紅黑又玄玄。","氣中生氣肌膚換，精裏含精性命專。","藥返便爲真道士，丹還本是聖胎仙。","出神入定虛华語，徒費功夫万万年。"]', '诗', 'shi', '', NULL, '七言 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b38ea6a3-972a-42d7-9779-ec796f801d7b', '七言 七', '七言 七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九鼎烹煎九轉砂，區分時節更無差。","精神氣血歸三要，南北東西共一家。","天地變通飛白雪，陰陽和合產金花。","終期鳳詔空中降，跨虎騎龍謁紫霞。"]', '["九鼎烹煎九轉砂，區分时節更無差。","精神氣血归三要，南北东西共一家。","天地变通飞白雪，陰陽和合產金花。","終期鳳詔空中降，跨虎騎龙謁紫霞。"]', '诗', 'shi', '', NULL, '七言 七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa8fd792-7d79-4d64-8c14-66487034e27d', '七言 八', '七言 八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["憑君子後午前看，一脈天津在脊端。","金闕內藏玄谷子，玉池中坐太和官。","只將至妙三周火，鍊出通靈九轉丹。","直指幾多求道者，行藏莫離虎龍灘。"]', '["憑君子後午前看，一脈天津在脊端。","金闕內藏玄谷子，玉池中坐太和官。","只將至妙三周火，鍊出通靈九轉丹。","直指幾多求道者，行藏莫離虎龙灘。"]', '诗', 'shi', '', NULL, '七言 八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1045aa88-ba54-47af-b0ad-c59965a06f63', '七言 九', '七言 九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["返本還元道氣平，虛非形質轉分明。","水中白雪微微結，火裏金蓮漸漸生。","聖汞論時非有體，真鉛窮看亦無名。","吾今爲報修行者，莫向燒金問至精。"]', '["返本還元道氣平，虛非形質轉分明。","水中白雪微微結，火裏金蓮漸漸生。","聖汞論时非有體，真鉛窮看亦無名。","吾今爲報修行者，莫向燒金问至精。"]', '诗', 'shi', '', NULL, '七言 九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df11e1f-3c83-4028-8320-ec52714e06df', '七言 十', '七言 十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["安排鼎竈煉玄根，進退須明卯酉門。","繞電奔雲飛日月，驅龍走虎出乾坤。","一丸因與紅顏駐，九轉能燒白髮痕。","此道幽微知者少，茫茫塵世與誰論。"]', '["安排鼎竈煉玄根，進退須明卯酉门。","繞電奔云飞日月，驱龙走虎出乾坤。","一丸因與紅顏駐，九轉能燒白髮痕。","此道幽微知者少，茫茫塵世與誰論。"]', '诗', 'shi', '', NULL, '七言 十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7788d525-c5b0-4845-bfab-c1adae510838', '七言 十一', '七言 十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["醍醐一盞詩一篇，暮醉朝吟不記年。","乾馬屢來遊九地，坤牛時駕出三天。","白龜窟裏夫妻會，青鳳巢中子母圓。","提挈靈童山上望，重重疊疊是金錢。"]', '["醍醐一盞诗一篇，暮醉朝吟不記年。","乾马屢来游九地，坤牛时駕出三天。","白龟窟裏夫妻會，青鳳巢中子母圓。","提挈靈童山上望，重重叠叠是金錢。"]', '诗', 'shi', '', NULL, '七言 十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d717ab9-0e1f-43d2-a924-91dc6c2b5246', '七言 十二', '七言 十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["認得東西木與金，自然爐鼎虎龍吟。","但隨天地明消息，方識陰陽有信音。","左掌南辰攀鶴羽，右擎北極剖龜心。","神仙親口留斯旨，何用區區向外尋。"]', '["認得东西木與金，自然爐鼎虎龙吟。","但隨天地明消息，方識陰陽有信音。","左掌南辰攀鹤羽，右擎北極剖龟心。","神仙親口留斯旨，何用區區向外尋。"]', '诗', 'shi', '', NULL, '七言 十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5c8185-192f-43eb-bc81-74e9021cbf11', '七言 十三', '七言 十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["一本天機深更深，徒言萬劫與千金。","三冬大熱玄中火，六月霜寒表外陰。","金爲浮來方見性，木因沈後始知心。","五行顛倒堪消息，返本還元在己尋。"]', '["一本天機深更深，徒言万劫與千金。","三冬大熱玄中火，六月霜寒表外陰。","金爲浮来方见性，木因沈後始知心。","五行顛倒堪消息，返本還元在己尋。"]', '诗', 'shi', '', NULL, '七言 十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('985dcca2-790b-4390-b6d6-240ab7c52c75', '七言 十四', '七言 十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["虎將龍軍氣宇雄，佩符持甲去悤悤。","鋪排劒戟奔如電，羅列旌旗疾似風。","活捉三尸焚鬼窟，生禽六賊破魔宮。","河清海晏乾坤淨，世世安居道德中。"]', '["虎將龙軍氣宇雄，佩符持甲去悤悤。","鋪排劒戟奔如電，羅列旌旗疾似风。","活捉三尸焚鬼窟，生禽六賊破魔宮。","河清海晏乾坤淨，世世安居道德中。"]', '诗', 'shi', '', NULL, '七言 十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1ec6fff-a3d8-4478-aae6-47f64fdfb083', '七言 十五', '七言 十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["我家勤種我家田，內有靈苗活萬年。","花似黃金苞不大，子如白玉顆皆圓。","栽培全賴中宮土，灌溉須憑上谷泉。","直候九年功滿日，和根拔入大羅天。"]', '["我家勤種我家田，內有靈苗活万年。","花似黄金苞不大，子如白玉顆皆圓。","栽培全賴中宮土，灌溉須憑上谷泉。","直候九年功满日，和根拔入大羅天。"]', '诗', 'shi', '', NULL, '七言 十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8109d68c-f4fa-4690-95b5-9b95aacbc23a', '七言 十六', '七言 十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["尋常學道說黃芽，萬水千山覓轉差。","有畛有園難下種，無根無脚自開花。","九三鼎內烹如酪，六一爐中結似霞。","不日成丹應換骨，飛升遙指玉皇家。"]', '["尋常学道说黄芽，万水千山覓轉差。","有畛有园难下種，無根無脚自开花。","九三鼎內烹如酪，六一爐中結似霞。","不日成丹應換骨，飞升遙指玉皇家。"]', '诗', 'shi', '', NULL, '七言 十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe6263e-2684-492b-97a5-1ab69c67c55f', '七言 十七', '七言 十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["四六關頭路坦平，行人到此不須驚。","從教犢駕轟轟轉，儘使羊車軋軋鳴。","渡海經河稀阻滯，上天入地絕欹傾。","功成直入長生殿，袖出神珠徹夜明。"]', '["四六关头路坦平，行人到此不須驚。","從教犢駕轟轟轉，儘使羊车軋軋鳴。","渡海經河稀阻滯，上天入地絕欹傾。","功成直入长生殿，袖出神珠徹夜明。"]', '诗', 'shi', '', NULL, '七言 十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6215009-3911-4727-9ac8-f00d4856d675', '七言 十八', '七言 十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九六相交道氣和，河車晝夜迸金波。","呼時一一關頭轉，吸處重重脈上摩。","電激離門光海嶽，雷轟震戶動婆娑。","思量此道真長遠，學者多迷溺愛河。"]', '["九六相交道氣和，河车晝夜迸金波。","呼时一一关头轉，吸处重重脈上摩。","電激離门光海嶽，雷轟震戶动婆娑。","思量此道真长远，学者多迷溺愛河。"]', '诗', 'shi', '', NULL, '七言 十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b8935a-322a-43c5-b466-493313a3f19d', '七言 十九', '七言 十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["金丹不是小金丹，陰鼎陽爐裏面安。","盡道東山尋汞易，豈知西海覓鉛難。","玄珠窟裏行非遠，赤水灘頭去便端。","認得靈竿真的路，何勞禮月步星壇。"]', '["金丹不是小金丹，陰鼎陽爐裏面安。","尽道东山尋汞易，豈知西海覓鉛难。","玄珠窟裏行非远，赤水灘头去便端。","認得靈竿真的路，何勞禮月步星壇。"]', '诗', 'shi', '', NULL, '七言 十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7878efc4-ced8-451d-8e87-00e3ab7a4688', '七言 二十', '七言 二十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["古今機要甚分明，自是衆生力量輕。","盡向有中尋有質，誰能無裏見無形。","真鉛聖汞徒虛費，玉室金關不解扃。","本色丹瓢推倒後，却吞丸藥待延齡。"]', '["古今機要甚分明，自是衆生力量轻。","尽向有中尋有質，誰能無裏见無形。","真鉛聖汞徒虛費，玉室金关不解扃。","本色丹瓢推倒後，却吞丸藥待延齡。"]', '诗', 'shi', '', NULL, '七言 二十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8c126f-098d-4d67-92cd-79d4d3a47e30', '七言 二十一', '七言 二十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["浮名浮利兩何堪，迴首歸山味轉甘。","舉世算無心可契，誰人更與道相參。","寸猶未到甘談尺，一尚難明強說三。","經卷葫蘆幷拄杖，依前擔入舊江南。"]', '["浮名浮利兩何堪，迴首归山味轉甘。","舉世算無心可契，誰人更與道相參。","寸猶未到甘談尺，一尚难明強说三。","經卷葫蘆幷拄杖，依前擔入旧江南。"]', '诗', 'shi', '', NULL, '七言 二十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2887f0ee-033e-45a1-8f89-0bdb03e94873', '七言 二十二', '七言 二十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["本來無作亦無行，行着之時是妄情。","老氏語中猶未決，瞿曇言下更難明。","靈竿有節通天去，至藥無根得地生。","今日與君無恡惜，功成只此是蓬瀛。"]', '["本来無作亦無行，行着之时是妄情。","老氏語中猶未決，瞿曇言下更难明。","靈竿有節通天去，至藥無根得地生。","今日與君無恡惜，功成只此是蓬瀛。"]', '诗', 'shi', '', NULL, '七言 二十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44dffb0-d36b-4982-89ec-1795f126cbe2', '七言 二十三', '七言 二十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["解將火種種刀圭，火種刀圭世豈知。","山上長男騎白馬，水邊少女牧烏龜。","無中出有還丹象，陰裏生陽大道基。","顛倒五行憑匠手，不逢匠手莫施爲。"]', '["解將火種種刀圭，火種刀圭世豈知。","山上长男騎白马，水邊少女牧烏龟。","無中出有還丹象，陰裏生陽大道基。","顛倒五行憑匠手，不逢匠手莫施爲。"]', '诗', 'shi', '', NULL, '七言 二十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e6155f-679f-4b60-bf32-cb693d1b209c', '七言 二十四', '七言 二十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三千餘法論修行，第一燒丹路最親。","須是坎男端的物，取他離女自然珍。","烹成不死砂中汞，結出長生水裏銀。","九轉九還功若就，定將衰老返長春。"]', '["三千餘法論修行，第一燒丹路最親。","須是坎男端的物，取他離女自然珍。","烹成不死砂中汞，結出长生水裏銀。","九轉九還功若就，定將衰老返长春。"]', '诗', 'shi', '', NULL, '七言 二十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6d10dbd-7e3b-4b8b-b837-8acb894621fa', '七言 二十五', '七言 二十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["欲種長生不死根，再營陰魄及陽魂。","先教玄母歸離戶，後遣空王鎮坎門。","虎到甲邊風浩浩，龍居庚內水溫溫。","迷途爭與輕輕泄，此理須憑達者論。"]', '["欲種长生不死根，再營陰魄及陽魂。","先教玄母归離戶，後遣空王鎮坎门。","虎到甲邊风浩浩，龙居庚內水溫溫。","迷途爭與轻轻泄，此理須憑達者論。"]', '诗', 'shi', '', NULL, '七言 二十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94847d21-1614-452b-a015-df7331d753ef', '七言 二十六', '七言 二十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["閉目存神玉戶觀，時來火候遞相傳。","雲飛海面龍吞汞，風擊巖巔虎伏鉛。","一旦煉成身內寶，等閑探得道中玄。","刀圭餌了丹書降，跳出塵籠上九天。"]', '["閉目存神玉戶观，时来火候遞相傳。","云飞海面龙吞汞，风擊巖巔虎伏鉛。","一旦煉成身內寶，等闲探得道中玄。","刀圭餌了丹书降，跳出塵籠上九天。"]', '诗', 'shi', '', NULL, '七言 二十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7993aa-1bd3-4c81-aeea-e9e5da6c8136', '七言 二十七', '七言 二十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["千日功夫不暫閑，河車搬載上崑山。","虎抽白汞安爐裏，龍發紅鉛向鼎間。","仙府記名丹已熟，陰司除籍命應還。","彩雲捧足歸何處，直入三清謝聖顏。"]', '["千日功夫不暫闲，河车搬載上崑山。","虎抽白汞安爐裏，龙發紅鉛向鼎间。","仙府記名丹已熟，陰司除籍命應還。","彩云捧足归何处，直入三清謝聖顏。"]', '诗', 'shi', '', NULL, '七言 二十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7eb727-3246-44e1-bad3-55727da3e95e', '七言 二十八', '七言 二十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["解匹真陰與正陽，三年功滿結成霜。","神龜出入庚辛位，丹鳳翺翔甲乙方。","九鼎先輝雙瑞氣，三元中換五毫光。","塵中若有同機者，共住煙霄不死鄉。"]', '["解匹真陰與正陽，三年功满結成霜。","神龟出入庚辛位，丹鳳翺翔甲乙方。","九鼎先輝雙瑞氣，三元中換五毫光。","塵中若有同機者，共住煙霄不死乡。"]', '诗', 'shi', '', NULL, '七言 二十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c0b4e2-28fc-495d-9c8a-d9c0f58b60a9', '七言 二十九', '七言 二十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["修生一路就中難，迷者徒將萬卷看。","水火均平方是藥，陰陽差互不成丹。","守雌勿失雄方住，在黑無虧白自乾。","認得此般真妙訣，何憂風雨妒衰殘。"]', '["修生一路就中难，迷者徒將万卷看。","水火均平方是藥，陰陽差互不成丹。","守雌勿失雄方住，在黑無虧白自乾。","認得此般真妙訣，何憂风雨妒衰殘。"]', '诗', 'shi', '', NULL, '七言 二十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b6d6d2-1b43-4d2d-ab8e-3ffd17f79f97', '七言 三十', '七言 三十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["纔吞一粒便安然，十二重樓九曲連。","庚虎循環餐絳雪，甲龍夭喬迸靈泉。","三三上應三千日，九九中延九萬年。","須得有緣方可授，未曾輕泄與人傳。"]', '["纔吞一粒便安然，十二重楼九曲連。","庚虎循环餐絳雪，甲龙夭喬迸靈泉。","三三上應三千日，九九中延九万年。","須得有緣方可授，未曾轻泄與人傳。"]', '诗', 'shi', '', NULL, '七言 三十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a57326-a31b-470b-a2b9-f08e776897c6', '七言 三十一', '七言 三十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰知神水玉華池，中有長生性命基。","運用須憑龍與虎，抽添全藉坎兼離。","晨昏點盡黃金粉，頃刻修成玉石脂。","齋戒餌之千日後，等閑輕舉上雲梯。"]', '["誰知神水玉华池，中有长生性命基。","運用須憑龙與虎，抽添全藉坎兼離。","晨昏点尽黄金粉，頃刻修成玉石脂。","斋戒餌之千日後，等闲轻舉上云梯。"]', '诗', 'shi', '', NULL, '七言 三十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849ef78f-6548-4a94-bae7-cde2121e9179', '七言 三十二', '七言 三十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九天雲淨鶴飛輕，銜簡翩翩別太清。","身外紅塵隨意換，爐中白石立時成。","九苞鳳向空中舞，五色雲從足下生。","回首便歸天上去，願將甘雨救焦氓。"]', '["九天云淨鹤飞轻，銜簡翩翩別太清。","身外紅塵隨意換，爐中白石立时成。","九苞鳳向空中舞，五色云從足下生。","回首便归天上去，願將甘雨救焦氓。"]', '诗', 'shi', '', NULL, '七言 三十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bf5f14-1a22-45e4-b794-c097c33a225c', '七言 三十三', '七言 三十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["嬰兒迤邐降瑤階，手握玄珠直下來。","半夜紫雲披素質，幾回赤氣掩桃顋。","微微笑處機關轉，拂拂行時戶牖開。","此是吾家真一子，庸愚誰敢等閑猜。"]', '["嬰兒迤邐降瑤階，手握玄珠直下来。","半夜紫云披素質，幾回赤氣掩桃顋。","微微笑处機关轉，拂拂行时戶牖开。","此是吾家真一子，庸愚誰敢等闲猜。"]', '诗', 'shi', '', NULL, '七言 三十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5341b9-3739-4834-a0e9-e61ecc3632fc', '七言 三十四', '七言 三十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["水得天符下玉都，三千日裏積功夫。","禱祈天地開金鼎，收拾陰陽鎖玉壺。","便覺凡軀能變化，深知妙道不虛圖。","時來試問塵中叟，這箇玄機世有無。"]', '["水得天符下玉都，三千日裏積功夫。","禱祈天地开金鼎，收拾陰陽鎖玉壺。","便覺凡軀能变化，深知妙道不虛圖。","时来試问塵中叟，這箇玄機世有無。"]', '诗', 'shi', '', NULL, '七言 三十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a13f67-7dbf-44fa-b92f-f38b2e5c43ae', '七言 三十五', '七言 三十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰識寰中達者人，生平解法水中銀。","一條拄杖撐天地，三尺昆吾斬鬼神。","大醉醉來眠月洞，高吟吟去傲紅塵。","自從悟裏終身後，贏得蓬壺永劫春。"]', '["誰識寰中達者人，生平解法水中銀。","一條拄杖撐天地，三尺昆吾斬鬼神。","大醉醉来眠月洞，高吟吟去傲紅塵。","自從悟裏終身後，贏得蓬壺永劫春。"]', '诗', 'shi', '', NULL, '七言 三十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42fe551-cfb6-44e6-bf9b-2f9a816202c2', '七言 三十六', '七言 三十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["紅爐迸濺煉金英，一點靈珠透室明。","擺動乾坤知道力，逃移生死見功程。","逍遙四海留蹤跡，歸去三清立姓名。","直上五雲雲路穩，紫鸞朱鳳自來迎。"]', '["紅爐迸濺煉金英，一点靈珠透室明。","擺动乾坤知道力，逃移生死见功程。","逍遙四海留蹤跡，归去三清立姓名。","直上五云云路穩，紫鸾朱鳳自来迎。"]', '诗', 'shi', '', NULL, '七言 三十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fcb9346-ceb3-4f45-b1b9-47f6dc8246fa', '七言 三十七', '七言 三十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["時人若要學長生，先是樞機晝夜行。","恍惚中間專志氣，虛無裏面固元精。","龍交虎戰三周畢，兔走烏飛九轉成。","煉出一爐神聖藥，五雲歸去路分明。"]', '["时人若要学长生，先是樞機晝夜行。","恍惚中间專志氣，虛無裏面固元精。","龙交虎戰三周畢，兔走烏飞九轉成。","煉出一爐神聖藥，五云归去路分明。"]', '诗', 'shi', '', NULL, '七言 三十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('171e02c6-af22-4eff-8db5-e0332d998365', '七言 三十八', '七言 三十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["亦無得失亦無言，動即施功靜即眠。","驅遣赤牛耕宇宙，分張玉粒種山川。","栽培不憚勞千日，服食須知活萬年。","今日示君君好信，教君見世作神仙。"]', '["亦無得失亦無言，动即施功静即眠。","驱遣赤牛耕宇宙，分張玉粒種山川。","栽培不憚勞千日，服食須知活万年。","今日示君君好信，教君见世作神仙。"]', '诗', 'shi', '', NULL, '七言 三十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fae0c8e-dff1-4a37-976a-ec14f4b1a591', '七言 三十九', '七言 三十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["不須兩兩與三三，秖在崑崙第一巖。","逢潤自然情易伏，遇炎常恐性難降。","有時直入三元戶，無事還歸九曲江。","世上有人燒得住，壽齊天地更無雙。"]', '["不須兩兩與三三，秖在崑崙第一巖。","逢潤自然情易伏，遇炎常恐性难降。","有时直入三元戶，無事還归九曲江。","世上有人燒得住，壽齊天地更無雙。"]', '诗', 'shi', '', NULL, '七言 三十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09198206-c93e-4bee-8d95-eceebb9593bb', '七言 四十', '七言 四十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["本末無非在玉都，亦曾陸地作凡夫。","吞金食氣先從有，悟理歸真便入無。","水火自然成既濟，陰陽和合自相符。","爐中煉出延年藥，溟渤從教變復枯。"]', '["本末無非在玉都，亦曾陸地作凡夫。","吞金食氣先從有，悟理归真便入無。","水火自然成既濟，陰陽和合自相符。","爐中煉出延年藥，溟渤從教变复枯。"]', '诗', 'shi', '', NULL, '七言 四十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbf524c-5151-487c-a235-4c6ed455bf66', '七言 四十一', '七言 四十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["無名無利任優游，遇酒逢歌且唱酬。","數載未曾經聖闕，千年唯只在仙州。","尋常水火三回進，真箇夫妻一處收。","藥就功成身羽化，更拋塵坌出凡流。"]', '["無名無利任優游，遇酒逢歌且唱酬。","數載未曾經聖闕，千年唯只在仙州。","尋常水火三回進，真箇夫妻一处收。","藥就功成身羽化，更拋塵坌出凡流。"]', '诗', 'shi', '', NULL, '七言 四十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eed8f68-baf3-4c63-b727-6bb2f581cc8e', '七言 四十二', '七言 四十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["杳杳冥冥莫問涯，雕蟲篆刻道之華。","守中絕學方知奧，抱一無言始見佳。","自有物如黃菊蘂，更無色似碧桃花。","休將心地虛勞用，煮鐵燒金轉轉差。"]', '["杳杳冥冥莫问涯，雕蟲篆刻道之华。","守中絕学方知奧，抱一無言始见佳。","自有物如黄菊蘂，更無色似碧桃花。","休將心地虛勞用，煮鐵燒金轉轉差。"]', '诗', 'shi', '', NULL, '七言 四十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55565fb7-5edc-49eb-b826-c4d572a14e74', '七言 四十三', '七言 四十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["還丹功滿未朝天，且向人間度有緣。","拄杖兩頭擔日月，葫蘆一箇隱山川。","詩吟自得閑中句，酒飲多遺醉後錢。","若問我修何妙法，不離身內汞和鉛。"]', '["還丹功满未朝天，且向人间度有緣。","拄杖兩头擔日月，葫蘆一箇隐山川。","诗吟自得闲中句，酒饮多遺醉後錢。","若问我修何妙法，不離身內汞和鉛。"]', '诗', 'shi', '', NULL, '七言 四十三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852da615-3172-4929-892b-5cd0c3380c31', '七言 四十四', '七言 四十四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["半紅半黑道中玄，水養真金火養鉛。","解接往年三寸氣，還將運動一周天。","烹煎盡在陰陽力，進退須憑日月權。","只此功成三島外，穩乘鸞鳳謁諸仙。"]', '["半紅半黑道中玄，水養真金火養鉛。","解接往年三寸氣，還將運动一周天。","烹煎尽在陰陽力，進退須憑日月權。","只此功成三島外，穩乘鸾鳳謁諸仙。"]', '诗', 'shi', '', NULL, '七言 四十四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e563c2-c1e6-43e0-99c4-d4f8e37aa37b', '七言 四十五', '七言 四十五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["返本還元已到乾，能升能降號飛仙。","一陽生是興功日，九轉周爲得道年。","煉藥但尋金裏水，安爐先立地中天。","此中便是還丹理，不遇奇人誓莫傳。"]', '["返本還元已到乾，能升能降號飞仙。","一陽生是兴功日，九轉周爲得道年。","煉藥但尋金裏水，安爐先立地中天。","此中便是還丹理，不遇奇人誓莫傳。"]', '诗', 'shi', '', NULL, '七言 四十五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975d3849-0609-44f8-a29f-c6b9c7f7d5a1', '七言 四十六', '七言 四十六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["飛龍九五已升天，次第還當赤帝權。","喜遇汞珠凝正午，幸逢鉛母結重玄。","狂猨自伏何須煉，野馬親調不着鞭。","煉就一丸天上藥，頓然心地永剛堅。"]', '["飞龙九五已升天，次第還當赤帝權。","喜遇汞珠凝正午，幸逢鉛母結重玄。","狂猨自伏何須煉，野马親調不着鞭。","煉就一丸天上藥，頓然心地永剛堅。"]', '诗', 'shi', '', NULL, '七言 四十六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250cebc9-a723-4018-b4be-fd42e133efa9', '七言 四十七', '七言 四十七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["舉世何人悟我家，我家別是一榮華。","盈箱貯積登仙錄，滿室收藏伏火砂。","頓飲長生天上酒，常栽不死洞中花。","凡流若問吾生計，遍地紛紛五彩霞。"]', '["舉世何人悟我家，我家別是一榮华。","盈箱貯積登仙錄，满室收藏伏火砂。","頓饮长生天上酒，常栽不死洞中花。","凡流若问吾生計，遍地紛紛五彩霞。"]', '诗', 'shi', '', NULL, '七言 四十七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84004c43-3d31-4688-a6da-b6dd15a637b2', '七言 四十八', '七言 四十八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["津能充渴氣充糧，家住三清玉帝鄉。","金鼎煉來多外白，玉虛烹處徹中黃。","始知青帝離宮住，方信金精水府藏。","流俗要求玄妙理，參同契有兩三行。"]', '["津能充渴氣充糧，家住三清玉帝乡。","金鼎煉来多外白，玉虛烹处徹中黄。","始知青帝離宮住，方信金精水府藏。","流俗要求玄妙理，參同契有兩三行。"]', '诗', 'shi', '', NULL, '七言 四十八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361c5ff1-87aa-465f-b4db-9217daf98380', '七言 四十九', '七言 四十九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["紫詔隨鸞下玉京，元君相命會三清。","便將金鼎丹砂餌，時拂霞衣駕鶴行。","天上雙童持珮引，月中嬌女執幡迎。","此時功滿參真後，始信仙都有姓名。"]', '["紫詔隨鸾下玉京，元君相命會三清。","便將金鼎丹砂餌，时拂霞衣駕鹤行。","天上雙童持珮引，月中嬌女執幡迎。","此时功满參真後，始信仙都有姓名。"]', '诗', 'shi', '', NULL, '七言 四十九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34451fa3-e895-4785-8b56-03843c1b3bf2', '七言 五十', '七言 五十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["修修修得到乾乾，方號人間一醉仙。","世上光陰催短景，洞中花木任長年。","形飛峭壁非凡骨，神在玄宮別有天。","唯願先生頻一顧，更玄玄外問玄玄。"]', '["修修修得到乾乾，方號人间一醉仙。","世上光陰催短景，洞中花木任长年。","形飞峭壁非凡骨，神在玄宮別有天。","唯願先生頻一顧，更玄玄外问玄玄。"]', '诗', 'shi', '', NULL, '七言 五十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75b78105-5b2b-491e-90ab-c582e418c060', '七言 一', '七言 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["金丹一粒定長生，須得真鉛煉甲庚。","火取南方赤鳳髓，水求北海黑龜精。","鼎追四季中央合，藥遣三元八卦行。","齋戒興功成九轉，定應入口鬼神驚。"]', '["金丹一粒定长生，須得真鉛煉甲庚。","火取南方赤鳳髓，水求北海黑龟精。","鼎追四季中央合，藥遣三元八卦行。","斋戒兴功成九轉，定應入口鬼神驚。"]', '诗', 'shi', '', NULL, '七言 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c422aa-60cf-4e6c-b0a6-215819287752', '七言 二', '七言 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["功滿來來際會難，又聞東去上仙壇。","杖頭春色一壺酒，頂上雲攢五嶽冠。","飲酒龜兒人不識，燒山符子鬼難看。","先生去後身須老，乞與貧儒換骨丹。"]', '["功满来来際會难，又闻东去上仙壇。","杖头春色一壺酒，頂上云攢五嶽冠。","饮酒龟兒人不識，燒山符子鬼难看。","先生去後身須老，乞與貧儒換骨丹。"]', '诗', 'shi', '', NULL, '七言 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30df7a37-f0e3-4aff-b0c1-7c597353bbc4', '七言 三', '七言 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["碧潭深處一真人，貌似桃花體似銀。","鬢髮未斑緣有術，紅顏不老爲通神。","蓬萊要去如今去，架上黃衣化作雲。","任彼桑田變滄海，一丸丹藥定千春。"]', '["碧潭深处一真人，貌似桃花體似銀。","鬢髮未斑緣有術，紅顏不老爲通神。","蓬萊要去如今去，架上黄衣化作云。","任彼桑田变滄海，一丸丹藥定千春。"]', '诗', 'shi', '', NULL, '七言 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb604590-292d-4f18-b410-ac7e4a59faaa', '七言 四', '七言 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["爐養丹砂鬢不斑，假將名利住人間。","已逢志士傳神藥，又喜同流動笑顏。","老子道經分付得，少微星許共相攀。","幸蒙上士甘撈摝，處世輸君一箇閑。"]', '["爐養丹砂鬢不斑，假將名利住人间。","已逢志士傳神藥，又喜同流动笑顏。","老子道經分付得，少微星許共相攀。","幸蒙上士甘撈摝，处世輸君一箇闲。"]', '诗', 'shi', '', NULL, '七言 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fcf0f86-c05f-436c-af0d-5244a0718c29', '七言 五', '七言 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰解長生似我哉，煉成真氣在三台。","盡知白日昇天去，剛逐紅塵下世來。","黑虎行時傾雨露，赤龍耕處產瓊瑰。","只吞一粒金丹藥，飛入青霄更不回。"]', '["誰解长生似我哉，煉成真氣在三台。","尽知白日昇天去，剛逐紅塵下世来。","黑虎行时傾雨露，赤龙耕处產瓊瑰。","只吞一粒金丹藥，飞入青霄更不回。"]', '诗', 'shi', '', NULL, '七言 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad99d88-cd3c-45eb-a142-f1cad0d3abe4', '七言 六', '七言 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["亂雲堆裏表星都，認得深藏大丈夫。","綠酒醉眠閑日月，白蘋風定釣江湖。","長將氣度隨天道，不把言詞問世徒。","山水路遙人不到，茅君消息近知無。"]', '["亂云堆裏表星都，認得深藏大丈夫。","綠酒醉眠闲日月，白蘋风定釣江湖。","长將氣度隨天道，不把言词问世徒。","山水路遙人不到，茅君消息近知無。"]', '诗', 'shi', '', NULL, '七言 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090618be-ceee-488b-9d88-35e74112b482', '七言 七', '七言 七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鶴爲車駕酒爲糧，爲戀長生不死鄉。","地脉尚能縮得短，人年豈不展教長。","星辰往往壺中見，日月時時衲裏藏。","若欲時流親得見，朝朝不離水銀行。"]', '["鹤爲车駕酒爲糧，爲戀长生不死乡。","地脉尚能縮得短，人年豈不展教长。","星辰往往壺中见，日月时时衲裏藏。","若欲时流親得见，朝朝不離水銀行。"]', '诗', 'shi', '', NULL, '七言 七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693a6c14-336f-440e-beae-c2c41c72bbc8', '七言 八', '七言 八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["靈芝無種亦無根，解飲能餐自返魂。","但得煙霞供歲月，任他烏兔走乾坤。","嬰兒只戀陽中母，姹女須朝頂上尊。","一得不回千古內，更無塚墓示兒孫。"]', '["靈芝無種亦無根，解饮能餐自返魂。","但得煙霞供歲月，任他烏兔走乾坤。","嬰兒只戀陽中母，姹女須朝頂上尊。","一得不回千古內，更無塚墓示兒孫。"]', '诗', 'shi', '', NULL, '七言 八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e192b0-074d-449f-af11-cd0bf3c26c2c', '七言 九', '七言 九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["世上何人會此言，休將名利挂心田。","等閑倒盡十分酒，遇興高吟一百篇。","物外煙霞爲伴侶，壺中日月任嬋娟。","他時功滿歸何處，直駕雲車入洞天。"]', '["世上何人會此言，休將名利挂心田。","等闲倒尽十分酒，遇兴高吟一百篇。","物外煙霞爲伴侶，壺中日月任嬋娟。","他时功满归何处，直駕云车入洞天。"]', '诗', 'shi', '', NULL, '七言 九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ac05e3-fe5b-4505-895a-3c9681d74a00', '七言 十', '七言 十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["玄門帝子坐中央，得算明長感玉皇。","枕上山河和雨露，笛中日月混瀟湘。","坎男會遇逢金女，離女交騰嫁木郎。","真箇夫妻齊守志，立教牽惹在陰陽。"]', '["玄门帝子坐中央，得算明长感玉皇。","枕上山河和雨露，笛中日月混瀟湘。","坎男會遇逢金女，離女交腾嫁木郎。","真箇夫妻齊守志，立教牽惹在陰陽。"]', '诗', 'shi', '', NULL, '七言 十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5738735e-c6ed-4818-b7ea-935a3e688988', '七言 十一', '七言 十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["遙指高峰笑一聲，紅霞紫霧面前生。","每於廛市無人識，長到山中有鶴行。","時弄玉蟾驅鬼魅，夜煎金鼎煮瓊英。","他時若赴蓬萊洞，知我仙家有姓名。"]', '["遙指高峰笑一声，紅霞紫霧面前生。","每於廛市無人識，长到山中有鹤行。","时弄玉蟾驱鬼魅，夜煎金鼎煮瓊英。","他时若赴蓬萊洞，知我仙家有姓名。"]', '诗', 'shi', '', NULL, '七言 十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2bbee1e-1acd-4655-a30d-a027f8304349', '七言 十二', '七言 十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["堪笑時人問我家，杖擔雲物惹煙霞。","眉藏火電非他說，手種金蓮不自誇。","三尺焦桐爲活計，一壺美酒是生涯。","騎龍遠出遊三島，夜久無人翫月華。"]', '["堪笑时人问我家，杖擔云物惹煙霞。","眉藏火電非他说，手種金蓮不自誇。","三尺焦桐爲活計，一壺美酒是生涯。","騎龙远出游三島，夜久無人翫月华。"]', '诗', 'shi', '', NULL, '七言 十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56dc9b8-3c26-4a30-8d81-f087050c3fa2', '七言 十三', '七言 十三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["九曲江邊坐臥看，一條長路入天端。","慶雲捧擁朝丹闕，瑞氣裴回起白煙。","鉛汞此時爲至藥，坎離今日結神丹。","功能濟命長無老，只在人心不是難。"]', '["九曲江邊坐臥看，一條长路入天端。","慶云捧擁朝丹闕，瑞氣裴回起白煙。","鉛汞此时爲至藥，坎離今日結神丹。","功能濟命长無老，只在人心不是难。"]', '诗', 'shi', '', NULL, '七言 十三 呂巖 shi');
